INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5020021216', 'Carina Curto', 'Brown', 'Machine Learning', 'ccurto@psu.edu', 'Attractor-based models for sequences and pattern generation in neural circuits', 'of neural activity. In this dissertation, we are focused on the general problem of how neural circuits encode rhythmic activity, as in central pattern generators (CPGs), as well as the encoding of sequences. Traditionally, rhythmic activity and CPGs have been modeled using coupled oscillators. Here we take a different approach, and present models for several different neural functions using threshold-linear networks. Our approach aims to unify attractor-based models (e.g., Hopfield networks) which encode static and dynamic patterns as attractors of the network. In the first half of this dissertation, we present several attractor-based models. These include: a network that can count the number of external inputs it receives; two models for locomotion, one encoding five different quadruped gaits and another encoding the orientation system of a swimming mollusk; and, finally, a model that connects the fixed point sequences with locomotion attractors to obtain a network that steps through a sequence of dynamic attractors. In the second half of the thesis, we present new theoretical results, some of which have already been published in [59]. There, we established conditions on network architectures to produce sequential attractors. Here we also include several new theorems relating the fixed points of composite networks to those of their component subnetworks, as well as a new architecture for layering networks which produces "fusion" attractors by minimizing interference between ', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100722237', 'Chen Sun', 'Brown', 'Machine Learning', 'chensun@brown.edu', 'Analyzing Modular Approaches for Visual Question Decomposition', 'Modular neural networks without additional training have recently been shown to surpass end-to-end neural networks on challenging vision–language tasks. The latest such methods simultaneously introduce LLM-based code generation to build programs and a number of skill-specific, task-oriented modules to execute them. In this paper, we focus on ViperGPT and ask where its additional performance comes from and how much is due to the (state-of-art, end-to-end) BLIP-2 model it subsumes vs. additional symbolic components. To do so, we conduct a controlled study (comparing end-to-end, modular, and prompting-based methods across several VQA benchmarks). We find that ViperGPT’s reported gains over BLIP-2 can be attributed to its selection of task-specific modules, and when we run ViperGPT using a more task-agnostic selection of modules, these gains go away. ViperGPT retains much of its performance if we make prominent alterations to its selection of modules: e.g. removing or retaining only BLIP-2. We also compare ViperGPT against a prompting-based decomposition strategy and find that, on some benchmarks, modular approaches significantly benefit by representing subtasks with natural language, instead of code. Our code is fully available at https://github.com/brown-palm/visual-question-decomposition.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5059267221', 'Daniel Ritchie', 'Brown', 'Machine Learning', 'daniel_ritchie@brown.edu', 'Improving Unsupervised Visual Program Inference with Code Rewriting Families', 'Programs offer compactness and structure that makes them an attractive representation for visual data. We explore how code rewriting can be used to improve systems for inferring programs from visual data. We first propose Sparse Intermittent Rewrite Injection (SIRI), a framework for unsupervised bootstrapped learning. SIRI sparsely applies code rewrite operations over a dataset of training programs, injecting the improved programs back into the training set. We design a family of rewriters for visual programming domains: parameter optimization, code pruning, and code grafting. For three shape programming languages in 2D and 3D, we show that using SIRI with our family of rewriters improves performance: better reconstructions and faster convergence rates, compared with bootstrapped learning methods that do not use rewriters or use them naively. Finally, we demonstrate that our family of rewriters can be effectively used at test time to improve the output of SIRI predictions. For 2D and 3D CSG, we outperform or match the reconstruction performance of recent domain-specific neural architectures, while producing more parsimonious programs, that use significantly fewer primitives.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5008164172', 'David Badre', 'Brown', 'Machine Learning', 'david_badre@brown.edu', 'A transient high-dimensional geometry affords stable conjunctive subspaces for efficient action selection', 'Flexible action selection requires cognitive control mechanisms capable of mapping the same inputs to different output actions depending on the context. From a neural state-space perspective, this requires a control representation that separates similar input neural states by context. Additionally, for action selection to be robust and time-invariant, information must be stable in time, enabling efficient readout. Here, using EEG decoding methods, we investigate how the geometry and dynamics of control representations constrain flexible action selection in the human brain. Participants performed a context-dependent action selection task. A forced response procedure probed action selection different states in neural trajectories. The result shows that before successful responses, there is a transient expansion of representational dimensionality that separated conjunctive subspaces. Further, the dynamics stabilizes in the same time window, with entry into this stable, high-dimensional state predictive of individual trial performance. These results establish the neural geometry and dynamics the human brain needs for flexible control over behavior. People can choose the correct actions to perform in a context-dependent way. Here, the authors show that this ability requires reaching a target brain state just prior to the response that encodes all task-relevant features in an integrated, high-dimensional, and temporally stable neural subspace.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040257276', 'David Paulius', 'Brown', 'Machine Learning', 'dpaulius@cs.brown.edu', 'CAPE: Corrective Actions from Precondition Errors using Large Language Models', 'Extracting knowledge and reasoning from large language models (LLMs) offers a path to designing intelligent robots. Common approaches that leverage LLMs for planning are unable to recover when actions fail and resort to retrying failed actions without resolving the underlying cause. We propose a novel approach (CAPE) that generates corrective actions to resolve precondition errors during planning. CAPE improves the quality of generated plans through few-shot reasoning on action preconditions. Our approach enables embodied agents to execute more tasks than baseline methods while maintaining semantic correctness and minimizing re-prompting. In VirtualHome, CAPE improves a human-annotated plan correctness metric from 28.89% to 49.63% over SayCan, whilst achieving competitive executability. Our improvements transfer to a Boston Dynamics Spot robot initialized with a set of skills (specified in language) and associated preconditions, where CAPE improves correctness by 76.49% with higher executability compared to SayCan. Our approach enables embodied agents to follow natural language commands and robustly recover from failures.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5128308654', 'George Em Karniadakis', 'Brown', 'Machine Learning', 'george_karniadakis@brown.edu', 'A variational framework for residual-based adaptivity in neural PDE solvers and operator learning', 'Residual-based adaptive strategies are widely used in scientific machine learning yet remain largely heuristic. We introduce a variational framework that formalizes these methods through convex transformations of the residual, where different transformations correspond to distinct objective functionals. For instance, exponential weights target uniform error minimization, while linear weights recover quadratic error minimization. This perspective reveals adaptive weighting as a means of selecting sampling distributions that optimize a primal objective, directly linking discretization choices to error metrics. This principled approach yields three key benefits: it enables systematic design of adaptive schemes, reduces discretization error by lowering estimator variance, and enhances learning dynamics by improving gradient signal-to-noise ratio. Extending the framework to operator learning, we demonstrate substantial performance gains across diverse optimizers and architectures. Our results provide a theoretical perspective for residual-based adaptivity and establish a foundation for principled discretization and training.', 2026);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5009658255', 'George Em Karniadakis', 'Brown', 'Machine Learning', 'george_karniadakis@brown.edu', 'HOW IMPORTANT ARE ACTIVATION FUNCTIONS IN REGRESSION AND CLASSIFICATION? A SURVEY, PERFORMANCE COMPARISON, AND FUTURE DIRECTIONS', 'Inspired by biological neurons, the activation functions play an essential part in the learning process of any artificial neural network (ANN) commonly used in many real-world problems. Various activation functions have been proposed in the literature for classification as well as regression tasks. In this work, we survey the activation functions that have been employed in the past as well as the current state-of-the-art. In particular, we present various developments in activation functions over the years and the advantages as well as disadvantages or limitations of these activation functions. We also discuss classical (fixed) activation functions, including rectifier units, and adaptive activation functions. In addition to discussing the taxonomy of activation functions based on characterization, a taxonomy of activation functions based on applications is presented. To this end, the systematic comparison of various fixed and adaptive activation functions is performed for classification datasets such as MNIST, CIFAR-10, and CIFAR-100. In recent years, a physics-informed machine learning framework has emerged for solving problems related to scientific computations. For this purpose, we also discuss various requirements for activation functions that have been used in the physics-informed machine learning framework. Furthermore, various comparisons are made among different fixed and adaptive activation functions using various machine learning libraries such as TensorFlow, PyTor', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5078124517', 'George Konidaris', 'Brown', 'Machine Learning', 'gdk@cs.brown.edu', 'Generalizing to New Domains by Mapping Natural Language to Lifted LTL', 'Recent work on using natural language to specify commands to robots has grounded that language to LTL. However, mapping natural language task specifications to LTL task specifications using language models require probability distributions over finite vocabulary. Existing state-of-the-art methods have extended this finite vocabulary to include unseen terms from the input sequence to improve output generalization. However, novel out-of-vocabulary atomic propositions cannot be generated using these methods. To overcome this, we introduce an intermediate contextual query representation which can be learned from single positive task specification examples, associating a contextual query with an LTL template. We demonstrate that this intermediate representation allows for generalization over unseen object references, assuming accurate groundings are available. We compare our method of mapping natural language task specifications to intermediate contextual queries against state-of-the-art CopyNet models capable of translating natural language to LTL, by evaluating whether correct LTL for manipulation and navigation task specifications can be output, and show that our method outperforms the CopyNet model on unseen object references. We demonstrate that the grounded LTL our method outputs can be used for planning in a simulated OO-MDP environment. Finally, we discuss some common failure modes encountered when translating natural language task specifications to grounded LTL.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5029666654', 'John P. Donoghue', 'Brown', 'Machine Learning', 'john_donoghue@brown.edu', 'Mapping the computational similarity of individual neurons within large-scale ensemble recordings using the SIMNETS analysis framework', 'The expansion of large-scale neural recording capabilities has provided new opportunities to examine multi-scale cortical network activity at single neuron resolution. At the same time, the growing scale and complexity of these datasets introduce new conceptual and technical challenges beyond what can be addressed using traditional analysis techniques. Here, we present the Similarity Networks (SIMNETS) analysis framework: an efficient and scalable pipeline designed to embed simultaneously recorded neurons into low dimensional maps according to the intrinsic relationship between their spike trains, making it possible to identify and visualize groups of neurons performing similar computations. The critical innovation is the use of pairwise spike train similarity (SSIM) matrices to capture the intrinsic relationship between the spike trains emitted by a neuron at different points in time (i.e., different experimental conditions), reflecting how the neuron responds to time-varying internal and external drives and making it possible to easily compare the information processing properties across neuronal populations. We use three publicly available neural population test datasets from the visual, motor, and hippocampal CA1 brain regions to validate the SIMNETS framework and demonstrate how it can be used to identify putative subnetworks (i.e., clusters of neurons with similar computational properties). Our analysis pipeline includes a novel statistical test designed to evaluate the', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5023997413', 'Luca Mossina', 'Brown', 'Machine Learning', 'luca.mossina@irt-saintexupery.com', 'Confident Object Detection via Conformal Prediction and Conformal Risk Control: an Application to Railway Signaling', 'Deploying deep learning models in real-world certified systems requires the ability to provide confidence estimates that accurately reflect their uncertainty. In this paper, we demonstrate the use of the conformal prediction framework to construct reliable and trustworthy predictors for detecting railway signals. Our approach is based on a novel dataset that includes images taken from the perspective of a train operator and state-of-the-art object detectors. We test several conformal approaches and introduce a new method based on conformal risk control. Our findings demonstrate the potential of the conformal prediction framework to evaluate model performance and provide practical guidance for achieving formally guaranteed uncertainty bounds.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5007609257', 'Michael J. Frank', 'Brown', 'Machine Learning', 'michael_frank@brown.edu', 'Beyond gradients: Factorized, geometric control of interference and generalization', 'Abstract Interference and generalization, which refer to counter-productive and useful interactions between learning episodes, respectively, are poorly understood in biological neural networks. Whereas much previous work has addressed these topics in terms of specialized brain systems, here we investigated how learning rules should impact them. We found that plasticity between groups of neurons can be decomposed into biologically meaningful factors, with factor geometry controlling interference and generalization. We introduce a “coordinated eligibility theory” in which plasticity is determined according to products of these factors, and is subject to surprise-based metaplasticity. This model computes directional derivatives of loss functions, which need not align with task gradients, allowing it to protect networks against catastrophic interference and facilitate generalization. Because the model’s factor structure is closely related to other plasticity rules, and is independent of how feedback is transmitted, it introduces a widely-applicable framework for interpreting supervised, reinforcement-based, and unsupervised plasticity in nervous systems.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5010250162', 'Miguel A. Bessa', 'Brown', 'Machine Learning', 'miguel_bessa@brown.edu', 'Continual prune-and-select: class-incremental learning with specialized subnetworks', 'The human brain is capable of learning tasks sequentially mostly without forgetting. However, deep neural networks (DNNs) suffer from catastrophic forgetting when learning one task after another. We address this challenge considering a class-incremental learning scenario where the DNN sees test data without knowing the task from which this data originates. During training, Continual Prune-and-Select (CP&S) finds a subnetwork within the DNN that is responsible for solving a given task. Then, during inference, CP&S selects the correct subnetwork to make predictions for that task. A new task is learned by training available neuronal connections of the DNN (previously untrained) to create a new subnetwork by pruning, which can include previously trained connections belonging to other subnetwork(s) because it does not update shared connections. This enables to eliminate catastrophic forgetting by creating specialized regions in the DNN that do not conflict with each other while still allowing knowledge transfer across them. The CP&S strategy is implemented with different subnetwork selection strategies, revealing superior performance to state-of-the-art continual learning methods tested on various datasets (CIFAR-100, CUB-200-2011, ImageNet-100 and ImageNet-1000). In particular, CP&S is capable of sequentially learning 10 tasks from ImageNet-1000 keeping an accuracy around 94% with negligible forgetting, a first-of-its-kind result in class-incremental learning. To the best of the ', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5063866156', 'Peipei Zhou', 'Brown', 'Machine Learning', 'peipei.zhou@pitt.edu', 'EQ-ViT: Algorithm-Hardware Co-Design for End-to-End Acceleration of Real-Time Vision Transformer Inference on Versal ACAP Architecture', 'While Vision Transformers (ViTs) have shown consistent progress in computer vision, deploying them for real-time decision-making scenarios (< 1 ms) is challenging. Current computing platforms like CPUs, GPUs, or FPGA-based solutions struggle to meet this deterministic low-latency real-time requirement, even with quantized ViT models. Some approaches use pruning or sparsity to reduce model size and latency, but this often results in accuracy loss. To address the aforementioned constraints, in this work, we propose EQ-ViT, an end-to-end acceleration framework with novel algorithm and architecture co-design features to enable real-time ViT acceleration on AMD Versal Adaptive Compute Acceleration Platform (ACAP). The contributions are four-fold. First, we perform in-depth kernel-level performance profiling & analysis and explain the bottlenecks for existing acceleration solutions on GPU, FPGA, and ACAP. Second, on the hardware level, we introduce a new spatial and heterogeneous accelerator architecture, EQ-ViT architecture. This architecture leverages the heterogeneous features of ACAP, where both FPGA and artificial intelligence engines (AIEs) coexist on the same system-on-chip (SoC). Third, On the algorithm level, we create a comprehensive quantization-aware training strategy, EQ-ViT algorithm. This strategy concurrently quantizes both weights and activations into 8-bit integers, aiming to improve accuracy rather than compromise it during quantization. Notably, the method also ', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5031008694', 'Reshma Munbodh', 'Brown', 'Machine Learning', 'reshma.munbodh@yale.edu', 'Clinical capability of modern brain tumor segmentation models', 'PURPOSE: State-of-the-art automated segmentation methods achieve exceptionally high performance on the Brain Tumor Segmentation (BraTS) challenge, a dataset of uniformly processed and standardized magnetic resonance generated images (MRIs) of gliomas. However, a reasonable concern is that these models may not fare well on clinical MRIs that do not belong to the specially curated BraTS dataset. Research using the previous generation of deep learning models indicates significant performance loss on cross-institutional predictions. Here, we evaluate the cross-institutional applicability and generalzsability of state-of-the-art deep learning models on new clinical data. METHODS: We train a state-of-the-art 3D U-Net model on the conventional BraTS dataset comprising low- and high-grade gliomas. We then evaluate the performance of this model for automatic tumor segmentation of brain tumors on in-house clinical data. This dataset contains MRIs of different tumor types, resolutions, and standardization than those found in the BraTS dataset. Ground truth segmentations to validate the automated segmentation for in-house clinical data were obtained from expert radiation oncologists. RESULTS: We report average Dice scores of 0.764, 0.648, and 0.61 for the whole tumor, tumor core, and enhancing tumor, respectively, in the clinical MRIs. These means are higher than numbers reported previously on same institution and cross-institution datasets of different origin using different methods. Th', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5070578596', 'Ritambhara Singh', 'Brown', 'Machine Learning', 'ritambhara@brown.edu', 'BetaExplainer: A Probabilistic Method to Explain Graph Neural Networks', 'Graph neural networks (GNNs) are powerful tools for conducting inference on graph data but are often seen as “black boxes" due to difficulty in extracting meaningful subnetworks driving predictive performance. Many interpretable GNN methods exist, but they cannot quantify uncertainty in edge weights and suffer in predictive accuracy when applied to challenging graph structures. In this work, we proposed BetaExplainer which addresses these issues by using a sparsity-inducing prior to mask unimportant edges during model training. To evaluate our approach, we examine various simulated data sets with diverse real-world characteristics. Not only does this implementation provide a notion of edge importance uncertainty, it also improves upon evaluation metrics for challenging datasets compared to state-of-the art explainer methods.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5015719218', 'Sherief Reda', 'Brown', 'Machine Learning', 'sherief_reda@brown.edu', 'MTLoRA: A Low-Rank Adaptation Approach for Efficient Multi-Task Learning', 'Adapting models pre-trained on large-scale datasets to a variety of downstream tasks is a common strategy in deep learning. Consequently, parameter-efficient fine-tuning methods have emerged as a promising way to adapt pretrained models to different tasks while training only a minimal number of parameters. While most of these methods are designed for single-task adaptation, parameter-efficient training in Multi-Task Learning (MTL) architectures is still unexplored. In this paper, we introduce MTLoRA, a novel framework for parameter-efficient training of MTL models. MTLoRA employs Task-Agnostic and Task-Specific Low-Rank Adaptation modules, which effectively disentangle the parameter space in MTL fine-tuning, thereby enabling the model to adeptly handle both task specialization and interaction within MTL contexts. We applied MTLoRA to hierarchical-transformer-based MTL architectures, adapting them to multiple downstream dense prediction tasks. Our extensive experiments on the PASCAL dataset show that MTLoRA achieves higher accuracy on downstream tasks compared to fully fine-tuning the MTL model while reducing the number of trainable parameters by 3.6×. Furthermore, MTLoRA establishes a Pareto-optimal trade-off between the number of trainable parameters and the accuracy of the downstream tasks, outperforming current state-of-the-art parameter-efficient training methods in both accuracy and efficiency. Our code is publicly available.11https://github.com/scale-lab/MTLoRA.git', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5059273574', 'Stefanie Tellex', 'Brown', 'Machine Learning', 'stefanie_tellex@brown.edu', 'Plug in the Safety Chip: Enforcing Constraints for LLM-driven Robot Agents', 'Recent advancements in large language models (LLMs) have enabled a new research domain, LLM agents, for solving robotics and planning tasks by leveraging the world knowledge and general reasoning abilities of LLMs obtained during pretraining. However, while considerable effort has been made to teach the robot the "dos", the "don’ts" received relatively less attention. We argue that, for any practical usage, it is as crucial to teach the robot the "don’ts": conveying explicit instructions about prohibited actions, assessing the robot’s comprehension of these restrictions, and, most importantly, ensuring compliance. Moreover, verifiable safe operation is essential for deployments that satisfy worldwide standards such as ISO 61508, which defines standards for safely deploying robots in industrial factory environments worldwide. Aiming at deploying the LLM agents in a collaborative environment, we propose a queryable safety constraint module based on linear temporal logic (LTL) that simultaneously enables natural language (NL) to temporal constraints encoding, safety violation reasoning and explaining, and unsafe action pruning. To demonstrate the effectiveness of our system, we conducted experiments in VirtualHome environment and on a real robot. The experimental results show that our system strictly adheres to the safety constraints and scales well with complex safety constraints, highlighting its potential for practical utility.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5018626055', 'T. Serre', 'Brown', 'Machine Learning', 'thomas_serre@brown.edu', 'How Good is your Explanation? Algorithmic Stability Measures to Assess the Quality of Explanations for Deep Neural Networks', 'A plethora of methods have been proposed to explain how deep neural networks reach their decisions but comparatively, little effort has been made to ensure that the explanations produced by these methods are objectively relevant. While several desirable properties for trustworthy explanations have been formulated, objective measures have been harder to derive. Here, we propose two new measures to evaluate explanations borrowed from the field of algorithmic stability: mean generalizability MeGe and relative consistency ReCo. We conduct extensive experiments on different network architectures, common explainability methods, and several image datasets to demonstrate the benefits of the proposed measures. In comparison to ours, popular fidelity measures are not sufficient to guarantee trustworthy explanations. Finally, we found that 1-Lipschitz networks produce explanations with higher MeGe and ReCo than common neural networks while reaching similar accuracy. This suggests that 1-Lipschitz networks are a relevant direction towards predictors that are more explainable and trustworthy.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5038126740', 'Vikas Srivastava', 'Brown', 'Machine Learning', 'vikas_srivastava@brown.edu', 'Drug release modeling using Physics-Informed Neural Networks', 'Accurate modeling of drug release is essential for designing and developing controlled-release systems. Classical models (Fick, Higuchi, Peppas) rely on simplifying assumptions that limit their accuracy in complex geometries and release mechanisms. Here, we propose a novel approach using Physics-Informed Neural Networks (PINNs) and Bayesian PINNs (BPINNs) for predicting drug release from complex geometries using planar, 1D-wrinkled, and 2D-crumpled films as examples. This approach uniquely integrates Fick’s diffusion law with limited and sparse experimental data to enable accurate long-term predictions from short-term measurements, and is systematically benchmarked against classical drug release models. We incorporated Fick’s second law into the PINN framework as a soft constraint being satisfied at randomly sampled collocation points. Previously published sparse experimental datasets are then used to evaluate drug release performance using mean absolute error (MAE) and root mean square error (RMSE), accounting for noisy conditions and limited data availability. Our approach reduced mean error by up to 40% relative to classical baselines across all film types. The PINN formulation achieved RMSE < 0.05 utilizing only the first 6% of the release time data (reducing 94% of release time required for the experiments) for the planar film. For wrinkled and crumpled films, the PINN reached RMSE < 0.05 in 33% of the release time data. BPINNs provide tighter and more reliable uncertain', 2026);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040366534', 'William H. Warren', 'Brown', 'Machine Learning', 'bill_warren@brown.edu', 'How many moving obstacles do we respond to at once? A temporal threshold model best accounts for collision avoidance in a crowd', 'On our daily commutes, we seamlessly weave through crowds, avoiding potential collisions with multiple pedestrians. How do we prioritize which obstacles to avoid? It is possible that we respond to the nearest N obstacles (topological threshold), or all obstacles within a temporal range (visual threshold). We previously described a visual model in which the risk of collision is specified by an obstacle’s change in bearing direction (|ψ''|), and the imminence of collision is specified by its optical expansion (θ''). Here we investigate the number of obstacles avoided by manipulating the visual threshold on (θ''⋅|ψ''|). In a VR experiment, participants avoided one, two, or three moving avatars (1.1m/s), which crossed their path (±112.5°) while walking toward a goal (11m). We compared models with four different thresholds, measuring error as the mean distance between model and human positions: (1) A visual threshold fit to multiple obstacles had the lowest error (θ ''⋅|ψ''| = 0.20 deg/s, M = 0.381m, Mdn = 0.267m). (2) A topological threshold for the single next obstacle had the next highest error (θ''⋅|ψ''| = 0.03 deg/s, M = 0.422m, Mdn = 0.298m). (3) A topological threshold for the next two obstacles had even higher error (θ''⋅|ψ''| = 0.03 deg/s, M = 0.463m, Mdn = 0.323m). (4) Our previous visual threshold fit to collisions with a single obstacle had the worst performance (θ''⋅|ψ''| = 0.03 deg/s, M = 0.477m, Mdn = 0.331m). We then simulated previous data on a participant walking through a c', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5052716839', 'Zhicheng Jiao', 'Brown', 'Machine Learning', 'zhicheng_jiao@brown.edu', 'AC-E Network: Attentive Context-Enhanced Network for Liver Segmentation', 'Segmentation of liver from CT scans is essential in computer-aided liver disease diagnosis and treatment. However, the 2DCNN ignores the 3D context, and the 3DCNN suffers from numerous learnable parameters and high computational cost. In order to overcome this limitation, we propose an Attentive Context-Enhanced Network (AC-E Network) consisting of 1) an attentive context encoding module (ACEM) that can be integrated into the 2D backbone to extract 3D context without a sharp increase in the number of learnable parameters; 2) a dual segmentation branch including complemental loss making the network attend to both the liver region and boundary so that getting the segmented liver surface with high accuracy. Extensive experiments on the LiTS and the 3D-IRCADb datasets demonstrate that our method outperforms existing approaches and is competitive to the state-of-the-art 2D-3D hybrid method on the equilibrium of the segmentation precision and the number of model parameters.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5012791383', 'Chunhao Wang', 'Duke', 'Machine Learning', 'chunhao.wang@duke.edu', 'Quantifying U‐Net uncertainty in multi‐parametric MRI‐based glioma segmentation by spherical image projection', 'BACKGROUND: Uncertainty quantification in deep learning is an important research topic. For medical image segmentation, the uncertainty measurements are usually reported as the likelihood that each pixel belongs to the predicted segmentation region. In potential clinical applications, the uncertainty result reflects the algorithm''s robustness and supports the confidence and trust of the segmentation result when the ground-truth result is absent. For commonly studied deep learning models, novel methods for quantifying segmentation uncertainty are in demand. PURPOSE: To develop a U-Net segmentation uncertainty quantification method based on spherical image projection of multi-parametric MRI (MP-MRI) in glioma segmentation. METHODS: The projection of planar MRI data onto a spherical surface is equivalent to a nonlinear image transformation that retains global anatomical information. By incorporating this image transformation process in our proposed spherical projection-based U-Net (SPU-Net) segmentation model design, multiple independent segmentation predictions can be obtained from a single MRI. The final segmentation is the average of all available results, and the variation can be visualized as a pixel-wise uncertainty map. An uncertainty score was introduced to evaluate and compare the performance of uncertainty measurements. The proposed SPU-Net model was implemented on the basis of 369 glioma patients with MP-MRI scans (T1, T1-Ce, T2, and FLAIR). Three SPU-Net models were ', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040468715', 'Cynthia Rudin', 'Duke', 'Machine Learning', 'cynthia@cs.duke.edu', 'Exploring the Whole Rashomon Set of Sparse Decision Trees', 'is the set of these all almost-optimal models. Rashomon sets can be large in size and complicated in structure, particularly for highly nonlinear function classes that allow complex interaction terms, such as decision trees. We provide the first technique for completely enumerating the Rashomon set for sparse decision trees; in fact, our work provides the first complete enumeration of any Rashomon set for a non-trivial problem with a highly nonlinear discrete function class. This allows the user an unprecedented level of control over model choice among all models that are approximately equally good. We represent the Rashomon set in a specialized data structure that supports efficient querying and sampling. We show three applications of the Rashomon set: 1) it can be used to study variable importance for the set of almost-optimal trees (as opposed to a single tree), 2) the Rashomon set for accuracy enables enumeration of the Rashomon sets for balanced accuracy and F1-score, and 3) the Rashomon set for a full dataset can be used to produce Rashomon sets constructed with only subsets of the data set. Thus, we are able to examine Rashomon sets across problems with a new lens, enabling users to choose models rather than be at the mercy of an algorithm that produces only a single model.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5020392456', 'Daniel Reker', 'Duke', 'Machine Learning', 'daniel.reker@duke.edu', 'Improving molecular machine learning through adaptive subsampling with active learning', 'Active machine learning can be used to sample training data in an autonomous manner to improve machine learning performance. This approach is competitive with state-of-the-art data sampling approaches, especially on erroneous data.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5087182068', 'Debmalya Panigrahi', 'Duke', 'Machine Learning', 'debmalya@cs.duke.edu', 'Customizing ML Predictions for Online Algorithms', 'A popular line of recent research incorporates ML advice in the design of online algorithms to improve their performance in typical instances. These papers treat the ML algorithm as a black-box, and redesign online algorithms to take advantage of ML predictions. In this paper, we ask the complementary question: can we redesign ML algorithms to provide better predictions for online algorithms? We explore this question in the context of the classic rent-or-buy problem, and show that incorporating optimization benchmarks in ML loss functions leads to significantly better performance, while maintaining a worst-case adversarial result when the advice is completely wrong. We support this finding both through theoretical bounds and numerical simulations.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100429403', 'Hai Li', 'Duke', 'Machine Learning', 'hai.li@duke.edu', 'Mixture Outlier Exposure: Towards Out-of-Distribution Detection in Fine-grained Environments', 'Many real-world scenarios in which DNN-based recognition systems are deployed have inherently fine-grained attributes (e.g., bird-species recognition, medical image classification). In addition to achieving reliable accuracy, a critical subtask for these models is to detect Out-of-distribution (OOD) inputs. Given the nature of the deployment environment, one may expect such OOD inputs to also be fine-grained w.r.t. the known classes (e.g., a novel bird species), which are thus extremely difficult to identify. Unfortunately, OOD detection in fine-grained scenarios remains largely underexplored. In this work, we aim to fill this gap by first carefully constructing four large-scale fine-grained test environments, in which existing methods are shown to have difficulties. Particularly, we find that even explicitly incorporating a diverse set of auxiliary outlier data during training does not provide sufficient coverage over the broad region where fine-grained OOD samples locate. We then propose Mixture Outlier Exposure (MixOE), which mixes ID data and training outliers to expand the coverage of different OOD granularities, and trains the model such that the prediction confidence linearly decays as the input transitions from ID to OOD. Extensive experiments and analyses demonstrate the effectiveness of MixOE for building up OOD detector in finegrained environments. The code is available at https://github.com/zjysteven/MixOE.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5059349233', 'Jennifer M. Groh', 'Duke', 'Machine Learning', 'jmgroh@duke.edu', 'Coordinated multiplexing of information about separate objects in visual cortex', 'of the stimuli that may be present at a given moment? We recently showed that when more than one stimulus is present, single neurons can fluctuate between coding one vs. the other(s) across some time period, suggesting a form of neural multiplexing of different stimuli (Caruso et al., 2018). Here, we investigate (a) whether such coding fluctuations occur in early visual cortical areas; (b) how coding fluctuations are coordinated across the neural population; and (c) how coordinated coding fluctuations depend on the parsing of stimuli into separate vs. fused objects. We found coding fluctuations do occur in macaque V1 but only when the two stimuli form separate objects. Such separate objects evoked a novel pattern of V1 spike count (''noise'') correlations involving distinct distributions of positive and negative values. This bimodal correlation pattern was most pronounced among pairs of neurons showing the strongest evidence for coding fluctuations or multiplexing. Whether a given pair of neurons exhibited positive or negative correlations depended on whether the two neurons both responded better to the same object or had different object preferences. Distinct distributions of spike count correlations based on stimulus preferences were also seen in V4 for separate objects but not when two stimuli fused to form one object. These findings suggest multiple objects evoke different response dynamics than those evoked by single stimuli, lending support to the multiplexing hypothesis ', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5005786784', 'Jessilyn Dunn', 'Duke', 'Machine Learning', 'jessilyn.dunn@duke.edu', 'A Systematic Review of Time Series Classification Techniques Used in Biomedical Applications', 'Background: Digital clinical measures collected via various digital sensing technologies such as smartphones, smartwatches, wearables, and ingestible and implantable sensors are increasingly used by individuals and clinicians to capture the health outcomes or behavioral and physiological characteristics of individuals. Time series classification (TSC) is very commonly used for modeling digital clinical measures. While deep learning models for TSC are very common and powerful, there exist some fundamental challenges. This review presents the non-deep learning models that are commonly used for time series classification in biomedical applications that can achieve high performance. Objective: We performed a systematic review to characterize the techniques that are used in time series classification of digital clinical measures throughout all the stages of data processing and model building. Methods: We conducted a literature search on PubMed, as well as the Institute of Electrical and Electronics Engineers (IEEE), Web of Science, and SCOPUS databases using a range of search terms to retrieve peer-reviewed articles that report on the academic research about digital clinical measures from a five-year period between June 2016 and June 2021. We identified and categorized the research studies based on the types of classification algorithms and sensor input types. Results: We found 452 papers in total from four different databases: PubMed, IEEE, Web of Science Database, and SCOPUS. Af', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5062247330', 'Jian Pei', 'Duke', 'Machine Learning', 'j.pei@duke.edu', 'Database Native Model Selection: Harnessing Deep Neural Networks in Database Systems', 'The growing demand for advanced analytics beyond statistical aggregation calls for database systems that support effective model selection of deep neural networks (DNNs). However, existing model selection strategies are based on either training-based algorithms that deliver high-performing models at the expense of high computational cost, or training-free algorithms that enhance computational efficiency with reduced effectiveness. These strategies often disregard computational cost and response time Service-Level Objectives (SLOs), which are of concern to average or budget-conscious machine learning users. In addition, they lack a well-designed integration of the model selection algorithms with DBMSs, which hinders efficient in-database model selection. This paper presents TRAILS, a resource-efficient and SLO-aware in-database model selection system. To leverage the strengths of both training-free and training-based model selection, we first characterize nine state-of-the-art training-free model evaluation metrics and propose a more effective one named JacFlow, and then, restructure the conventional model selection procedure into two phases: filtering and refinement. A novel coordinator is also introduced to strike a balance between the high efficiency of train-free algorithms and the high effectiveness of training-based algorithms, ensuring high-performing model selection while adhering to target SLOs. Moreover, we incorporate the proposed algorithm into PostgreSQL to develo', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5007239332', 'Jordan M. Malof', 'Duke', 'Machine Learning', 'jordan.malof@duke.edu', 'SIMPL: Generating Synthetic Overhead Imagery to Address Custom Zero-Shot and Few-Shot Detection Problems', 'Recently deep neural networks (DNNs) have achieved tremendous success for object detection in overhead (e.g., satellite) imagery. One ongoing challenge however is the acquisition of training data, due to high costs of obtaining satellite imagery and annotating objects in it. In this work we present a simple approach termed Synthetic object IMPLantation (SIMPL) - to easily and rapidly generate large quantities of synthetic overhead training data for custom target objects. We demonstrate the effectiveness of using SIMPL synthetic imagery for training DNNs in zero-shot scenarios where no real imagery is available; and few-shot learning scenarios, where limited real-world imagery is available. We also conduct experiments to study the sensitivity of SIMPLs effectiveness to some key design parameters, providing users for insights when designing synthetic imagery for custom objects. We release a software implementation of our SIMPL approach, as well as design details of our experimental synthetic imagery, so that others can build upon our approach, or use it for their own custom problems.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040192736', 'Joseph Y. Lo', 'Duke', 'Machine Learning', 'joseph.lo@duke.edu', 'Ipsilateral Lesion Detection Refinement for Tomosynthesis', 'Computer-aided detection (CAD) frameworks for breast cancer screening have been researched for several decades. Early adoption of deep-learning models in CAD frameworks has shown greatly improved detection performance compared to traditional CAD on single-view images. Recently, studies have improved performance by merging information from multiple views within each screening exam. Clinically, the integration of lesion correspondence during screening is a complicated decision process that depends on the correct execution of several referencing steps. However, most multi-view CAD frameworks are deep-learning-based black-box techniques. Fully end-to-end designs make it very difficult to analyze model behaviors and fine-tune performance. More importantly, the black-box nature of the techniques discourages clinical adoption due to the lack of explicit reasoning for each multi-view referencing step. Therefore, there is a need for a multi-view detection framework that can not only detect cancers accurately but also provide step-by-step, multi-view reasoning. In this work, we present Ipsilateral-Matching-Refinement Networks (IMR-Net) for digital breast tomosynthesis (DBT) lesion detection across multiple views. Our proposed framework adaptively refines the single-view detection scores based on explicit ipsilateral lesion matching. IMR-Net is built on a robust, single-view detection CAD pipeline with a commercial development DBT dataset of 24675 DBT volumetric views from 8034 exams. P', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5113873534', 'Jun Yang', 'Duke', 'Machine Learning', 'junyang@cs.duke.edu', 'Selectivity Functions of Range Queries are Learnable', 'This paper explores the use of machine learning for estimating the selectivity of range queries in database systems. Using classic learning theory for real-valued functions based on shattering dimension, we show that the selectivity function of a range space with bounded VC-dimension is learnable. As many popular classes of queries (e.g., orthogonal range search, inequalities involving linear combination of attributes, distance-based search, etc.) represent range spaces with finite VC-dimension, our result immediately implies that their selectivity functions are also learnable. To the best of our knowledge, this is the first attempt at formally explaining the role of machine learning techniques in selectivity estimation, and complements the growing literature in empirical studies in this direction. Supplementing these theoretical results, our experimental results demonstrate that, empirically, even a basic learning algorithm with generic models is able to produce accurate predictions across settings, matching state-of-art methods designed for specific queries, and using training sample sizes commensurate with our theory.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5033880864', 'Krishnendu Chakrabarty', 'Duke', 'Machine Learning', 'Krishnendu.Chakrabarty@asu.edu', 'Functional Criticality Analysis of Structural Faults in AI Accelerators', 'The ubiquitous application of deep neural networks (DNNs) has led to a rise in demand for artificial intelligence (AI) accelerators. For example, the tensor processing unit from Google–based on a systolic array–and its variants are of considerable interest for DNN inferencing using AI accelerators. This article studies the problem of classifying structural faults in such an accelerator based on their functional criticality. We first analyze pin-level faults in the processing elements (PEs) of a systolic array. Simulation results for the LeNet network with 8-bit fixed-point, 16-bit floating-point (FP), and 32-bit FP data paths applied to the MNIST dataset show that over 93% of the pin-level structural faults in a PE are functionally benign. We present a greedy iterative framework for determining the criticality of stuck-at faults in a PE netlist and analyze the limitations of criticality analysis methods based on repeated fault simulations. We next present a scalable two-tier machine-learning (ML)-based method to assess the functional criticality of stuck-at faults in a computationally efficient manner. We address the problem of minimizing misclassification by utilizing generative adversarial networks (GANs). Two-tier ML/GAN-based criticality assessment leads to less than 1% test escapes during functional criticality evaluation of structural faults.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5054438743', 'Kyle Bradbury', 'Duke', 'Machine Learning', 'kyle.bradbury@duke.edu', 'Utilizing Geospatial Data for Assessing Energy Security: Mapping Small Solar Home Systems Using Unmanned Aerial Vehicles and Deep Learning', 'Solar home systems (SHS), a cost-effective solution for rural communities far from the grid in developing countries, are small solar panels and associated equipment that provides power to a single household. A crucial resource for targeting further investment of public and private resources, as well as tracking the progress of universal electrification goals, is shared access to high-quality data on individual SHS installations including information such as location and power capacity. Though recent studies utilizing satellite imagery and machine learning to detect solar panels have emerged, they struggle to accurately locate many SHS due to limited image resolution (some small solar panels only occupy several pixels in satellite imagery). In this work, we explore the viability and cost-performance tradeoff of using automatic SHS detection on unmanned aerial vehicle (UAV) imagery as an alternative to satellite imagery. More specifically, we explore three questions: (i) what is the detection performance of SHS using drone imagery; (ii) how expensive is the drone data collection, compared to satellite imagery; and (iii) how well does drone-based SHS detection perform in real-world scenarios? To examine these questions, we collect and publicly-release a dataset of high-resolution drone imagery encompassing SHS imaged under a variety of real-world conditions and use this dataset and a dataset of imagery from Rwanda to evaluate the capabilities of deep learning models to recognize', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001300575', 'Maciej A. Mazurowski', 'Duke', 'Machine Learning', 'maciej.mazurowski@duke.edu', 'SWSSL: Sliding Window-Based Self-Supervised Learning for Anomaly Detection in High-Resolution Images', 'Anomaly detection (AD) aims to determine if an instance has properties different from those seen in normal cases. The success of this technique depends on how well a neural network learns from normal instances. We observe that the learning difficulty scales exponentially with the input resolution, making it infeasible to apply AD to high-resolution images. Resizing them to a lower resolution is a compromising solution and does not align with clinical practice where the diagnosis could depend on image details. In this work, we propose to train the network and perform inference at the patch level, through the sliding window algorithm. This simple operation allows the network to receive high-resolution images but introduces additional training difficulties, including inconsistent image structure and higher variance. We address these concerns by setting the network''s objective to learn augmentation-invariant features. We further study the augmentation function in the context of medical imaging. In particular, we observe that the resizing operation, a key augmentation in general computer vision literature, is detrimental to detection accuracy, and the inverting operation can be beneficial. We also propose a new module that encourages the network to learn from adjacent patches to boost detection performance. Extensive experiments are conducted on breast tomosynthesis and chest X-ray datasets and our method improves 8.03% and 5.66% AUC on image-level classification respectively over', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5009102659', 'Neil Zhenqiang Gong', 'Duke', 'Machine Learning', 'neil.gong@duke.edu', 'BadEncoder: Backdoor Attacks to Pre-trained Encoders in Self-Supervised Learning', 'Self-supervised learning in computer vision aims to pre-train an image encoder using a large amount of unlabeled images or (image, text) pairs. The pre-trained image encoder can then be used as a feature extractor to build downstream classifiers for many downstream tasks with a small amount of or no labeled training data. In this work, we propose BadEncoder, the first backdoor attack to self-supervised learning. In particular, our BadEncoder injects backdoors into a pre-trained image encoder such that the downstream classifiers built based on the backdoored image encoder for different downstream tasks simultaneously inherit the backdoor behavior. We formulate our BadEncoder as an optimization problem and we propose a gradient descent based method to solve it, which produces a backdoored image encoder from a clean one. Our extensive empirical evaluation results on multiple datasets show that our BadEncoder achieves high attack success rates while preserving the accuracy of the downstream classifiers. We also show the effectiveness of BadEncoder using two publicly available, real-world image encoders, i.e., Google’s image encoder pre-trained on ImageNet and OpenAI’s Contrastive Language-Image Pre-training (CLIP) image encoder pre-trained on 400 million (image, text) pairs collected from the Internet. Moreover, we consider defenses including Neural Cleanse and MNTD (empirical defenses) as well as PatchGuard (a provable defense). Our results show that these defenses are insuffici', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100673516', 'Nuo Li', 'Duke', 'Machine Learning', 'nuo.li@duke.edu', 'A combinatorial neural code for long-term motor memory', 'Motor skill repertoire can be stably retained over long periods, but the neural mechanism that underlies stable memory storage remains poorly understood1–8. Moreover, it is unknown how existing motor memories are maintained as new motor skills are continuously acquired. Here we tracked neural representation of learned actions throughout a significant portion of the lifespan of a mouse and show that learned actions are stably retained in combination with context, which protects existing memories from erasure during new motor learning. We established a continual learning paradigm in which mice learned to perform directional licking in different task contexts while we tracked motor cortex activity for up to six months using two-photon imaging. Within the same task context, activity driving directional licking was stable over time with little representational drift. When learning new task contexts, new preparatory activity emerged to drive the same licking actions. Learning created parallel new motor memories instead of modifying existing representations. Re-learning to make the same actions in the previous task context re-activated the previous preparatory activity, even months later. Continual learning of new task contexts kept creating new preparatory activity patterns. Context-specific memories, as we observed in the motor system, may provide a solution for stable memory storage throughout continual learning. Long-term tracking of learned actions in mouse motor cortex shows t', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5056639842', 'Ricardo Henao', 'Duke', 'Machine Learning', 'ricardo.henao@duke.edu', 'Efficient Classification of Very Large Images with Tiny Objects', 'An increasing number of applications in computer vision, specially, in medical imaging and remote sensing, become challenging when the goal is to classify very large images with tiny informative objects. Specifically, these classification tasks face two key challenges: i) the size of the input image is usually in the order of mega- or giga-pixels, however, existing deep architectures do not easily operate on such big images due to memory constraints, consequently, we seek a memory-efficient method to process these images; and ii) only a very small fraction of the input images are informative of the label of interest, resulting in low region of interest (ROI) to image ratio. However, most of the current convolutional neural networks (CNNs) are designed for image classification datasets that have relatively large ROIs and small image sizes (sub-megapixel). Existing approaches have addressed these two challenges in isolation. We present an end-to-end CNN model termed Zoom-In network that leverages hierarchical attention sampling for classification of large images with tiny objects using a single GPU. We evaluate our method on four large-image histopathology, road-scene and satellite imaging datasets, and one gigapixel pathology dataset. Experimental results show that our model achieves higher accuracy than existing methods while requiring less memory resources.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5109839104', 'Ronald Parr', 'Duke', 'Machine Learning', 'ronald.parr@duke.edu', 'On the Existence of Simpler Machine Learning Models', 'It is almost always easier to find an accurate-but-complex model than an accurate-yet-simple model. Finding optimal, sparse, accurate models of various forms (linear models with integer coefficients, decision sets, rule lists, decision trees) is generally NP-hard. We often do not know whether the search for a simpler model will be worthwhile, and thus we do not go to the trouble of searching for one. In this work, we ask an important practical question: can accurate-yet-simple models be proven to exist, or shown likely to exist, before explicitly searching for them? We hypothesize that there is an important reason that simple-yet-accurate models often do exist. This hypothesis is that the size of the Rashomon set is often large, where the Rashomon set is the set of almost-equally-accurate models from a function class. If the Rashomon set is large, it contains numerous accurate models, and perhaps at least one of them is the simple model we desire. In this work, we formally present the Rashomon ratio as a new gauge of simplicity for a learning problem, depending on a function class and a data set. The Rashomon ratio is the ratio of the volume of the set of accurate models to the volume of the hypothesis space, and it is different from standard complexity measures from statistical learning theory. Insight from studying the Rashomon ratio provides an easy way to check whether a simpler model might exist for a problem before finding it, namely whether several different machine le', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5023554560', 'Sin‐Ho Jung', 'Duke', 'Machine Learning', 'sinho.jung@duke.edu', 'LASSO and Elastic Net Tend to Over-Select Features', 'Machine learning methods have been a standard approach to select features that are associated with an outcome and to build a prediction model when the number of candidate features is large. LASSO is one of the most popular approaches to this end. The LASSO approach selects features with large regression estimates, rather than based on statistical significance, that are associated with the outcome by imposing an L1-norm penalty to overcome the high dimensionality of the candidate features. As a result, LASSO may select insignificant features while possibly missing significant ones. Furthermore, from our experience, LASSO has been found to select too many features. By selecting features that are not associated with the outcome, we may have to spend more cost to collect and manage them in the future use of a fitted prediction model. Using the combination of L1- and L2-norm penalties, elastic net (EN) tends to select even more features than LASSO. The overly selected features that are not associated with the outcome act like white noise, so that the fitted prediction model may lose prediction accuracy. In this paper, we propose to use standard regression methods, without any penalizing approach, combined with a stepwise variable selection procedure to overcome these issues. Unlike LASSO and EN, this method selects features based on statistical significance. Through extensive simulations, we show that this maximum likelihood estimation-based method selects a very small number of f', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5023633559', 'Sina Farsiu', 'Duke', 'Machine Learning', 'sina.farsiu@duke.edu', 'Directional Connectivity-based Segmentation of Medical Images', 'Anatomical consistency in biomarker segmentation is crucial for many medical image analysis tasks. A promising paradigm for achieving anatomically consistent segmentation via deep networks is incorporating pixel connectivity, a basic concept in digital topology, to model inter-pixel relationships. However, previous works on connectivity modeling have ignored the rich channel-wise directional information in the latent space. In this work, we demonstrate that effective disentanglement of directional sub-space from the shared latent space can significantly enhance the feature representation in the connectivity-based network. To this end, we propose a directional connectivity modeling scheme for segmentation that decouples, tracks, and utilizes the directional information across the network. Experiments on various public medical image segmentation benchmarks show the effectiveness of our model as compared to the state-of-the-art methods. Code is available at https://github.com/Zyun-Y/DconnNet.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5058073627', 'Yiran Chen', 'Duke', 'Machine Learning', 'yiran.chen@duke.edu', 'Cascading structured pruning', 'Performance and efficiency of running modern Deep Neural Networks (DNNs) are heavily bounded by data movement. To mitigate the data movement bottlenecks, recent DNN inference accelerator designs widely adopt aggressive compression techniques and sparse-skipping mechanisms. These mechanisms avoid transferring or computing with zero-valued weights or activations to save time and energy. However, such sparse-skipping logic involves large input buffers and irregular data access patterns, thus precluding many energy-efficient data reuse opportunities and dataflows. In this work, we propose Cascading Structured Pruning (CSP), a technique that preserves significantly more data reuse opportunities for higher energy efficiency while maintaining comparable performance relative to recent sparse architectures such as SparTen. CSP includes the following two components: At algorithm level, CSP-A induces a predictable sparsity pattern that allows for low-overhead compression of weight data and sequential access to both activation and weight data. At architecture level, CSP-H leverages CSP-A''s induced sparsity pattern with a novel dataflow to access unique activation data only once, thus removing the demand for large input buffers. Each CSP-H processing element (PE) employs a novel accumulation buffer design and a counter-based sparse-skipping mechanism to support the dataflow with minimum controller overhead. We verify our approach on several representative models. Our simulated results sho', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5034716112', 'Z. J. Kabala', 'Duke', 'Machine Learning', 'zbigniew.kabala@duke.edu', 'Refereeing the Sport of Squash with a Machine Learning System', 'Squash is a sport where referee decisions are essential to the game. However, these decisions are very subjective in nature. Disputes, both from the players and the audience, regularly occur because the referee made a controversial call. In this study, we propose automating the referee decision process through machine learning. We trained neural networks to predict such decisions using data from 400 referee decisions acquired through extensive video footage reviewing and labeling. Six positional values were extracted, including the attacking player’s position, the retreating player’s position, the ball’s position in the frame, the ball’s projected first bounce, the ball’s projected second bounce, and the attacking player’s racket head position. We calculated nine additional distance values, such as the distance between players and the distance from the attacking player’s racket head to the ball’s path. Models were trained on Wolfram Mathematica and Python using these values. The best Wolfram Mathematica model and the best Python model achieved accuracies of 86% ± 3.03% and 85.2% ± 5.1%, respectively. These accuracies surpass 85%, demonstrating near-human performance. Our model has great potential for improvement as it is currently trained with limited, unbalanced data (400 decisions) and lacks crucial data points such as time and speed. The performance of our model is almost surely going to improve significantly with a larger training dataset. Unlike human referees, machine l', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5077329074', 'Zhicheng Ji', 'Duke', 'Machine Learning', 'zhicheng.ji@duke.edu', 'A systematic evaluation of computational methods for cell segmentation', 'Cell segmentation is a fundamental task in analyzing biomedical images. Many computational methods have been developed for cell segmentation and instance segmentation, but their performances are not well understood in various scenarios. We systematically evaluated the performance of 18 segmentation methods to perform cell nuclei and whole cell segmentation using light microscopy and fluorescence staining images. We found that general-purpose methods incorporating the attention mechanism exhibit the best overall performance. We identified various factors influencing segmentation performances, including image channels, choice of training data, and cell morphology, and evaluated the generalizability of methods across image modalities. We also provide guidelines for choosing the optimal segmentation methods in various real application scenarios. We developed Seggal, an online resource for downloading segmentation models already pre-trained with various tissue and cell types, substantially reducing the time and effort for training cell segmentation models.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5091409910', 'Adrian V. Dalca', 'Harvard', 'Machine Learning', 'adalca@mgh.harvard.edu', 'Learning the Effect of Registration Hyperparameters with HyperMorph', 'We introduce HyperMorph, a framework that facilitates efficient hyperparameter tuning in learning-based deformable image registration. Classical registration algorithms perform an iterative pair-wise optimization to compute a deformation field that aligns two images. Recent learning-based approaches leverage large image datasets to learn a function that rapidly estimates a deformation for a given image pair. In both strategies, the accuracy of the resulting spatial correspondences is strongly influenced by the choice of certain hyperparameter values. However, an effective hyperparameter search consumes substantial time and human effort as it often involves training multiple models for different fixed hyperparameter values and may lead to suboptimal registration. We propose an amortized hyperparameter learning strategy to alleviate this burden by learning the impact of hyperparameters on deformation fields. We design a meta network, or hypernetwork, that predicts the parameters of a registration network for input hyperparameters, thereby comprising a single model that generates the optimal deformation field corresponding to given hyperparameter values. This strategy enables fast, high-resolution hyperparameter search at test-time, reducing the inefficiency of traditional approaches while increasing flexibility. We also demonstrate additional benefits of HyperMorph, including enhanced robustness to model initialization and the ability to rapidly identify optimal hyperparameter ', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5058812679', 'Ali Gholipour', 'Harvard', 'Machine Learning', 'ali.gholipour@childrens.harvard.edu', 'Improving Calibration and Out-of-Distribution Detection in Deep Models for Medical Image Segmentation', 'Convolutional Neural Networks (CNNs) have proved to be powerful medical image segmentation models. In this study, we address some of the main unresolved issues regarding these models. Specifically, training of these models on small medical image datasets is still challenging, with many studies promoting techniques such as transfer learning. Moreover, these models are infamous for producing over-confident predictions and for failing silently when presented with out-of-distribution (OOD) test data. In this paper, for improving prediction calibration we advocate for multi-task learning, i.e., training a single model on several different datasets, spanning different organs of interest and different imaging modalities. We show that multi-task learning can significantly improve model confidence calibration. For OOD detection, we propose a novel method based on spectral analysis of CNN feature maps. We show that different datasets, representing different imaging modalities and/or different organs of interest, have distinct spectral signatures, which can be used to identify whether or not a test image is similar to the images used for training. We show that our proposed method is more accurate than several competing methods, including methods based on prediction uncertainty and image classification.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5018154366', 'Benjamin H. Kann', 'Harvard', 'Machine Learning', 'benjamin_kann@dfci.harvard.edu', 'A foundation model for generalized brain MRI analysis', 'Artificial intelligence (AI) applied to brain magnetic resonance imaging (MRI) has the potential to improve disease diagnosis and management but requires algorithms with generalizable knowledge that can perform well in a variety of clinical scenarios. The field has been constrained, thus far, by limited training data and task-specific models that do not generalize well across patient populations and medical tasks. Foundation models, by leveraging self-supervised learning, pretraining, and targeted adaptation, present a promising paradigm to overcome these limitations. Here, we present Brain Imaging Adaptive Core (BrainIAC), a novel foundation model designed to learn generalized representations from unlabeled brain MRI data and serve as a core basis for diverse downstream application adaptation. Trained and validated on 48,519 brain MRIs across a broad spectrum of tasks, we demonstrate that BrainIAC outperforms localized supervised training and other pretrained models, particularly in low-data settings and high-difficulty tasks, allowing for application in scenarios otherwise infeasible. BrainIAC can be integrated into imaging pipelines and multimodal frameworks and may lead to improved biomarker discovery and AI clinical translation.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5085184029', 'Bryan Ostdiek', 'Harvard', 'Machine Learning', 'bostdiek@g.harvard.edu', 'Neural embedding: learning the embedding of the manifold of physics data', 'A bstract In this paper, we present a method of embedding physics data manifolds with metric structure into lower dimensional spaces with simpler metrics, such as Euclidean and Hyperbolic spaces. We then demonstrate that it can be a powerful step in the data analysis pipeline for many applications. Using progressively more realistic simulated collisions at the Large Hadron Collider, we show that this embedding approach learns the underlying latent structure. With the notion of volume in Euclidean spaces, we provide for the first time a viable solution to quantifying the true search capability of model agnostic search algorithms in collider physics (i.e. anomaly detection). Finally, we discuss how the ideas presented in this paper can be employed to solve many practical challenges that require the extraction of physically meaningful representations from information in complex high dimensional datasets.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5073266403', 'Haim Sompolinsky', 'Harvard', 'Machine Learning', 'hsompolinsky@mcb.harvard.edu', 'Neural representational geometry underlies few-shot concept learning', 'Understanding the neural basis of the remarkable human cognitive capacity to learn novel concepts from just one or a few sensory experiences constitutes a fundamental problem. We propose a simple, biologically plausible, mathematically tractable, and computationally powerful neural mechanism for few-shot learning of naturalistic concepts. We posit that the concepts that can be learned from few examples are defined by tightly circumscribed manifolds in the neural firing-rate space of higher-order sensory areas. We further posit that a single plastic downstream readout neuron learns to discriminate new concepts based on few examples using a simple plasticity rule. We demonstrate the computational power of our proposal by showing that it can achieve high few-shot learning accuracy on natural visual concepts using both macaque inferotemporal cortex representations and deep neural network (DNN) models of these representations and can even learn novel visual concepts specified only through linguistic descriptors. Moreover, we develop a mathematical theory of few-shot learning that links neurophysiology to predictions about behavioral outcomes by delineating several fundamental and measurable geometric properties of neural representations that can accurately predict the few-shot learning performance of naturalistic concepts across all our numerical simulations. This theory reveals, for instance, that high-dimensional manifolds enhance the ability to learn new concepts from few examp', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5043151044', 'Hanspeter Pfister', 'Harvard', 'Machine Learning', 'pfister@seas.harvard.edu', 'Learning Vector Quantized Shape Code for Amodal Blastomere Instance Segmentation', 'Blastomere instance segmentation is important for analyzing embryos’ abnormality. To measure the accurate shapes and sizes of blastomeres, their amodal segmentation is necessary. Amodal instance segmentation aims to recover an object’s complete silhouette even when the object is not fully visible. For each detected object, previous methods directly regress the target mask from input features. However, images of an object under different amounts of occlusion should have the same amodal mask output, making it harder to train the regression model. To alleviate the problem, we propose to classify input features into intermediate shape codes and recover complete object shapes. First, we pre-train the Vector Quantized Variational Autoencoder (VQ-VAE) model to learn these discrete shape codes from ground truth amodal masks. Then, we incorporate the VQ-VAE model into the amodal instance segmentation pipeline with an additional refinement module. We also detect an occlusion map to integrate occlusion information with a backbone feature. As such, our network faithfully detects bounding boxes of amodal objects. On an internal embryo cell image benchmark, the proposed method outperforms previous state-of-the-art methods. To show generalizability, we show segmentation results on the public KINS natural image benchmark. Our method would enable accurate measurement of blastomeres in In Vitro Fertilization (IVF) clinics, potentially increasing the IVF success rate.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5012052022', 'Jason Poulos', 'Harvard', 'Machine Learning', 'poulos@hcp.med.harvard.edu', 'Adversarial Machine Learning: Bayesian Perspectives', 'Adversarial Machine Learning (AML) is emerging as a major field aimed at protecting Machine Learning (ML) systems against security threats: in certain scenarios there may be adversaries that actively manipulate input data to fool learning systems. This creates a new class of security vulnerabilities that ML systems may face, and a new desirable property called adversarial robustness essential to trust operations based on ML outputs. Most work in AML is built upon a game-theoretic modeling of the conflict between a learning system and an adversary, ready to manipulate input data. This assumes that each agent knows their opponent’s interests and uncertainty judgments, facilitating inferences based on Nash equilibria. However, such common knowledge assumption is not realistic in the security scenarios typical of AML. After reviewing such game-theoretic approaches, we discuss the benefits that Bayesian perspectives provide when defending ML-based systems. We demonstrate how the Bayesian approach allows us to explicitly model our uncertainty about the opponent’s beliefs and interests, relaxing unrealistic assumptions, and providing more robust inferences. We illustrate this approach in supervised learning settings, and identify relevant future research problems. Supplementary materials for this article are available online.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5054888342', 'Juan Eugenio Iglesias', 'Harvard', 'Machine Learning', 'jiglesiasgonzalez@mgh.harvard.edu', 'SynthSeg: Segmentation of brain MRI scans of any contrast and resolution without retraining', 'Despite advances in data augmentation and transfer learning, convolutional neural networks (CNNs) difficultly generalise to unseen domains. When segmenting brain scans, CNNs are highly sensitive to changes in resolution and contrast: even within the same MRI modality, performance can decrease across datasets. Here we introduce SynthSeg, the first segmentation CNN robust against changes in contrast and resolution. SynthSeg is trained with synthetic data sampled from a generative model conditioned on segmentations. Crucially, we adopt a domain randomisation strategy where we fully randomise the contrast and resolution of the synthetic training data. Consequently, SynthSeg can segment real scans from a wide range of target domains without retraining or fine-tuning, which enables straightforward analysis of huge amounts of heterogeneous clinical data. Because SynthSeg only requires segmentations to be trained (no images), it can learn from labels obtained by automated methods on diverse populations (e.g., ageing and diseased), thus achieving robustness to a wide range of morphological variability. We demonstrate SynthSeg on 5,000 scans of six modalities (including CT) and ten resolutions, where it exhibits unparallelled generalisation compared with supervised CNNs, state-of-the-art domain adaptation, and Bayesian segmentation. Finally, we demonstrate the generalisability of SynthSeg by applying it to cardiac MRI and CT scans.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5072714716', 'Matthew D. Schwartz', 'Harvard', 'Machine Learning', 'schwartz@g.harvard.edu', 'Challenges for unsupervised anomaly detection in particle physics', 'A bstract Anomaly detection relies on designing a score to determine whether a particular event is uncharacteristic of a given background distribution. One way to define a score is to use autoencoders, which rely on the ability to reconstruct certain types of data (background) but not others (signals). In this paper, we study some challenges associated with variational autoencoders, such as the dependence on hyperparameters and the metric used, in the context of anomalous signal (top and W ) jets in a QCD background. We find that the hyperparameter choices strongly affect the network performance and that the optimal parameters for one signal are non-optimal for another. In exploring the networks, we uncover a connection between the latent space of a variational autoencoder trained using mean-squared-error and the optimal transport distances within the dataset. We then show that optimal transport distances to representative events in the background dataset can be used directly for anomaly detection, with performance comparable to the autoencoders. Whether using autoencoders or optimal transport distances for anomaly detection, we find that the choices that best represent the background are not necessarily best for signal identification. These challenges with unsupervised anomaly detection bolster the case for additional exploration of semi-supervised or alternative approaches.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5069001141', 'Mauricio Santillana', 'Harvard', 'Machine Learning', 'msantill@g.harvard.edu', 'Using digital traces to build prospective and real-time county-level early warning systems to anticipate COVID-19 outbreaks in the United States', 'Coronavirus disease 2019 (COVID-19) continues to affect the world, and the design of strategies to curb disease outbreaks requires close monitoring of their trajectories. We present machine learning methods that leverage internet-based digital traces to anticipate sharp increases in COVID-19 activity in U.S. counties. In a complementary direction to the efforts led by the Centers for Disease Control and Prevention (CDC), our models are designed to detect the time when an uptrend in COVID-19 activity will occur. Motivated by the need for finer spatial resolution epidemiological insights, we build upon previous efforts conceived at the state level. Our methods—tested in an out-of-sample manner, as events were unfolding, in 97 counties representative of multiple population sizes across the United States—frequently anticipated increases in COVID-19 activity 1 to 6 weeks before local outbreaks, defined when the effective reproduction number R t becomes larger than 1 for a period of 2 weeks.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5078672454', 'Meena M. Makary', 'Harvard', 'Machine Learning', 'mmakary@mgh.harvard.edu', 'FLAIR MRI sequence synthesis using squeeze attention generative model for reliable brain tumor segmentation', 'Manual segmentation of brain tumors using structural magnetic resonance imaging (MRI) is an arduous and time-consuming task. Therefore, automatic and robust segmentation will considerably influence neuro-oncological clinical trials by reducing excessive manual annotation time. Herein, we propose a deep learning model that automatically segments brain tumors even in cases of missing MRI sequences, which are common in practical clinical settings. To address this issue, we enhance a generative adversarial network (GAN) by incorporating a squeeze-and-excitation (SE) attention module into its generator and a PatchGAN into its discriminator. The SE module recalibrates channel responses by explicitly modeling interdependencies, enabling the network to focus on critical regions such as tumor areas. Our proposed generative model is optimized using a combination of adversarial, structural similarity, and mean absolute error losses to synthesize missing MRI sequences more effectively. This enhancement allows our model to synthesize the missing MRI sequence (fluid attenuated inversion recovery [FLAIR]) by leveraging information from other available sequences (T1-weighted, T2-weighted, or contrast-enhanced T1-weighted [T1ce]). For the segmentation task, we employ an optimized nnU-Net model, which is trained using existing sequences and evaluated using both available and synthesized sequences (including missing ones), mimicking real-world scenarios where often only limited MRI sequences ar', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5010629974', 'Nicola Toschi', 'Harvard', 'Machine Learning', 'toschi@med.uniroma2.it', 'Beyond multilayer perceptrons: Investigating complex topologies in neural networks', 'This study delves into the crucial aspect of network topology in artificial neural networks (NNs) and its impact on model performance. Addressing the need to comprehend how network structures influence learning capabilities, the research contrasts traditional multilayer perceptrons (MLPs) with models built on various complex topologies using novel network generation techniques. Drawing insights from synthetic datasets, the study reveals the remarkable accuracy of complex NNs, particularly in high-difficulty scenarios, outperforming MLPs. Our exploration extends to real-world datasets, highlighting the task-specific nature of optimal network topologies and unveiling trade-offs, including increased computational demands and reduced robustness to graph damage in complex NNs compared to MLPs. This research underscores the pivotal role of complex topologies in addressing challenging learning tasks. However, it also signals the necessity for deeper insights into the complex interplay among topological attributes influencing NN performance. By shedding light on the advantages and limitations of complex topologies, this study provides valuable guidance for practitioners and paves the way for future endeavors to design more efficient and adaptable neural architectures across various applications.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5077239665', 'Oleg S. Pianykh', 'Harvard', 'Machine Learning', 'opianykh@mgh.harvard.edu', 'Temporal quality degradation in AI models', 'As AI models continue to advance into many real-life applications, their ability to maintain reliable quality over time becomes increasingly important. The principal challenge in this task stems from the very nature of current machine learning models, dependent on the data as it was at the time of training. In this study, we present the first analysis of AI "aging": the complex, multifaceted phenomenon of AI model quality degradation as more time passes since the last model training cycle. Using datasets from four different industries (healthcare operations, transportation, finance, and weather) and four standard machine learning models, we identify and describe the main temporal degradation patterns. We also demonstrate the principal differences between temporal model degradation and related concepts that have been explored previously, such as data concept drift and continuous learning. Finally, we indicate potential causes of temporal degradation, and suggest approaches to detecting aging and reducing its impact.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5042900617', 'Omar Arnaout', 'Harvard', 'Machine Learning', 'oarnaout@bwh.harvard.edu', 'Deep neural networks allow expert-level brain meningioma segmentation and present potential for improvement of clinical practice', 'Accurate brain meningioma segmentation and volumetric assessment are critical for serial patient follow-up, surgical planning and monitoring response to treatment. Current gold standard of manual labeling is a time-consuming process, subject to inter-user variability. Fully-automated algorithms for meningioma segmentation have the potential to bring volumetric analysis into clinical and research workflows by increasing accuracy and efficiency, reducing inter-user variability and saving time. Previous research has focused solely on segmentation tasks without assessment of impact and usability of deep learning solutions in clinical practice. Herein, we demonstrate a three-dimensional convolutional neural network (3D-CNN) that performs expert-level, automated meningioma segmentation and volume estimation on MRI scans. A 3D-CNN was initially trained by segmenting entire brain volumes using a dataset of 10,099 healthy brain MRIs. Using transfer learning, the network was then specifically trained on meningioma segmentation using 806 expert-labeled MRIs. The final model achieved a median performance of 88.2% reaching the spectrum of current inter-expert variability (82.6-91.6%). We demonstrate in a simulated clinical scenario that a deep learning approach to meningioma segmentation is feasible, highly accurate and has the potential to improve current clinical practice.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5075516550', 'Petros Koumoutsakos', 'Harvard', 'Machine Learning', 'petros@seas.harvard.edu', 'Generative learning for forecasting the dynamics of high-dimensional complex systems', 'We introduce generative models for accelerating simulations of high-dimensional systems through learning and evolving their effective dynamics. In the proposed Generative Learning of Effective Dynamics (G-LED), instances of high dimensional data are down sampled to a lower dimensional manifold that is evolved through an auto-regressive attention mechanism. In turn, Bayesian diffusion models, that map this low-dimensional manifold onto its corresponding high-dimensional space, operate on batches of physics correlated, time sequences of data and capture the statistics of the system dynamics. We demonstrate the capabilities and drawbacks of G-LED in simulations of several benchmark systems, including the Kuramoto-Sivashinsky (KS) equation, two-dimensional high Reynolds number flow over a backward-facing step, and simulations of three-dimensional turbulent channel flow. The results demonstrate that generative learning offers new frontiers for the accurate forecasting of the statistical properties of high-dimensional systems at a reduced computational cost.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001559651', 'Pragya Sur', 'Harvard', 'Machine Learning', 'pragya@fas.harvard.edu', 'A precise high-dimensional asymptotic theory for boosting and minimum-ℓ1-norm interpolated classifiers', 'This paper establishes a precise high-dimensional asymptotic theory for boosting on separable data, taking statistical and computational perspectives. We consider a high-dimensional setting where the number of features (weak learners) p scales with the sample size n, in an overparametrized regime. Under a class of statistical models, we provide an exact analysis of the generalization error of boosting when the algorithm interpolates the training data and maximizes the empirical ℓ1-margin. Further, we explicitly pin down the relation between the boosting test error and the optimal Bayes error, as well as the proportion of active features at interpolation (with zero initialization). In turn, these precise characterizations answer certain questions raised in (Neural Comput. 11 (1999) 1493–1517; Ann. Statist. 26 (1998) 1651–1686) surrounding boosting, under assumed data generating processes. At the heart of our theory lies an in-depth study of the maximum-ℓ1-margin, which can be accurately described by a new system of nonlinear equations; to analyze this margin, we rely on Gaussian comparison techniques and develop a novel uniform deviation argument. Our statistical and computational arguments can handle (1) any finite-rank spiked covariance model for the feature distribution and (2) variants of boosting corresponding to general ℓq-geometry, q∈[1,2]. As a final component, via the Lindeberg principle, we establish a universality result showcasing that the scaled ℓ1-margin (asympto', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5058429770', 'Quanzheng Li', 'Harvard', 'Machine Learning', 'li.quanzheng@mgh.harvard.edu', 'SwinCross: Cross‐modal Swin transformer for head‐and‐neck tumor segmentation in PET/CT images', 'BACKGROUND: Radiotherapy (RT) combined with cetuximab is the standard treatment for patients with inoperable head and neck cancers. Segmentation of head and neck (H&N) tumors is a prerequisite for radiotherapy planning but a time-consuming process. In recent years, deep convolutional neural networks (DCNN) have become the de facto standard for automated image segmentation. However, due to the expensive computational cost associated with enlarging the field of view in DCNNs, their ability to model long-range dependency is still limited, and this can result in sub-optimal segmentation performance for objects with background context spanning over long distances. On the other hand, Transformer models have demonstrated excellent capabilities in capturing such long-range information in several semantic segmentation tasks performed on medical images. PURPOSE: Despite the impressive representation capacity of vision transformer models, current vision transformer-based segmentation models still suffer from inconsistent and incorrect dense predictions when fed with multi-modal input data. We suspect that the power of their self-attention mechanism may be limited in extracting the complementary information that exists in multi-modal data. To this end, we propose a novel segmentation model, debuted, Cross-modal Swin Transformer (SwinCross), with cross-modal attention (CMA) module to incorporate cross-modal feature extraction at multiple resolutions. METHODS: We propose a novel architectu', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5075643472', 'Sauro Succi', 'Harvard', 'Machine Learning', 'succi@seas.harvard.edu', 'Benchmarking YOLOv5 and YOLOv7 models with DeepSORT for droplet tracking applications', 'Tracking droplets in microfluidics is a challenging task. The difficulty arises in choosing a tool to analyze general microfluidic videos to infer physical quantities. The state-of-the-art object detector algorithm You Only Look Once (YOLO) and the object tracking algorithm Simple Online and Realtime Tracking with a Deep Association Metric (DeepSORT) are customizable for droplet identification and tracking. The customization includes training YOLO and DeepSORT networks to identify and track the objects of interest. We trained several YOLOv5 and YOLOv7 models and the DeepSORT network for droplet identification and tracking from microfluidic experimental videos. We compare the performance of the droplet tracking applications with YOLOv5 and YOLOv7 in terms of training time and time to analyze a given video across various hardware configurations. Despite the latest YOLOv7 being 10% faster, the real-time tracking is only achieved by lighter YOLO models on RTX 3070 Ti GPU machine due to additional significant droplet tracking costs arising from the DeepSORT algorithm. This work is a benchmark study for the YOLOv5 and YOLOv7 networks with DeepSORT in terms of the training time and inference time for a custom dataset of microfluidic droplets.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5006865040', 'Shing–Tung Yau', 'Harvard', 'Machine Learning', 'yau@math.harvard.edu', 'A novel 2-phase residual U-net algorithm combined with optimal mass transportation for 3D brain tumor detection and segmentation', 'Utilizing the optimal mass transportation (OMT) technique to convert an irregular 3D brain image into a cube, a required input format for a U-net algorithm, is a brand new idea for medical imaging research. We develop a cubic volume-measure-preserving OMT (V-OMT) model for the implementation of this conversion. The contrast-enhanced histogram equalization grayscale of fluid-attenuated inversion recovery (FLAIR) in a brain image creates the corresponding density function. We then propose an effective two-phase residual U-net algorithm combined with the V-OMT algorithm for training and validation. First, we use the residual U-net and V-OMT algorithms to precisely predict the whole tumor (WT) region. Second, we expand this predicted WT region with dilation and create a smooth function by convolving the step-like function associated with the WT region in the brain image with a [Formula: see text] blur tensor. Then, a new V-OMT algorithm with mesh refinement is constructed to allow the residual U-net algorithm to effectively train Net1-Net3 models. Finally, we propose ensemble voting postprocessing to validate the final labels of brain images. We randomly chose 1000 and 251 brain samples from the Brain Tumor Segmentation (BraTS) 2021 training dataset, which contains 1251 samples, for training and validation, respectively. The Dice scores of the WT, tumor core (TC) and enhanced tumor (ET) regions for validation computed by Net1-Net3 were 0.93705, 0.90617 and 0.87470, respectively. ', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5012875116', 'Steven J. Gortler', 'Harvard', 'Machine Learning', 'sjg@cs.harvard.edu', 'Low-Dimensional Invariant Embeddings for Universal Geometric Learning', 'Abstract This paper studies separating invariants: mappings on D -dimensional domains which are invariant to an appropriate group action and which separate orbits. The motivation for this study comes from the usefulness of separating invariants in proving universality of equivariant neural network architectures. We observe that in several cases the cardinality of separating invariants proposed in the machine learning literature is much larger than the dimension D . As a result, the theoretical universal constructions based on these separating invariants are unrealistically large. Our goal in this paper is to resolve this issue. We show that when a continuous family of semi-algebraic separating invariants is available, separation can be obtained by randomly selecting $$2D+1 $$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <mml:mn>2</mml:mn> <mml:mi>D</mml:mi> <mml:mo>+</mml:mo> <mml:mn>1</mml:mn> </mml:mrow> </mml:math> of these invariants. We apply this methodology to obtain an efficient scheme for computing separating invariants for several classical group actions which have been studied in the invariant learning literature. Examples include matrix multiplication actions on point clouds by permutations, rotations, and various other linear groups. Often the requirement of invariant separation is relaxed and only generic separation is required. In this case, we show that only $$D+1$$ <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"> <mml:mrow> <m', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5091317440', 'Susanne F. Yelin', 'Harvard', 'Machine Learning', 'syelin@g.harvard.edu', 'Quantum Goemans-Williamson Algorithm with the Hadamard Test and Approximate Amplitude Constraints', 'Semidefinite programs are optimization methods with a wide array of applications, such as approximating difficult combinatorial problems. One such semidefinite program is the Goemans-Williamson algorithm, a popular integer relaxation technique. We introduce a variational quantum algorithm for the Goemans-Williamson algorithm that uses only <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>n</mml:mi><mml:mrow class="MJX-TeXAtom-ORD"><mml:mo>+</mml:mo></mml:mrow><mml:mn>1</mml:mn></mml:math> qubits, a constant number of circuit preparations, and <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mtext>poly</mml:mtext><mml:mo stretchy="false">(</mml:mo><mml:mi>n</mml:mi><mml:mo stretchy="false">)</mml:mo></mml:math> expectation values in order to approximately solve semidefinite programs with up to <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>N</mml:mi><mml:mo>=</mml:mo><mml:msup><mml:mn>2</mml:mn><mml:mi>n</mml:mi></mml:msup></mml:math> variables and <mml:math xmlns:mml="http://www.w3.org/1998/Math/MathML"><mml:mi>M</mml:mi><mml:mo>&amp;#x223C;</mml:mo><mml:mi>O</mml:mi><mml:mo stretchy="false">(</mml:mo><mml:mi>N</mml:mi><mml:mo stretchy="false">)</mml:mo></mml:math> constraints. Efficient optimization is achieved by encoding the objective matrix as a properly parameterized unitary conditioned on an auxilary qubit, a technique known as the Hadamard Test. The Hadamard Test enables us to optimize the objective function by estimating ', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100359288', 'Xiaofeng Liu', 'Harvard', 'Machine Learning', 'xliu61@mgh.harvard.edu', 'Constraining pseudo‐label in self‐training unsupervised domain adaptation with energy‐based model', 'Deep learning is usually data starved, and the unsupervised domain adaptation (UDA) is developed to introduce the knowledge in the labeled source domain to the unlabeled target domain. Recently, deep self-training presents a powerful means for UDA, involving an iterative process of predicting the target domain and then taking the confident predictions as hard pseudo-labels for retraining. However, the pseudo-labels are usually unreliable, thus easily leading to deviated solutions with propagated errors. In this paper, we resort to the energy-based model and constrain the training of the unlabeled target sample with an energy function minimization objective. It can be achieved via a simple additional regularization or an energy-based loss. This framework allows us to gain the benefits of the energy-based model, while retaining strong discriminative performance following a plug-and-play fashion. The convergence property and its connection with classification expectation minimization are investigated. We deliver extensive experiments on the most popular and large-scale UDA benchmarks of image classification as well as semantic segmentation to demonstrate its generality and effectiveness.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5000509445', 'Xun Gao', 'Harvard', 'Machine Learning', 'xungao@g.harvard.edu', 'Interpretable Quantum Advantage in Neural Sequence Learning', 'Quantum neural networks have been widely studied in recent years, given their potential practical utility and recent results regarding their ability to efficiently express certain classical data. However, analytic results to date rely on assumptions and arguments from complexity theory. Because of this, there is little intuition as to the source of the expressive power of quantum neural networks or for which classes of classical data any advantage can be reasonably expected to hold. Here, we study the relative expressive power between a broad class of neural network sequence models and a class of recurrent models based on Gaussian operations with non-Gaussian measurements. We explicitly show that quantum contextuality is the source of an unconditional memory separation in the expressivity of the two model classes. We use this intuition to study the relative performance of our introduced model on a standard translation data set exhibiting linguistic contextuality. In doing so, we demonstrate that our introduced quantum models are able to outperform state-of-the-art classical models even in practice.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5033732758', 'Yang‐Yu Liu', 'Harvard', 'Machine Learning', 'yyl@channing.harvard.edu', 'Searching for spin glass ground states through deep reinforcement learning', 'Spin glasses are disordered magnets with random interactions that are, generally, in conflict with each other. Finding the ground states of spin glasses is not only essential for understanding the nature of disordered magnets and many other physical systems, but also useful to solve a broad array of hard combinatorial optimization problems across multiple disciplines. Despite decades-long efforts, an algorithm with both high accuracy and high efficiency is still lacking. Here we introduce DIRAC - a deep reinforcement learning framework, which can be trained purely on small-scale spin glass instances and then applied to arbitrarily large ones. DIRAC displays better scalability than other methods and can be leveraged to enhance any thermal annealing method. Extensive calculations on 2D, 3D and 4D Edwards-Anderson spin glass instances demonstrate the superior performance of DIRAC over existing methods. The presented framework will help us better understand the nature of the low-temperature spin-glass phase, which is a fundamental challenge in statistical physics. Moreover, the gauge transformation technique adopted in DIRAC builds a deep connection between physics and artificial intelligence. In particular, this opens up a promising avenue for reinforcement learning models to explore in the enormous configuration space, which would be extremely helpful to solve many other hard combinatorial optimization problems.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5068615078', 'Zifan Gu', 'Harvard', 'Machine Learning', 'zifan.gu@utsouthwestern.edu', 'Enhancing semantic segmentation in chest X-ray images through image preprocessing: ps-KDE for pixel-wise substitution by kernel density estimation', 'BACKGROUND: In medical imaging, the integration of deep-learning-based semantic segmentation algorithms with preprocessing techniques can reduce the need for human annotation and advance disease classification. Among established preprocessing techniques, Contrast Limited Adaptive Histogram Equalization (CLAHE) has demonstrated efficacy in improving segmentation algorithms across various modalities, such as X-rays and CT. However, there remains a demand for improved contrast enhancement methods considering the heterogeneity of datasets and the various contrasts across different anatomic structures. METHOD: This study proposes a novel preprocessing technique, ps-KDE, to investigate its impact on deep learning algorithms to segment major organs in posterior-anterior chest X-rays. Ps-KDE augments image contrast by substituting pixel values based on their normalized frequency across all images. We evaluate our approach on a U-Net architecture with ResNet34 backbone pre-trained on ImageNet. Five separate models are trained to segment the heart, left lung, right lung, left clavicle, and right clavicle. RESULTS: The model trained to segment the left lung using ps-KDE achieved a Dice score of 0.780 (SD = 0.13), while that of trained on CLAHE achieved a Dice score of 0.717 (SD = 0.19), p<0.01. ps-KDE also appears to be more robust as CLAHE-based models misclassified right lungs in select test images for the left lung model. The algorithm for performing ps-KDE is available at https://gi', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5064829377', 'Akshay Chaudhari', 'Stanford', 'Machine Learning', 'akshaysc@stanford.edu', 'Improving Data-Efficiency and Robustness of Medical Imaging Segmentation Using Inpainting-Based Self-Supervised Learning', 'We systematically evaluate the training methodology and efficacy of two inpainting-based pretext tasks of context prediction and context restoration for medical image segmentation using self-supervised learning (SSL). Multiple versions of self-supervised U-Net models were trained to segment MRI and CT datasets, each using a different combination of design choices and pretext tasks to determine the effect of these design choices on segmentation performance. The optimal design choices were used to train SSL models that were then compared with baseline supervised models for computing clinically-relevant metrics in label-limited scenarios. We observed that SSL pretraining with context restoration using 32 × 32 patches and Poission-disc sampling, transferring only the pretrained encoder weights, and fine-tuning immediately with an initial learning rate of 1 × 10−3 provided the most benefit over supervised learning for MRI and CT tissue segmentation accuracy (p &lt; 0.001). For both datasets and most label-limited scenarios, scaling the size of unlabeled pretraining data resulted in improved segmentation performance. SSL models pretrained with this amount of data outperformed baseline supervised models in the computation of clinically-relevant metrics, especially when the performance of supervised learning was low. Our results demonstrate that SSL pretraining using inpainting-based pretext tasks can help increase the robustness of models in label-limited scenarios and reduce worst-', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5045543562', 'Benjamin Van Roy', 'Stanford', 'Machine Learning', 'bvr@stanford.edu', 'Satisficing in Time-Sensitive Bandit Learning', 'Much of the recent literature on bandit learning focuses on algorithms that aim to converge on an optimal action. One shortcoming is that this orientation does not account for time sensitivity, which can play a crucial role when learning an optimal action requires much more information than near-optimal ones. Indeed, popular approaches, such as upper-confidence-bound methods and Thompson sampling, can fare poorly in such situations. We consider instead learning a satisficing action, which is near-optimal while requiring less information, and propose satisficing Thompson sampling, an algorithm that serves this purpose. We establish a general bound on expected discounted regret and study the application of satisficing Thompson sampling to linear and infinite-armed bandits, demonstrating arbitrarily large benefits over Thompson sampling. We also discuss the relation between the notion of satisficing and the theory of rate distortion, which offers guidance on the selection of satisficing actions.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5029806914', 'Boris Murmann', 'Stanford', 'Machine Learning', 'murmann@stanford.edu', 'Enhancing the Energy Efficiency and Robustness of tinyML Computer Vision Using Coarsely-quantized Log-gradient Input Images', 'This article studies the merits of applying log-gradient input images to convolutional neural networks (CNNs) for tinyML computer vision (CV). We show that log gradients enable: (i) aggressive 1-bit quantization of first-layer inputs, (ii) potential CNN resource reductions, (iii) inherent insensitivity to illumination changes (1.7% accuracy loss across 2 -5 … 2 3 brightness variation vs. up to 10% for JPEG), and (iv) robustness to adversarial attacks (&gt;10% higher accuracy than JPEG-trained models). We establish these results using the PASCAL RAW image dataset and through a combination of experiments using quantization threshold search, neural architecture search, and a fixed three-layer network. The latter reveals that training on log-gradient images leads to higher filter similarity, making the CNN more prunable. The combined benefits of aggressive first-layer quantization, CNN resource reductions, and operation without tight exposure control and image signal processing (ISP) are helpful for pushing tinyML CV toward its ultimate efficiency limits.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5070082070', 'Caroline Trippel', 'Stanford', 'Machine Learning', 'trippel@stanford.edu', 'Model Selection for Latency-Critical Inference Serving', 'In an inference service system, model selection and scheduling (MS&S) schemes map inference queries to trained machine learning (ML) models, hosted on a finite set of workers, to solicit accurate predictions within strict latency targets. MS&S is challenged by both varying query load and stochastic query inter-arrival patterns; however, state-of-the-art MS&S approaches conservatively account for load exclusively.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5088409133', 'Carolyn R. Bertozzi', 'Stanford', 'Machine Learning', 'bertozzi@stanford.edu', 'Analyzing nested experimental designs—A user-friendly resampling method to determine experimental significance', 'While hierarchical experimental designs are near-ubiquitous in neuroscience and biomedical research, researchers often do not take the structure of their datasets into account while performing statistical hypothesis tests. Resampling-based methods are a flexible strategy for performing these analyses but are difficult due to the lack of open-source software to automate test construction and execution. To address this, we present Hierarch, a Python package to perform hypothesis tests and compute confidence intervals on hierarchical experimental designs. Using a combination of permutation resampling and bootstrap aggregation, Hierarch can be used to perform hypothesis tests that maintain nominal Type I error rates and generate confidence intervals that maintain the nominal coverage probability without making distributional assumptions about the dataset of interest. Hierarch makes use of the Numba JIT compiler to reduce p-value computation times to under one second for typical datasets in biomedical research. Hierarch also enables researchers to construct user-defined resampling plans that take advantage of Hierarch''s Numba-accelerated functions.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5026961968', 'Clark Barrett', 'Stanford', 'Machine Learning', 'barrett@cs.stanford.edu', 'Marabou 2.0: A Versatile Formal Analyzer of Neural Networks', 'Abstract This paper serves as a comprehensive system description of version 2.0 of the Marabou framework for formal analysis of neural networks. We discuss the tool’s architectural design and highlight the major features and components introduced since its initial release.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5054372964', 'David Sussillo', 'Stanford', 'Machine Learning', 'sussillo@stanford.edu', 'Flexible multitask computation in recurrent networks utilizes shared dynamical motifs', 'Flexible computation is a hallmark of intelligent behavior. Yet, little is known about how neural networks contextually reconfigure for different computations. Humans are able to perform a new task without extensive training, presumably through the composition of elementary processes that were previously learned. Cognitive scientists have long hypothesized the possibility of a compositional neural code, where complex neural computations are made up of constituent components; however, the neural substrate underlying this structure remains elusive in biological and artificial neural networks. Here we identified an algorithmic neural substrate for compositional computation through the study of multitasking artificial recurrent neural networks. Dynamical systems analyses of networks revealed learned computational strategies that mirrored the modular subtask structure of the task-set used for training. Dynamical motifs such as attractors, decision boundaries and rotations were reused across different task computations. For example, tasks that required memory of a continuous circular variable repurposed the same ring attractor. We show that dynamical motifs are implemented by clusters of units and are reused across different contexts, allowing for flexibility and generalization of previously learned computation. Lesioning these clusters resulted in modular effects on network performance: a lesion that destroyed one dynamical motif only minimally perturbed the structure of other dyn', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5080725225', 'Dorsa Sadigh', 'Stanford', 'Machine Learning', 'dorsa@cs.stanford.edu', 'APReL: A Library for Active Preference-based Reward Learning Algorithms', 'Reward learning is a fundamental problem in human-robot interaction to have robots that operate in alignment with what their human user wants. Many preference-based learning algorithms and active querying techniques have been proposed as a solution to this problem. In this paper, we present APReL, a library for active preference-based reward learning algorithms, which enable researchers and practitioners to experiment with the existing techniques and easily develop their own algorithms for various modules of the problem. APReL is available at https://github.com/Stanford-ILIAD/APReL.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5050640377', 'Ellen Vitercik', 'Stanford', 'Machine Learning', 'vitercik@stanford.edu', 'How Much Data Is Sufficient to Learn High-Performing Algorithms?', 'Algorithms often have tunable parameters that impact performance metrics such as runtime and solution quality. For many algorithms used in practice, no parameter settings admit meaningful worst-case bounds, so the parameters are made available for the user to tune. Alternatively, parameters may be tuned implicitly within the proof of a worst-case approximation ratio or runtime bound. Worst-case instances, however, may be rare or nonexistent in practice. A growing body of research has demonstrated that a data-driven approach to parameter tuning can lead to significant improvements in performance. This approach uses a training set of problem instances sampled from an unknown, application-specific distribution and returns a parameter setting with strong average performance on the training set. We provide techniques for deriving generalization guarantees that bound the difference between the algorithm’s average performance over the training set and its expected performance on the unknown distribution. Our results apply no matter how the parameters are tuned, be it via an automated or manual approach. The challenge is that for many types of algorithms, performance is a volatile function of the parameters: slightly perturbing the parameters can cause a large change in behavior. Prior research [e.g., 12 , 16 , 20 , 62 ] has proved generalization bounds by employing case-by-case analyses of greedy algorithms, clustering algorithms, integer programming algorithms, and selling mechanis', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5061822097', 'Eric Darve', 'Stanford', 'Machine Learning', 'darve@stanford.edu', 'Anomaly Detection with Domain Adaptation', 'Despite great advances have been made in the field of domain adaptation (DA), the vast majority of current methods in DA solve classical ML tasks, e.g. classification. In this paper, we study a novel research direction: semi-supervised anomaly detection with domain adaptation. Given a set of normal data from a source domain and a limited number of normal examples from a target domain, the goal is to have a well-performing anomaly detector in the target domain. We then present the Invariant Representation Anomaly Detection (IRAD) to solve this problem where we first learn to extract a domain-invariant representation. The extraction is achieved by an across-domain encoder trained together with source-specific encoders and generators by adversarial learning. An anomaly detector is then trained using the learnt representations. We evaluate IRAD extensively on anomaly detection datasets, object recognition datasets and digits benchmarks. Experimental results show that IRAD outperforms baseline models by a wide margin across different datasets. We derive a theoretical lower bound for the joint error that explains the performance decay from over-training and also an upper bound for the generalization error.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5069625302', 'Grace Gao', 'Stanford', 'Machine Learning', 'gracegao@stanford.edu', 'Ellipsotopes: Uniting Ellipsoids and Zonotopes for Reachability Analysis and Fault Detection', 'Ellipsoids are a common representation for reachability analysis, because they can be transformed efficiently under affine maps, and they allow conservative approximation of Minkowski sums, which let one incorporate uncertainty and linearization error in a dynamical system by expanding the size of the reachable set. Zonotopes, a type of symmetric, convex polytope, are similarly frequently used, because they allow efficient numerical implementations of affine maps and exact Minkowski sums. Both of these representations also enable efficient, convex collision detection for fault detection or formal verification tasks, wherein one checks if the reachable set of a system collides (i.e., intersects) with an unsafe set. However, both representations often result in conservative representations for reachable sets of arbitrary systems, and neither is closed under intersection. Recently, representations, such as constrained zonotopes and constrained polynomial zonotopes, have been shown to overcome some of these conservativeness challenges, and are closed under intersection. However, constrained zonotopes cannot represent shapes with smooth boundaries, such as ellipsoids, and constrained polynomial zonotopes can require solving a nonconvex program for collision checking or fault detection. This article introducesellipsotopes, a set representation that is closed under affine maps, Minkowski sums, and intersections. Ellipsotopes combine the advantages of ellipsoids and zonotopes while e', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5065577825', 'Greg Zaharchuk', 'Stanford', 'Machine Learning', 'gregz@stanford.edu', 'One Model to Synthesize Them All: Multi-Contrast Multi-Scale Transformer for Missing Data Imputation', 'Multi-contrast magnetic resonance imaging (MRI) is widely used in clinical practice as each contrast provides complementary information. However, the availability of each imaging contrast may vary amongst patients, which poses challenges to radiologists and automated image analysis algorithms. A general approach for tackling this problem is missing data imputation, which aims to synthesize the missing contrasts from existing ones. While several convolutional neural networks (CNN) based algorithms have been proposed, they suffer from the fundamental limitations of CNN models, such as the requirement for fixed numbers of input and output channels, the inability to capture long-range dependencies, and the lack of interpretability. In this work, we formulate missing data imputation as a sequence-to-sequence learning problem and propose a multi-contrast multi-scale Transformer (MMT), which can take any subset of input contrasts and synthesize those that are missing. MMT consists of a multi-scale Transformer encoder that builds hierarchical representations of inputs combined with a multi-scale Transformer decoder that generates the outputs in a coarse-to-fine fashion. The proposed multi-contrast Swin Transformer blocks can efficiently capture intra- and inter-contrast dependencies for accurate image synthesis. Moreover, MMT is inherently interpretable as it allows us to understand the importance of each input contrast in different regions by analyzing the in-built attention maps of', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5082588269', 'Hae Young Noh', 'Stanford', 'Machine Learning', 'noh@stanford.edu', 'Seismic multi-hazard and impact estimation via causal inference from satellite imagery', 'Rapid post-earthquake reconnaissance is important for emergency responses and rehabilitation by providing accurate and timely information about secondary hazards and impacts, including landslide, liquefaction, and building damage. Despite the extensive collection of geospatial data and satellite images, existing physics-based and data-driven methods suffer from low estimation performance due to the complex and event-specific causal dependencies underlying the cascading processes of earthquake-triggered hazards and impacts. Herein, we present a rapid seismic multi-hazard and impact estimation system that leverages advanced statistical causal inference and remote sensing techniques. The unique feature of this system is that it provides accurate and high-resolution estimations on a regional scale by jointly inferring multiple hazards and building damage from satellite images through modeling their causal dependencies. We evaluate our system on multiple seismic events from diverse countries around the globe. Our results corroborate that incorporating causal dependencies significantly improves large-scale estimation accuracy for multiple hazards and impacts compared to existing systems. The results also reveal quantitative causal mechanisms among earthquake-triggered multi-hazard and impact for multiple seismic events. Our system establishes a new way to extract and utilize the complex interactions of multiple hazards and impacts for effective disaster responses and advancing unde', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100621605', 'Jiajun Wu', 'Stanford', 'Machine Learning', 'jiajunwu@cs.stanford.edu', 'NS3D: Neuro-Symbolic Grounding of 3D Objects and Relations', 'Grounding object properties and relations in 3D scenes is a prerequisite for a wide range of artificial intelligence tasks, such as visually grounded dialogues and embodied manipulation. However, the variability of the 3D domain induces two fundamental challenges: 1) the expense of labeling and 2) the complexity of 3D grounded language. Hence, essential desiderata for models are to be data-efficient, generalize to different data distributions and tasks with unseen semantic forms, as well as ground complex language semantics (e.g., view-point anchoring and multi-object reference). To address these challenges, we propose NS3D, a neuro-symbolic framework for 3D grounding. NS3D translates language into programs with hierarchical structures by leveraging large language-to-code models. Different functional modules in the programs are implemented as neural networks. Notably, NS3D extends prior neuro-symbolic visual reasoning methods by introducing functional modules that effectively reason about high-arity relations (i.e., relations among more than two objects), key in disambiguating objects in complex 3D scenes. Modular and compositional architecture enables NS3D to achieve state-of-the-art results on the ReferIt3D view-dependence task, a 3D referring expression compre-hension benchmark. Importantly, NS3D shows significantly improved performance on settings of data-efficiency and generalization, and demonstrate zero-shot transfer to an unseen 3D question-answering task.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5008053913', 'Kincho H. Law', 'Stanford', 'Machine Learning', 'law@stanford.edu', 'Fusion of CCTV Video and Spatial Information for Automated Crowd Congestion Monitoring in Public Urban Spaces', 'Crowd congestion is one of the main causes of modern public safety issues such as stampedes. Conventional crowd congestion monitoring using closed-circuit television (CCTV) video surveillance relies on manual observation, which is tedious and often error-prone in public urban spaces where crowds are dense, and occlusions are prominent. With the aim of managing crowded spaces safely, this study proposes a framework that combines spatial and temporal information to automatically map the trajectories of individual occupants, as well as to assist in real-time congestion monitoring and prediction. Through exploiting both features from CCTV footage and spatial information of the public space, the framework fuses raw CCTV video and floor plan information to create visual aids for crowd monitoring, as well as a sequence of crowd mobility graphs (CMGraphs) to store spatiotemporal features. This framework uses deep learning-based computer vision models, geometric transformations, and Kalman filter-based tracking algorithms to automate the retrieval of crowd congestion data, specifically the spatiotemporal distribution of individuals and the overall crowd flow. The resulting collective crowd movement data is then stored in the CMGraphs, which are designed to facilitate congestion forecasting at key exit/entry regions. We demonstrate our framework on two video data, one public from a train station dataset and the other recorded at a stadium following a crowded football game. Using both q', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100381484', 'Lei Xing', 'Stanford', 'Machine Learning', 'lei@stanford.edu', 'Adaptive Region-Specific Loss for Improved Medical Image Segmentation', 'Defining the loss function is an important part of neural network design and critically determines the success of deep learning modeling. A significant shortcoming of the conventional loss functions is that they weight all regions in the input image volume equally, despite the fact that the system is known to be heterogeneous (i.e., some regions can achieve high prediction performance more easily than others). Here, we introduce a region-specific loss to lift the implicit assumption of homogeneous weighting for better learning. We divide the entire volume into multiple sub-regions, each with an individualized loss constructed for optimal local performance. Effectively, this scheme imposes higher weightings on the sub-regions that are more difficult to segment, and vice versa. Furthermore, the regional false positive and false negative errors are computed for each input image during a training step and the regional penalty is adjusted accordingly to enhance the overall accuracy of the prediction. Using different public and in-house medical image datasets, we demonstrate that the proposed regionally adaptive loss paradigm outperforms conventional methods in the multi-organ segmentations, without any modification to the neural network architecture or additional data preparation.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5050003000', 'Marco Pavone', 'Stanford', 'Machine Learning', 'pavone@stanford.edu', 'Augmenting Lane Perception and Topology Understanding with Standard Definition Navigation Maps', 'Autonomous driving has traditionally relied heavily on costly and labor-intensive High Definition (HD) maps, hindering scalability. In contrast, Standard Definition (SD) maps are more affordable and have worldwide coverage, offering a scalable alternative. In this work, we systematically explore the effect of SD maps for real-time lane-topology understanding. We propose a novel framework to integrate SD maps into online map prediction and propose a Transformer-based encoder, SD Map Encoder Representations from transFormers, to leverage priors in SD maps for the lane-topology prediction task. This enhancement consistently and significantly boosts (by up to 60%) lane detection and topology prediction on current state-of-the-art online map prediction methods without bells and whistles and can be immediately incorporated into any Transformer-based lane-topology method. Code is available at https://github.com/NVlabs/SMERF.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5068326377', 'Mykel J. Kochenderfer', 'Stanford', 'Machine Learning', 'mykel@stanford.edu', 'Multi-Agent Variational Occlusion Inference Using People as Sensors', 'Autonomous vehicles must reason about spatial occlusions in urban environments to ensure safety without being overly cautious. Prior work explored occlusion inference from observed social behaviors of road agents, hence treating people as sensors. Inferring occupancy from agent behaviors is an inherently multimodal problem; a driver may behave similarly for different occupancy patterns ahead of them (e.g., a driver may move at constant speed in traffic or on an open road). Past work, however, does not account for this multimodality, thus neglecting to model this source of aleatoric uncertainty in the relationship between driver behaviors and their environment. We propose an occlusion inference method that characterizes observed behaviors of human agents as sensor measurements, and fuses them with those from a standard sensor suite. To capture the aleatoric uncertainty, we train a conditional variational autoencoder with a discrete latent space to learn a multimodal mapping from observed driver trajectories to an occupancy grid representation of the view ahead of the driver. Our method handles multi-agent scenarios, combining measurements from multiple observed drivers using evidential theory to solve the sensor fusion problem. Our approach is validated on a cluttered, real-world intersection, outperforming baselines and demonstrating real-time capable performance. Our code is available at https://github.com/sisl/MultiAgentVariationalOcclusionInferenc', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5029554261', 'Priyanka Raina', 'Stanford', 'Machine Learning', 'praina@stanford.edu', 'CHIMERA: A 0.92-TOPS, 2.2-TOPS/W Edge AI Accelerator With 2-MByte On-Chip Foundry Resistive RAM for Efficient Training and Inference', E'Implementing edge artificial intelligence (AI) inference and training is challenging with current memory technologies. As deep neural networks (DNNs) grow in size, this problem is only getting worse. This article presents CHIMERA, the first non-volatile DNN chip for both edge AI training and inference using foundry on-chip resistive RAM (RRAM) macros and no off-chip memory, fabricated in 40-nm CMOS. CHIMERA&#x2019;s DNN accelerator is specifically optimized for RRAM and achieves 0.92-TOPS peak performance and 2.2-TOPS/W energy efficiency. We scale inference up to$6\\times $larger DNNs by connecting six CHIMERAs in an illusion system with just 4&#x0025; overhead in measured execution time and 5&#x0025; in energy, enabled by communication-sparse DNN mappings that exploit RRAM non-volatility through quick chip wake-up and shutdown ($ &lt; 33 ~\\mu \\text{s}$). Our incremental edge AI training algorithm, called low-rank training, overcomes RRAM write energy, speed, and endurance challenges and achieves the same accuracy as traditional algorithms with up to$283\\times $fewer RRAM weight update steps and$340\\times $better energy-delay product. Combined with ENDUrance REsiliency using random Remapping (ENDURER), a hardware module that provides resilience to write endurance failures, we enable ten years of 20-samples/min incremental edge AI training.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5027340494', 'Robert Tibshirani', 'Stanford', 'Machine Learning', 'tibs@stanford.edu', 'Prediction and Outlier Detection in Classification Problems', 'Abstract We consider the multi-class classification problem when the training data and the out-of-sample test data may have different distributions and propose a method called BCOPS (balanced and conformal optimized prediction sets). BCOPS constructs a prediction set C(x) as a subset of class labels, possibly empty. It tries to optimize the out-of-sample performance, aiming to include the correct class and to detect outliers x as often as possible. BCOPS returns no prediction (corresponding to C(x) equal to the empty set) if it infers x to be an outlier. The proposed method combines supervised learning algorithms with conformal prediction to minimize a misclassification loss averaged over the out-of-sample distribution. The constructed prediction sets have a finite sample coverage guarantee without distributional assumptions. We also propose a method to estimate the outlier detection rate of a given procedure. We prove asymptotic consistency and optimality of our proposals under suitable assumptions and illustrate our methods on real data examples.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5081511803', 'Serena Yeung', 'Stanford', 'Machine Learning', 'syyeung@stanford.edu', 'PROB: Probabilistic Objectness for Open World Object Detection', 'Open World Object Detection (OWOD) is a new and challenging computer vision task that bridges the gap between classic object detection (OD) benchmarks and object detection in the real world. In addition to detecting and classifying seen/labeled objects, OWOD algorithms are expected to detect novel/unknown objects - which can be classified and incrementally learned. In standard OD, object proposals not overlapping with a labeled object are automatically classified as background. Therefore, simply applying OD methods to OWOD fails as unknown objects would be predicted as background. The challenge of detecting unknown objects stems from the lack of supervision in distinguishing unknown objects and background object proposals. Previous OWOD methods have attempted to overcome this issue by generating supervision using pseudo-labeling - however, unknown object detection has remained low. Probabilistic/generative models may provide a solution for this challenge. Herein, we introduce a novel probabilistic framework for objectness estimation, where we alternate between probability distribution estimation and objectness likelihood maximization of known objects in the embedded feature space - ultimately allowing us to estimate the objectness probability of different proposals. The resulting Probabilistic Objectness transformer-based open-world detector, PROB, integrates our framework into traditional object detection models, adapting them for the open-world setting. Comprehensive experi', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5089493027', 'Stefan Wager', 'Stanford', 'Machine Learning', 'swager@stanford.edu', 'Offline Multi-Action Policy Learning: Generalization and Optimization', 'As a result of digitization of the economy, more and more decision makers from a wide range of domains have gained the ability to target products, services, and information provision based on individual characteristics. Examples include selecting offers, prices, advertisements, or emails to send to consumers, choosing a bid to submit in a contextual first-price auctions, and determining which medication to prescribe to a patient. The key to enabling this is to learn a treatment policy from historical observational data in a sample-efficient way, hence uncovering the best personalized treatment choice recommendation. In “Offline Policy Learning: Generalization and Optimization,” Z. Zhou, S. Athey, and S. Wager provide a sample-optimal policy learning algorithm that is computationally efficient and that learns a tree-based treatment policy from observational data. In our quest toward fully automated personalization, the work provides a theoretically sound and practically implementable approach.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5091179481', 'Stefano Ermon', 'Stanford', 'Machine Learning', 'ermon@cs.stanford.edu', 'Efficient Conditional Pre-training for Transfer Learning', 'Almost all the state-of-the-art neural networks for computer vision tasks are trained by (1) pre-training on a large-scale dataset and (2) finetuning on the target dataset. This strategy helps reduce dependence on the target dataset and improves convergence rate and generalization on the target task. Although pre-training on large-scale datasets is very useful for new methods or models, its foremost disadvantage is high training cost. To address this, we propose efficient filtering methods to select relevant subsets from the pre-training dataset. Additionally, we discover that lowering image resolutions in the pre-training step offers a great trade-off between cost and performance. We validate our techniques by pre-training on ImageNet in both the unsupervised and supervised settings and finetuning on a diverse collection of target datasets and tasks. Our proposed methods drastically reduce pre-training cost and provide strong performance boosts. Finally, we improve the current standard of ImageNet pre-training by 1-3% by tuning available models on our subsets and pre-training on a dataset filtered from a larger scale dataset.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100968975', 'Yiqiao Zhong', 'Stanford', 'Machine Learning', 'yiqiao.zhong@wisc.edu', 'The interpolation phase transition in neural networks: Memorization and generalization under lazy training', 'Modern neural networks are often operated in a strongly overparametrized regime: they comprise so many parameters that they can interpolate the training set, even if actual labels are replaced by purely random ones. Despite this, they achieve good prediction error on unseen data: interpolating the training set does not lead to a large generalization error. Further, overparametrization appears to be beneficial in that it simplifies the optimization landscape. Here, we study these phenomena in the context of two-layers neural networks in the neural tangent (NT) regime. We consider a simple data model, with isotropic covariates vectors in d dimensions, and N hidden neurons. We assume that both the sample size n and the dimension d are large, and they are polynomially related. Our first main result is a characterization of the eigenstructure of the empirical NT kernel in the overparametrized regime Nd≫n. This characterization implies as a corollary that the minimum eigenvalue of the empirical NT kernel is bounded away from zero as soon as Nd≫n and, therefore, the network can exactly interpolate arbitrary labels in the same regime. Our second main result is a characterization of the generalization error of NT ridge regression including, as a special case, min-ℓ2 norm interpolation. We prove that, as soon as Nd≫n, the test error is well approximated by the one of kernel ridge regression with respect to the infinite-width kernel. The latter is in turn well approximated by the error ', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5101555401', 'Ali Mesbah', 'UC Berkeley', 'Machine Learning', 'mesbah@berkeley.edu', 'A Tutorial on Derivative-Free Policy Learning Methods for Interpretable Controller Representations', 'This paper provides a tutorial overview of recent advances in learning control policy representations for complex systems. We focus on control policies that are determined by solving an optimization problem that depends on the current state and some adjustable parameters. We refer to such policies as interpretable in the sense that each of the individual components can be directly understood by practitioners once the parameters are set, i.e., the objective function encodes the desired goal and the constraint functions enforce the rules of the system. We discuss how various commonly used control policies can be viewed in this manner such as the linear quadratic regulator, (nonlinear) model predictive control, and approximate dynamic programming. Traditionally, the parameters that appear in these control policies have been tuned by hand, expert knowledge, or simple trial-and-error experimentation, which can be time consuming and lead to suboptimal results in practice. To this end, we describe how the Bayesian optimization framework, which is a class of efficient derivative-free optimization methods for noisy functions, can be used to efficiently automate this process. In addition to reviewing relevant literature and demonstrating the effectiveness of these new methods on an illustrative example problem, we also offer perspectives on future research in this area.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5114047203', 'Amir Gholami', 'UC Berkeley', 'Machine Learning', 'amirgh@berkeley.edu', 'Adaptive Self-Supervision Algorithms for Physics-Informed Neural Networks', 'Physics-informed neural networks (PINNs) incorporate physical knowledge from the problem domain as a soft constraint on the loss function, but recent work has shown that this can lead to optimization difficulties. Here, we study the impact of the location of the collocation points on the trainability of these models. We find that the vanilla PINN performance can be significantly boosted by adapting the location of the collocation points as training proceeds. Specifically, we propose a novel adaptive collocation scheme which progressively allocates more collocation points (without increasing their total number) to areas where the model is making higher errors (based on the gradient of the loss function in the domain). This, coupled with a judicious restarting of the training during any optimization stalls (by simply resampling the collocation points in order to adjust the loss landscape) leads to better estimates for the prediction error. We present results for several problems, including a 2D Poisson and diffusion-advection system with different forcing functions. We find that training vanilla PINNs for these problems can result in up to 70% prediction error in the solution, especially in the regime of low collocation points. In contrast, our adaptive schemes can achieve up to an order of magnitude smaller error, with similar computational complexity as the baseline. Furthermore, we find that the adaptive methods consistently perform on-par or slightly better than vanilla PIN', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5031491881', 'Angjoo Kanazawa', 'UC Berkeley', 'Machine Learning', 'kanazawa@eecs.berkeley.edu', 'Nerfstudio: A Modular Framework for Neural Radiance Field Development', 'Neural Radiance Fields (NeRF) are a rapidly growing area of research with wide-ranging applications in computer vision, graphics, robotics, and more. In order to streamline the development and deployment of NeRF research, we propose a modular PyTorch framework, Nerfstudio. Our framework includes plug-and-play components for implementing NeRF-based methods, which make it easy for researchers and practitioners to incorporate NeRF into their projects. Additionally, the modular design enables support for extensive real-time visualization tools, streamlined pipelines for importing captured in-the-wild data, and tools for exporting to video, point cloud and mesh representations. The modularity of Nerfstudio enables the development of Nerfacto, our method that combines components from recent papers to achieve a balance between speed and quality, while also remaining flexible to future modifications. To promote community-driven development, all associated code and data are made publicly available with open-source licensing.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5008034417', 'Avideh Zakhor', 'UC Berkeley', 'Machine Learning', 'avz@eecs.berkeley.edu', 'Gallery Filter Network for Person Search', 'In person search, we aim to localize a query person from one scene in other gallery scenes. The cost of this search operation is dependent on the number of gallery scenes, making it beneficial to reduce the pool of likely scenes. We describe and demonstrate the Gallery Filter Network (GFN), a novel module which can efficiently discard gallery scenes from the search process, and benefit scoring for persons detected in remaining scenes. We show that the GFN is robust under a range of different conditions by testing on different retrieval sets, including cross-camera, occluded, and low-resolution scenarios. In addition, we develop the base SeqNeXt person search model, which improves and simplifies the original SeqNet model. We show that the SeqNeXt+GFN combination yields significant performance gains over other state-of-the-art methods on the standard PRW and CUHK-SYSU person search datasets. To aid experimentation for this and other models, we provide standardized tooling for the data processing and evaluation pipeline typically used for person search research.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5014661259', 'Ching‐Yao Chan', 'UC Berkeley', 'Machine Learning', 'cychan@berkeley.edu', 'Bimodal Extended Kalman Filter-Based Pedestrian Trajectory Prediction', 'We propose a pedestrian trajectory prediction algorithm based on the bimodal extended Kalman filter. With this filter, we are able to make full use of the dual-state nature of the pedestrian movement, i.e., the pedestrian is either moving or remains stationary. We apply the dual-mode probability model to describe the state of the pedestrian. Based on this model, we construct the proposed bimodal extended Kalman filter to estimate pedestrian state distribution. The filter obtains the state distribution for each pedestrian in the scene, respectively, and use that state distribution to predict the future trajectories of all the people in the scene. This prediction method estimates the prior probability of each parameter of the model through the dataset and updates the individual posterior probability of the pedestrian state through the bimodal extended Kalman filter. Our model can predict the trajectory of every individual, by taking the social interaction of pedestrians as well as the surrounding physical obstacles into account, with less than fifty model parameters being used, while with the limited parameter, our model could be nearly accurate as other deep learning models and still be comprehensible for model users.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5045155646', 'Claire J. Tomlin', 'UC Berkeley', 'Machine Learning', 'tomlin@berkeley.edu', 'Multi-Agent Reachability Calibration with Conformal Prediction', 'We investigate methods to provide safety assurances for autonomous agents that incorporate learning-based predictions of other, uncontrolled agents'' behavior into their own trajectory planning. Given a learning-based forecasting model that predicts agents'' trajectories, we introduce a method for providing probabilistic assurances on the model''s prediction error with calibrated confidence intervals. Through quantile regression, conformal prediction, and reachability analysis, our method generates probabilistically safe and dynamically feasible prediction sets. We showcase their utility in certifying the safety of planning algorithms, both in simulations using actual autonomous driving data and in an experiment with Boeing vehicles.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5013076652', 'Costas J. Spanos', 'UC Berkeley', 'Machine Learning', 'spanos@berkeley.edu', 'Conditional Synthetic Data Generation for Robust Machine Learning Applications with Limited Pandemic Data', 'Background: At the onset of a pandemic, such as COVID-19, data with proper labeling/attributes corresponding to the new disease might be unavailable or sparse. Machine Learning (ML) models trained with the available data, which is limited in quantity and poor in diversity, will often be biased and inaccurate. At the same time, ML algorithms designed to fight pandemics must have good performance and be developed in a time-sensitive manner. To tackle the challenges of limited data, and label scarcity in the available data, we propose generating conditional synthetic data, to be used alongside real data for developing robust ML models. Methods: We present a hybrid model consisting of a conditional generative flow and a classifier for conditional synthetic data generation. The classifier decouples the feature representation for the condition, which is fed to the flow to extract the local noise. We generate synthetic data by manipulating the local noise with fixed conditional feature representation. We also propose a semi-supervised approach to generate synthetic samples in the absence of labels for a majority of the available data. Results: We performed conditional synthetic generation for chest computed tomography (CT) scans corresponding to normal, COVID-19, and pneumonia afflicted patients. We show that our method significantly outperforms existing models both on qualitative and quantitative performance, and our semi-supervised approach can efficiently synthesize conditional s', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5062174672', 'David Wagner', 'UC Berkeley', 'Machine Learning', 'daw@cs.berkeley.edu', 'REAP: A Large-Scale Realistic Adversarial Patch Benchmark', 'Machine learning models are known to be susceptible to adversarial perturbation. One famous attack is the adversarial patch, a particularly crafted sticker that makes the model mispredict the object it is placed on. This attack presents a critical threat to cyber-physical systems that rely on cameras such as autonomous cars. Despite the significance of the problem, conducting research in this setting has been difficult; evaluating attacks and defenses in the real world is exceptionally costly while synthetic data are unrealistic. In this work, we propose the REAP (REalistic Adversarial Patch) benchmark, a digital benchmark that enables the evaluations on real images under real-world conditions. Built on top of the Mapillary Vistas dataset, our benchmark contains over 14,000 traffic signs. Each sign is augmented with geometric and lighting transformations for applying a digitally generated patch realistically onto the sign. Using our benchmark, we perform the first large-scale assessments of adversarial patch attacks under realistic conditions. Our experiments suggest that patch attacks may present a smaller threat than previously believed and that the success rate of an attack on simpler digital simulations is not predictive of its actual effectiveness in practice. Our benchmark is released publicly at https://github.com/wagner-group/reap-benchmark.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5025067440', 'Francesco Borrelli', 'UC Berkeley', 'Machine Learning', 'fborrelli@berkeley.edu', 'ParkPredict+: Multimodal Intent and Motion Prediction for Vehicles in Parking Lots with CNN and Transformer', 'The problem of multimodal intent and trajectory prediction for human-driven vehicles in parking lots is addressed in this paper. Using models designed with CNN and Transformer networks, we extract temporal-spatial and contextual information from trajectory history and local bird''s eye view (BEV) semantic images, and generate predictions about intent distribution and future trajectory sequences. Our methods outperform existing models in accuracy, while allowing an arbitrary number of modes, encoding complex multi-agent scenarios, and adapting to different parking maps. To train and evaluate our method, we present the first public 4K video dataset of human driving in parking lots with accurate annotation, high frame rate, and rich traffic scenarios.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5060196069', 'Jacob Steinhardt', 'UC Berkeley', 'Machine Learning', 'jsteinhardt@berkeley.edu', 'PixMix: Dreamlike Pictures Comprehensively Improve Safety Measures', 'In real-world applications of machine learning, reliable and safe systems must consider measures of performance beyond standard test set accuracy. These other goals include out-of-distribution (OOD) robustness, prediction consistency, resilience to adversaries, calibrated uncertainty estimates, and the ability to detect anomalous inputs. However, improving performance towards these goals is often a balancing act that today''s methods cannot achieve without sacrificing performance on other safety axes. For instance, adversarial training improves adversarial robustness but sharply degrades other classifier performance metrics. Similarly, strong data augmentation and regularization techniques often improve OOD robustness but harm anomaly detection, raising the question of whether a Pareto improvement on all existing safety measures is possible. To meet this challenge, we design a new data augmentation strategy utilizing the natural structural complexity of pictures such as fractals, which outperforms numerous baselines, is near Pareto-optimal, and roundly improves safety measures.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001594573', 'Jitendra Malik', 'UC Berkeley', 'Machine Learning', 'malik@eecs.berkeley.edu', 'Reversible Vision Transformers', 'We present Reversible Vision Transformers, a memory efficient architecture design for visual recognition. By decoupling the GPU memory footprint from the depth of the model, Reversible Vision Transformers enable memory efficient scaling of transformer architectures. We adapt two popular models, namely Vision Transformer and Multiscale Vision Transformers, to reversible variants and benchmark extensively across both model sizes and tasks of image classification, object detection and video classification. Reversible Vision Transformers achieve a reduced memory footprint of up to 15.5× at identical model complexity, parameters and accuracy, demonstrating the promise of reversible vision transformers as an efficient backbone for resource limited training regimes. Finally, we find that the additional computational burden of recomputing activations is more than overcome for deeper models, where throughput can increase up to 3.9 × over their non-reversible counterparts. Code and models are available at https://github.com/facebookresearch/mvit.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5047285420', 'Kurt Keutzer', 'UC Berkeley', 'Machine Learning', 'keutzer@berkeley.edu', 'A Survey of Quantization Methods for Efficient Neural Network Inference', 'This chapter provides approaches to the problem of quantizing the numerical values in deep Neural Network computations, covering the advantages/disadvantages of current methods. Over the past decade, people have observed significant improvements in the accuracy of Neural Networks (NNs) for a wide range of problems, often achieved by highly over-parameterized models. Achieving efficient, real-time NNs with optimal accuracy requires rethinking the design, training, and deployment of NN models. Model distillation involves training a large model and then using it as a teacher to train a more compact model. Loosely related to NN quantization is work in neuroscience that suggests that the human brain stores information in a discrete/quantized form, rather than in a continuous form. Gray and Neuhoff have written a very nice survey of the history of quantization up to 1998.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5064077634', 'Masayoshi Tomizuka', 'UC Berkeley', 'Machine Learning', 'tomizuka@berkeley.edu', 'NeRF-Det: Learning Geometry-Aware Volumetric Representation for Multi-View 3D Object Detection', 'We present NeRF-Det, a novel method for indoor 3D detection with posed RGB images as input. Unlike existing indoor 3D detection methods that struggle to model scene geometry, our method makes novel use of NeRF in an end-to-end manner to explicitly estimate 3D geometry, thereby improving 3D detection performance. Specifically, to avoid the significant extra latency associated with per-scene optimization of NeRF, we introduce sufficient geometry priors to enhance the generalizability of NeRF-MLP. Furthermore, we subtly connect the detection and NeRF branches through a shared MLP, enabling an efficient adaptation of NeRF to detection and yielding geometry-aware volumetric representations for 3D detection. Our method outperforms state-of-the-arts by 3.9 mAP and 3.1 mAP on the ScanNet and ARKITScenes benchmarks, respectively. We provide extensive analysis to shed light on how NeRF-Det works. As a result of our joint-training design, NeRF-Det is able to generalize well to unseen scenes for object detection, view synthesis, and depth estimation tasks without requiring per-scene optimization. Code is available at https://github.com/facebookresearch/NeRF-Det.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5058341556', 'Matthew Tancik', 'UC Berkeley', 'Machine Learning', 'tancik@berkeley.edu', 'LERF: Language Embedded Radiance Fields', 'Humans describe the physical world using natural language to refer to specific 3D locations based on a vast range of properties: visual appearance, semantics, abstract associations, or actionable affordances. In this work we propose Language Embedded Radiance Fields (LERFs), a method for grounding language embeddings from off-the-shelf models like CLIP into NeRF, which enable these types of open-ended language queries in 3D. LERF learns a dense, multi-scale language field inside NeRF by volume rendering CLIP embeddings along training rays, supervising these embeddings across training views to provide multi-view consistency and smooth the underlying language field. After optimization, LERF can extract 3D relevancy maps for a broad range of language prompts interactively in real-time, which has potential use cases in robotics, understanding vision-language models, and interacting with 3D scenes. LERF enables pixel-aligned, zero-shot queries on the distilled 3D CLIP embeddings without relying on region proposals or masks, supporting long-tail open-vocabulary queries hierarchically across the volume. See the project website at: https://lerf.io.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5082297273', 'Michael Lustig', 'UC Berkeley', 'Machine Learning', 'mlustig@eecs.berkeley.edu', 'Implicit data crimes: Machine learning bias arising from misuse of public data', 'SignificancePublic databases are an important resource for machine learning research, but their growing availability sometimes leads to "off-label" usage, where data published for one task are used for another. This work reveals that such off-label usage could lead to biased, overly optimistic results of machine-learning algorithms. The underlying cause is that public data are processed with hidden processing pipelines that alter the data features. Here we study three well-known algorithms developed for image reconstruction from magnetic resonance imaging measurements and show they could produce biased results with up to 48% artificial improvement when applied to public databases. We relate to the publication of such results as implicit "data crimes" to raise community awareness of this growing big data problem.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5022946616', 'Sayna Ebrahimi', 'UC Berkeley', 'Machine Learning', 'sayna@berkeley.edu', 'Contrastive Test-Time Adaptation', 'Test-time adaptation is a special setting of unsupervised domain adaptation where a trained model on the source domain has to adapt to the target domain without accessing source data. We propose a novel way to leverage self-supervised contrastive learning to facilitate target feature learning, along with an online pseudo labeling scheme with refinement that significantly denoises pseudo labels. The contrastive learning task is applied jointly with pseudo labeling, contrasting positive and negative pairs constructed similarly as MoCo but with source-initialized encoder, and excluding same-class negative pairs indicated by pseudo labels. Meanwhile, we produce pseudo labels online and refine them via soft voting among their nearest neighbors in the target feature space, enabled by maintaining a memory queue. Our method, AdaContrast, achieves state-of-the-art performance on major benchmarks while having several desirable properties compared to existing works, including memory efficiency, insensitivity to hyper-parameters, and better model calibration. Code is released at https://github.com/DianCh/AdaContrast.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5042014034', 'Stella X. Yu', 'UC Berkeley', 'Machine Learning', 'stellayu@umich.edu', 'Clipped Hyperbolic Classifiers Are Super-Hyperbolic Classifiers', 'Hyperbolic space can naturally embed hierarchies, unlike Euclidean space. Hyperbolic Neural Networks (HNNs) exploit such representational power by lifting Euclidean features into hyperbolic space for classification, outperforming Euclidean neural networks (ENNs) on datasets with known semantic hierarchies. However, HNNs underperform ENNs on standard benchmarks without clear hierarchies, greatly restricting HNNs'' applicability in practice. Our key insight is that HNNs'' poorer general classification performance results from vanishing gradients during backpropagation, caused by their hybrid architecture connecting Euclidean features to a hyperbolic classifier. We propose an effective solution by simply clipping the Euclidean feature magnitude while training HNNs. Our experiments demonstrate that clipped HNNs become super-hyperbolic classifiers: They are not only consistently better than HNNs which already outperform ENNs on hierarchical data, but also on-par with ENNs on MNIST, CIFAR10, CIFAR100 and ImageNet benchmarks, with better adversarial robustness and out-of-distribution detection.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5057257463', 'Stephen Bates', 'UC Berkeley', 'Machine Learning', 'stephenbates@berkeley.edu', 'Conformal Prediction: A Gentle Introduction', 'Black-box machine learning models are now routinely used in high-risk settings, like medical diagnostics, which demand uncertainty quantification to avoid consequential model failures. Conformal prediction (a.k.a. conformal inference) is a user-friendly paradigm for creating statistically rigorous uncertainty sets/intervals for the predictions of such models. Critically, the sets are valid in a distribution-free sense: they possess explicit, non-asymptotic guarantees even without distributional assumptions or model assumptions. One can use conformal prediction with any pre-trained model, such as a neural network, to produce sets that are guaranteed to contain the ground truth with a user-specified probability, such as 90%. It is easy-to-understand, easy-to-use, and general, applying naturally to problems arising in the fields of computer vision, natural language processing, deep reinforcement learning, and so on. This hands-on introduction is aimed to provide the reader a working understanding of conformal prediction and related distribution-free uncertainty quantification techniques with one self-contained document. We lead the reader through practical theory for and examples of conformal prediction and describe its extensions to complex machine learning tasks involving structured outputs, distribution shift, timeseries, outliers, models that abstain, and more. Throughout, there are many explanatory illustrations, examples, and code samples in Python. With each code sample c', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5029105520', 'Trevor Darrell', 'UC Berkeley', 'Machine Learning', 'trevor@eecs.berkeley.edu', 'Self-Correcting LLM-Controlled Diffusion Models', 'Text-to-image generation has witnessed significant progress with the advent of diffusion models. Despite the ability to generate photorealistic images, current text-to-image diffusion models still often struggle to accurately interpret and follow complex input text prompts. In contrast to existing models that aim to generate images only with their best effort, we introduce Self-correcting LLM-controlled Diffusion (SLD). SLD is a framework that generates an image from the input prompt, assesses its alignment with the prompt, and performs self-corrections on the inaccuracies in the generated image. Steered by an LLM controller, SLD turns text-to-image generation into an iterative closed-loop process, ensuring correctness in the resulting image. SLD is not only training-free but can also be seamlessly integrated with diffusion models behind API access, such as DALL-E 3, to further boost the performance of state-of-the-art diffusion models. Experimental results show that our approach can rectify a majority of incorrect generations, particularly in generative numeracy, attribute binding, and spatial relationships. Furthermore, by simply adjusting the instructions to the LLM, SLD can perform image editing tasks, bridging the gap between text-to-image generation and image editing pipelines. Our code is available at: https://self-correcting-llm-diffusion.github.io.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5031565603', 'Wei Zhan', 'UC Berkeley', 'Machine Learning', 'wzhan@berkeley.edu', 'Causal-based Time Series Domain Generalization for Vehicle Intention Prediction', 'Accurately predicting the possible behaviors of traffic participants is an essential capability for autonomous vehicles. Since autonomous vehicles need to navigate in dynamically changing environments, they are expected to make accurate predictions regardless of where they are and what driving circumstances they encountered. Therefore, generalization capability to unseen domains is crucial for prediction models when autonomous vehicles are deployed in the real world. In this paper, we aim to address the domain generalization problem for vehicle intention prediction tasks and a causal-based time series domain generalization (CTSDG) model is proposed. We construct a structural causal model for vehicle intention prediction tasks to learn an invariant representation of input driving data for domain generalization. We further integrate a recurrent latent variable model into our structural causal model to better capture temporal latent dependencies from time-series input data. The effectiveness of our approach is evaluated via real-world driving data. We demonstrate that our proposed method has consistent improvement on prediction accuracy compared to other state-of-the-art domain generalization and behavior prediction methods.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5101770873', 'Wei Zhan', 'UC Berkeley', 'Machine Learning', 'wzhan@berkeley.edu', 'SparseFusion: Fusing Multi-Modal Sparse Representations for Multi-Sensor 3D Object Detection', 'By identifying four important components of existing LiDAR-camera 3D object detection methods (LiDAR and camera candidates, transformation, and fusion outputs), we observe that all existing methods either find dense candidates or yield dense representations of scenes. However, given that objects occupy only a small part of a scene, finding dense candidates and generating dense representations is noisy and inefficient. We propose SparseFusion, a novel multi-sensor 3D detection method that exclusively uses sparse candidates and sparse representations. Specifically, SparseFusion utilizes the outputs of parallel detectors in the LiDAR and camera modalities as sparse candidates for fusion. We transform the camera candidates into the LiDAR coordinate space by disentangling the object representations. Then, we can fuse the multi-modality candidates in a unified 3D space by a lightweight self-attention module. To mitigate negative transfer between modalities, we propose novel semantic and geometric cross-modality transfer modules that are applied prior to the modality-specific detectors. SparseFusion achieves state-of-the-art performance on the nuScenes benchmark while also running at the fastest speed, even outperforming methods with stronger backbones. We perform extensive experiments to demonstrate the effectiveness and efficiency of our modules and overall method pipeline. Our code will be made publicly available at https://github.com/yichen928/SparseFusion.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5008683881', 'Yakun Sophia Shao', 'UC Berkeley', 'Machine Learning', 'ysshao@berkeley.edu', 'MoCA: Memory-Centric, Adaptive Execution for Multi-Tenant Deep Neural Networks', 'Driven by the wide adoption of deep neural networks (DNNs) across different application domains, multi-tenancy execution, where multiple DNNs are deployed simultaneously on the same hardware, has been proposed to satisfy the latency requirements of different applications while improving the overall system utilization. However, multi-tenancy execution could lead to undesired system-level resource contention, causing quality-of-service (QoS) degradation for latency-critical applications.To address this challenge, we propose MoCA1, an adaptive multi-tenancy system for DNN accelerators. Unlike existing solutions that focus on compute resource partition, MoCA dynamically manages shared memory resources of co-located applications to meet their QoS targets. Specifically, MoCA leverages the regularities in both DNN operators and accelerators to dynamically modulate memory access rates based on their latency targets and user-defined priorities so that co-located applications get the resources they demand without significantly starving their co-runners. We demonstrate that MoCA improves the satisfaction rate of the service level agreement (SLA) up to 3.9× (1.8× average), system throughput by 2.3× (1.7× average), and fairness by 1.3× (1.2× average), compared to prior work.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5090707978', 'Andrea L. Bertozzi', 'UCLA', 'Machine Learning', 'bertozzi@math.ucla.edu', 'Graph-based active learning for semi-supervised classification of SAR data', 'We present a novel method for classification of Synthetic Aperture Radar (SAR) data by combining ideas from graph-based learning and neural network methods within an active learning framework. Graph-based methods in machine learning are based on a similarity graph constructed from the data. When the data consists of raw images composed of scenes, extraneous information can make the classification task more difficult. In recent years, neural network methods have been shown to provide a promising framework for extracting patterns from SAR images. These methods, however, require ample training data to avoid overfitting. At the same time, such training data are often unavailable for applications of interest, such as automatic target recognition (ATR) and SAR data. We use a Convolutional Neural Network Variational Autoencoder (CNNVAE) to embed SAR data into a feature space, and then construct a similarity graph from the embedded data and apply graph-based semi-supervised learning techniques. The CNNVAE feature embedding and graph construction requires no labeled data, which reduces overfitting and improves the generalization performance of graph learning at low label rates. Furthermore, the method easily incorporates a human-in-the-loop for active learning in the data-labeling process. We present promising results and compare them to other standard machine learning methods on the Moving and Stationary Target Acquisition and Recognition (MSTAR) dataset for ATR with small amounts of', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5056549033', 'Anne K. Churchland', 'UCLA', 'Machine Learning', 'AChurchland@mednet.ucla.edu', 'The implications of categorical and category-free mixed selectivity on representational geometries', 'The firing rates of individual neurons displaying mixed selectivity are modulated by multiple task variables. When mixed selectivity is nonlinear, it confers an advantage by generating a high-dimensional neural representation that can be flexibly decoded by linear classifiers. Although the advantages of this coding scheme are well accepted, the means of designing an experiment and analyzing the data to test for and characterize mixed selectivity remain unclear. With the growing number of large datasets collected during complex tasks, the mixed selectivity is increasingly observed and is challenging to interpret correctly. We review recent approaches for analyzing and interpreting neural datasets and clarify the theoretical implications of mixed selectivity in the variety of forms that have been reported in the literature. We also aim to provide a practical guide for determining whether a neural population has linear or nonlinear mixed selectivity and whether this mixing leads to a categorical or category-free representation.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5022064746', 'Bahman Gharesifard', 'UCLA', 'Machine Learning', 'gharesifard@ucla.edu', 'Universal Approximation Power of Deep Residual Neural Networks Through the Lens of Control', 'In this article, we show that deep residual neural networks have the power of universal approximation by using, in an essential manner, the observation that these networks can be modeled as nonlinear control systems. We first study the problem of using a deep residual neural network to exactly memorize training data by formulating it as a controllability problem for an ensemble control system. Using techniques from geometric control theory, we identify a class of activation functions that allow us to ensure controllability on an open and dense submanifold of sample points. Using this result, and resorting to the notion of monotonicity, we establish that any continuous function can be approximated on a compact set to arbitrary accuracy, with respect to the uniform norm, by this class of neural networks. Moreover, we provide optimal bounds on the number of required neurons.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5010841999', 'Cho‐Jui Hsieh', 'UCLA', 'Machine Learning', 'chohsieh@cs.ucla.edu', 'Training Meta-Surrogate Model for Transferable Adversarial Attack', 'The problem of adversarial attacks to a black-box model when no queries are allowed has posed a great challenge to the community and has been extensively investigated. In this setting, one simple yet effective method is to transfer the obtained adversarial examples from attacking surrogate models to fool the target model. Previous works have studied what kind of attacks to the surrogate model can generate more transferable adversarial examples, but their performances are still limited due to the mismatches between surrogate models and the target model. In this paper, we tackle this problem from a novel angle---instead of using the original surrogate models, can we obtain a Meta-Surrogate Model (MSM) such that attacks to this model can be easily transferred to other models? We show that this goal can be mathematically formulated as a bi-level optimization problem and design a differentiable attacker to make training feasible. Given one or a set of surrogate models, our method can thus obtain an MSM such that adversarial examples generated on MSM enjoy eximious transferability. Comprehensive experiments on Cifar-10 and ImageNet demonstrate that by attacking the MSM, we can obtain stronger transferable adversarial examples to deceive black-box models including adversarially trained ones, with much higher success rates than existing methods.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5113600509', 'Fei–Yue Wang', 'UCLA', 'Machine Learning', 'feiyue.wang@ia.ac.cn', 'Social Radars: Finding Targets in Cyberspace for Cybersecurity', 'Inspired by the insight from American political scientist Lasswell, who summarized the environmental role in societal surveillance [1], Schramm coined the term “social radar” [2] as it resembles the activities of radar in collecting and processing information, playing a crucial role in helping humans perceive changes in the internal and external environment and promptly adjusting adaptive behaviors. Against the backdrop of cyberspace security becoming a global focus, the development of globalization in information and intelligence calls for in-depth research into social radar. This can help us better understand and respond to complex societal dynamics more intelligently and sensitively. Social radar, as the capability to keenly observe and interpret this information, aids in a better understanding of societal trends, cultural evolution, and interpersonal interactions. This sensitivity is crucial for timely grasping societal changes and predicting trends. In the 2010 “Arab Spring” event, social media played a crucial role in driving the movement, resulting in widespread violent conflicts that had significant impacts on both society and the economy [3]. This event re-introduced social radar as a service platform based on social networks and social media. It aims to employ keyword expansion detection modules and sentiment analysis tools to summarize specific social dashboards in Fig. 1. The generated results assist authorities in planning “risk control strategies,” issuing alert', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5101688179', 'Guang Cheng', 'UCLA', 'Machine Learning', 'guangcheng@ucla.edu', 'A Survey on Statistical Theory of Deep Learning: Approximation, Training Dynamics, and Generative Models', 'In this article, we review the literature on statistical theories of neural networks from three perspectives: approximation, training dynamics, and generative models. In the first part, results on excess risks for neural networks are reviewed in the nonparametric framework of regression. These results rely on explicit constructions of neural networks, leading to fast convergence rates of excess risks. Nonetheless, their underlying analysis only applies to the global minimizer in the highly nonconvex landscape of deep neural networks. This motivates us to review the training dynamics of neural networks in the second part. Specifically, we review articles that attempt to answer the question of how a neural network trained via gradient-based methods finds a solution that can generalize well on unseen data. In particular, two well-known paradigms are reviewed: the neural tangent kernel and mean-field paradigms. Last, we review the most recent theoretical advancements in generative models, including generative adversarial networks, diffusion models, and in-context learning in large language models from two of the same perspectives, approximation and training dynamics.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100617262', 'Haixin Wang', 'UCLA', 'Machine Learning', 'whx@cs.ucla.edu', 'PastNet: Introducing Physical Inductive Biases for Spatio-temporal Video Prediction', 'In this paper, we investigate the challenge of spatio-temporal video prediction, which involves generating future videos based on historical data streams. Existing approaches typically utilize external information such as semantic maps to enhance video prediction, which often neglect the inherent physical knowledge embedded within videos. Furthermore, their high computational demands could impede their applications for high-resolution videos. To address these constraints, we introduce a novel approach called <u>P</u>hysics-<u>a</u>ssisted <u>S</u>patio-<u>t</u>emporal <u>Net</u>work (PastNet) for generating high-quality video prediction. The core of our PastNet lies in incorporating a spectral convolution operator in the Fourier domain, which efficiently introduces inductive biases from the underlying physical laws. Additionally, we employ a memory bank with the estimated intrinsic dimensionality to discretize local features during the processing of complex spatio-temporal signals, thereby reducing computational costs and facilitating efficient high-resolution video prediction. Extensive experiments on various widely-used datasets demonstrate the effectiveness and efficiency of the proposed PastNet compared with a range of state-of-the-art methods, particularly in high-resolution scenarios. Our code is available at https://github.com/easylearningscores/PastNet.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5086926394', 'Hayden Schaeffer', 'UCLA', 'Machine Learning', 'hayden@math.ucla.edu', 'Towards a foundation model for partial differential equations: Multioperator learning and extrapolation', 'Foundation models, such as large language models, have demonstrated success in addressing various language and image processing tasks. In this work, we introduce a multimodal foundation model for scientific problems, named PROSE-PDE. Our model, designed for bimodality to bimodality learning, is a multioperator learning approach which can predict future states of spatiotemporal systems while concurrently learning the underlying governing equations of the physical system. Specifically, we focus on multioperator learning by training distinct one-dimensional time-dependent nonlinear constant coefficient partial differential equations, with potential applications to many physical applications including physics, geology, and biology. More importantly, we provide three extrapolation studies to demonstrate that PROSE-PDE can generalize physical features through the robust training of multiple operators and that the proposed model can extrapolate to predict PDE solutions whose models or data were unseen during the training. Furthermore, we show through systematic numerical experiments that the utilization of the symbolic modality in our model effectively resolves the well-posedness problems with training multiple operators and thus enhances our model''s predictive capabilities.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5088673556', 'Hongquan Xu', 'UCLA', 'Machine Learning', 'hqxu@stat.ucla.edu', 'Evaluating Designs for Hyperparameter Tuning in Deep Neural Networks', 'The performance of a learning technique relies heavily on hyperparameter settings. It calls for hyperparameter tuning for a deep learning technique, which may be too computationally expensive for sophisticated learning techniques. As such, expeditiously exploring the relationship between hyperparameters and the performance of a learning technique controlled by these hyperparameters is desired, and thus it entails the consideration of design strategies to collect informative data efficiently to do so. Various designs can be considered for this purpose. The question as to which design to use then naturally arises. In this paper, we examine the use of different types of designs in efficiently collecting informative data to study the surface of test accuracy, a measure of the performance of a learning technique, over hyperparameters. Under the settings we considered, we find that the strong orthogonal array outperforms all other comparable designs.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5016776689', 'Jason Cong', 'UCLA', 'Machine Learning', 'cong@cs.ucla.edu', 'Caffeine: Towards Uniformed Representation and Acceleration for Deep Convolutional Neural Networks', 'With the recent advancement of multilayer convolutional neural networks (CNN), deep learning has achieved amazing success in many areas, especially in visual content understanding and classification. To improve the performance and energy-efficiency of the computation-demanding CNN, the FPGA-based acceleration emerges as one of the most attractive alternatives. In this paper we design and implement Caffeine, a hardware and software co-designed library to efficiently accelerate the entire CNN on FPGAs. Based on the portable high-level synthesis, Caffeine provides a design automation flow that optimizes and generates FPGA-based AI hardware and runtime software codes. We integrate Caffeine into the industry-standard software deep learning framework.Caffeine achieves a peak performance of 365 GOPS on Xilinx KU060 FPGA and 636 GOPS on Virtex7 690t FPGA, showing up to 7.3x and 43.5x performance and energy gains over Caffe on a 12-core Xeon server, and 1.5x better energy-efficiency over the GPU.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5068374815', 'Jiaqi Ma', 'UCLA', 'Machine Learning', 'jiaqima@ucla.edu', 'OPV2V: An Open Benchmark Dataset and Fusion Pipeline for Perception with Vehicle-to-Vehicle Communication', 'Employing Vehicle-to-Vehicle communication to enhance perception performance in self-driving technology has attracted considerable attention recently; however, the absence of a suitable open dataset for benchmarking algorithms has made it difficult to develop and assess cooperative perception technologies. To this end, we present the first large-scale open simulated dataset for Vehicle-to-Vehicle perception. It contains over 70 interesting scenes, 11,464 frames, and 232,913 annotated 3D vehicle bounding boxes, collected from 8 towns in CARLA and a digital town of Culver City, Los Angeles. We then construct a comprehensive benchmark with a total of 16 implemented models to evaluate several information fusion strategies (i.e. early, late, and intermediate fusion) with state-of-the-art LiDAR detection algorithms. Moreover, we propose a new Attentive Intermediate Fusion pipeline to aggregate information from multiple connected vehicles. Our experiments show that the proposed pipeline can be easily integrated with existing 3D LiDAR detectors and achieve outstanding performance even with large compression rates. To encourage more researchers to investigate Vehicle-to-Vehicle perception, we will release the dataset, benchmark methods, and all related codes in https://mobility-lab.seas.ucla.edu/opv2v/.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5037745074', 'Jonathan B. Hopkins', 'UCLA', 'Machine Learning', 'hopkins@seas.ucla.edu', 'Comparing Mechanical Neural-Network Learning Algorithms', 'Abstract The purpose of this work is to compare learning algorithms to identify which is the fastest and most accurate for training mechanical neural networks (MNNs). MNNs are a unique class of lattice-based artificial intelligence (AI) architected materials that learn their mechanical behaviors with repeated exposure to external loads. They can learn multiple behaviors simultaneously in situ and re-learn desired behaviors after being damaged or cut into new shapes. MNNs learn by tuning the stiffnesses of their constituent beams similar to how artificial neural networks (ANNs) learn by tuning their weights. In this work, we compare the performance of six algorithms (i.e., genetic algorithm, full pattern search, partial pattern search, interior point, sequential quadratic progression, and Nelder–Mead) applied to MNN leaning. A computational model was created to simulate MNN learning using these algorithms with experimentally measured noise included. A total of 3900 runs were simulated. The results were validated using experimentally collected data from a physical MNN. We identify algorithms like Nelder–Mead that are both fast and able to reject noise. Additionally, we provide insights into selecting learning algorithms based on the desired balance between accuracy and speed, as well as the general characteristics that are favorable for training MNNs. These insights will promote more efficient MNN learning and will provide a foundation for future algorithm development.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5000684736', 'Jungseock Joo', 'UCLA', 'Machine Learning', 'jjoo@comm.ucla.edu', 'Explaining Deep Convolutional Neural Networks via Latent Visual-Semantic Filter Attention', 'Interpretability is an important property for visual mod-els as it helps researchers and users understand the in-ternal mechanism of a complex model. However, gener-ating semantic explanations about the learned representation is challenging without direct supervision to produce such explanations. We propose a general framework, La-tent Visual Semantic Explainer (LaViSE), to teach any ex-isting convolutional neural network to generate text de-scriptions about its own latent representations at the filter level. Our method constructs a mapping between the vi-sual and semantic spaces using generic image datasets, using images and category names. It then transfers the map-ping to the target domain which does not have semantic la-bels. The proposedframework employs a modular structure and enables to analyze any trained network whether or not its original training data is available. We show that our method can generate novel descriptions for learned filters beyond the set of categories defined in the training dataset and perform an extensive evaluation on multiple datasets. We also demonstrate a novel application of our method for unsupervised dataset bias analysis which allows us to auto-matically discover hidden biases in datasets or compare dif-ferent subsets without using additional labels. The dataset and code are made public to facilitate further research.11https://github.com/YuYang0901/LaViSE', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040894533', 'Kambiz Nael', 'UCLA', 'Machine Learning', 'Kambiz.Nael@ucsf.edu', 'U-Net Based Segmentation and Characterization of Gliomas', '(1) Background: Gliomas are the most common primary brain neoplasms accounting for roughly 40−50% of all malignant primary central nervous system tumors. We aim to develop a deep learning-based framework for automated segmentation and prediction of biomarkers and prognosis in patients with gliomas. (2) Methods: In this retrospective two center study, patients were included if they (1) had a diagnosis of glioma with known surgical histopathology and (2) had preoperative MRI with FLAIR sequence. The entire tumor volume including FLAIR hyperintense infiltrative component and necrotic and cystic components was segmented. Deep learning-based U-Net framework was developed based on symmetric architecture from the 512 × 512 segmented maps from FLAIR as the ground truth mask. (3) Results: The final cohort consisted of 208 patients with mean ± standard deviation of age (years) of 56 ± 15 with M/F of 130/78. DSC of the generated mask was 0.93. Prediction for IDH-1 and MGMT status had a performance of AUC 0.88 and 0.62, respectively. Survival prediction of <18 months demonstrated AUC of 0.75. (4) Conclusions: Our deep learning-based framework can detect and segment gliomas with excellent performance for the prediction of IDH-1 biomarker status and survival.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5056932023', 'Ke Sheng', 'UCLA', 'Machine Learning', 'ksheng@mednet.ucla.edu', 'Fully automated segmentation of prostatic urethra for MR‐guided radiation therapy', 'PURPOSE: Accurate delineation of the urethra is a prerequisite for urethral dose reduction in prostate radiotherapy. However, even in magnetic resonance-guided radiation therapy (MRgRT), consistent delineation of the urethra is challenging, particularly in online adaptive radiotherapy. This paper presented a fully automatic MRgRT-based prostatic urethra segmentation framework. METHODS: Twenty-eight prostate cancer patients were included in this study. In-house 3D half fourier single-shot turbo spin-echo (HASTE) and turbo spin echo (TSE) sequences were used to image the Foley-free urethra on a 0.35 T MRgRT system. The segmentation pipeline uses 3D nnU-Net as the base and innovatively combines ground truth and its corresponding radial distance (RD) map during training supervision. Additionally, we evaluate the benefit of incorporating a convolutional long short term memory (LSTM-Conv) layer and spatial recurrent convolution layer (RCL) into nnU-Net. A novel slice-by-slice simple exponential smoothing (SEPS) method specifically for tubular structures was used to post-process the segmentation results. RESULTS: The experimental results show that nnU-Net trained using a combination of Dice, cross-entropy and RD achieved a Dice score of 77.1 ± 2.3% in the testing dataset. With SEPS, Hausdorff distance (HD) and 95% HD were reduced to 2.95 ± 0.17 mm and 1.84 ± 0.11 mm, respectively. LSTM-Conv and RCL layers only minimally improved the segmentation precision. CONCLUSION: We present the', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5059053660', 'Kyunghyun Sung', 'UCLA', 'Machine Learning', 'ksung@mednet.ucla.edu', 'CAT-Net: A Cross-Slice Attention Transformer Model for Prostate Zonal Segmentation in MRI', 'Prostate cancer is the second leading cause of cancer death among men in the United States. The diagnosis of prostate MRI often relies on accurate prostate zonal segmentation. However, state-of-the-art automatic segmentation methods often fail to produce well-contained volumetric segmentation of the prostate zones since certain slices of prostate MRI, such as base and apex slices, are harder to segment than other slices. This difficulty can be overcome by leveraging important multi-scale image-based information from adjacent slices, but current methods do not fully learn and exploit such cross-slice information. In this paper, we propose a novel cross-slice attention mechanism, which we use in a Transformer module to systematically learn cross-slice information at multiple scales. The module can be utilized in any existing deep-learning-based segmentation framework with skip connections. Experiments show that our cross-slice attention is able to capture cross-slice information significant for prostate zonal segmentation in order to improve the performance of current state-of-the-art methods. Cross-slice attention improves segmentation accuracy in the peripheral zones, such that segmentation results are consistent across all the prostate slices (apex, mid-gland, and base). The code for the proposed model is available at https://bit.ly/CAT-Net.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5074563122', 'Mani Srivastava', 'UCLA', 'Machine Learning', 'mbs@ee.ucla.edu', 'Machine Learning for Microcontroller-Class Hardware: A Review', 'The advancements in machine learning opened a new opportunity to bring intelligence to the low-end Internet-of-Things nodes such as microcontrollers. Conventional machine learning deployment has high memory and compute footprint hindering their direct deployment on ultra resource-constrained microcontrollers. This paper highlights the unique requirements of enabling onboard machine learning for microcontroller class devices. Researchers use a specialized model development workflow for resource-limited applications to ensure the compute and latency budget is within the device limits while still maintaining the desired performance. We characterize a closed-loop widely applicable workflow of machine learning model development for microcontroller class devices and show that several classes of applications adopt a specific instance of it. We present both qualitative and numerical insights into different stages of model development by showcasing several use cases. Finally, we identify the open research challenges and unsolved questions demanding careful considerations moving forward.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5055368146', 'Mohammad Khalid Jawed', 'UCLA', 'Machine Learning', 'khalidjm@seas.ucla.edu', 'mBEST: Realtime Deformable Linear Object Detection Through Minimal Bending Energy Skeleton Pixel Traversals', 'Robotic manipulation of deformable materials is a challenging task that often requires realtime visual feedback. This is especially true for deformable linear objects (DLOs) or “rods”, whose slender and flexible structures make proper tracking and detection nontrivial. To address this challenge, we presentmBEST, a robust algorithm for the realtime detection of DLOs that is capable of producing an ordered pixel sequence of each DLO''s centerline along with segmentation masks. Our algorithm obtains a binary mask of the DLOs and then thins it to produce a skeleton pixel representation. After refining the skeleton to ensure topological correctness, the pixels are traversed to generate paths along each unique DLO. At the core of our algorithm, we postulate that intersections can be robustly handled by choosing the combination of paths that minimizes the cumulative bending energy of the DLO(s). We show that this simple and intuitive formulation outperforms the state-of-the-art methods for detecting DLOs with large numbers of sporadic crossings ranging from curvatures with high variance to nearly-parallel configurations. Furthermore, our method achieves a significant performance improvement of approximately 50% faster runtime and better scaling over the state of the art.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5011624405', 'Peter Reiher', 'UCLA', 'Machine Learning', 'reiher@cs.ucla.edu', 'On Explainable and Adaptable Detection of Distributed Denial-of-Service Traffic', 'Launched from numerous end-hosts throughout the Internet, a distributed denial-of-service (DDoS) attack can exhaust the network bandwidth or other resources of a victim, cripple its service, and make it unavailable to legitimate clients. Recently many learning-based approaches attempt to detect DDoS attacks, but their results are often hardly explainable to users and their models are seldom adaptable to new environments. In this paper, we propose a new learning-based DDoS detection approach. It detects DDoS attacks via an enhanced k-nearest neighbors (KNN) algorithm, which utilizes a k-dimensional (KD) tree to speed up the detection process, and classifies DDoS sources at a fine granularity according to each IP''s risk level. Compared to previous DDoS detection approaches, this approach outputs explanatory information that enables network administrators to easily inspect detection results and make necessary interventions. Moreover, this approach is adaptable in that users do not need to retrain the detection model to have it fit with a new network environment. We evaluated this approach in both simulated environments and the real world, achieving more than 95.6% accuracy in detecting DDoS attacks at line speed. In addition, we carried out a human subject study on its explainability, demonstrating that the outputs can help people better understand the attack and make interventions precisely and promptly.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5084229134', 'Puneet Gupta', 'UCLA', 'Machine Learning', 'puneetg@ucla.edu', 'A 4.4–75-TOPS/W 14-nm Programmable, Performance- and Precision-Tunable All-Digital Stochastic Computing Neural Network Inference Accelerator', 'We present the first programmable and precision-tunable Stochastic Computing (SC) neural network (NN) inference accelerator. The use of SC makes it possible to achieve multiply-accumulate (MAC) density of 38.4k MAC/mm2, enabling a level of spatial data reuse unachievable to conventional, fixed-point architectures. This extensive reuse amortizes the cost of SC conversion and reduces the number of memory accesses, which can otherwise consume significant energy and latency. Our accelerator is a stand-alone architecture, with a custom instruction set architecture (ISA), and support for end-to-end model inference with convolutional and fully-connected layers of variable input and filter sizes. Further, it demonstrates extensive accuracy-latency trade-offs by varying the stream length. The 14nm demonstration chip achieves 2.4 TOPS and 75 TOPS/W peak throughput and energy efficiency, outperforming comparable fixed-point accelerators.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5022329872', 'Ramin Ramezani', 'UCLA', 'Machine Learning', 'raminr@ucla.edu', 'Data Generation Using Simulation Technology to Improve Perception Mechanism of Autonomous Vehicles', 'Abstract Recent advancements in computer graphics technology allow more realistic rendering of car driving environments. They have enabled self-driving car simulators such as DeepGTA-V and CARLA (Car Learning to Act) to generate large amounts of synthetic data that can complement the existing real-world dataset in training autonomous car perception. Furthermore, since self-driving car simulators allow full control of the environments, they can generate dangerous driving scenarios that the real-world dataset lacks such as bad weather and accident scenarios. In this paper, we will demonstrate the effectiveness of combining data gathered from the real-world with data generated in simulated world to train perception system on object detection and localization task. We will also propose a multi-level deep learning perception framework that aims to emulate a human learning experience in which series of tasks from simple to more difficult ones are learnt in a certain domain. The autonomous car perceptron can learn from easy-to-drive scenarios to more challenging ones customized by simulation software.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5002037883', 'Stanley Osher', 'UCLA', 'Machine Learning', 'sjo@math.ucla.edu', 'Scheduled Restart Momentum for Accelerated Stochastic Gradient Descent', 'Stochastic gradient descent (SGD) algorithms, with constant momentum and its variants such as Adam, are the optimization methods of choice for training deep neural networks (DNNs). There is great interest in speeding up the convergence of these methods due to their high computational expense. Nesterov accelerated gradient with a time-varying momentum (NAG) improves the convergence rate of gradient descent for convex optimization using a specially designed momentum; however, it accumulates error when the stochastic gradient is used, slowing convergence at best and diverging at worst. In this paper, we propose scheduled restart SGD (SRSGD), a new NAG-style scheme for training DNNs. SRSGD replaces the constant momentum in SGD by the increasing momentum in NAG but stabilizes the iterations by resetting the momentum to zero according to a schedule. Using a variety of models and benchmarks for image classification, we demonstrate that, in training DNNs, SRSGD significantly improves convergence and generalization; for instance, in training ResNet-200 for ImageNet classification, SRSGD achieves an error rate of 20.93% versus the benchmark of 22.13%. These improvements become more significant as the network grows deeper. Furthermore, on both CIFAR and ImageNet, SRSGD reaches similar or even better error rates with significantly fewer training epochs compared to the SGD baseline. Our implementation of SRSGD is available at https://github.com/minhtannguyen/SRSGD.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5037514446', 'Adriana H. Tremoulet', 'UCSD', 'Machine Learning', 'atremoulet@health.ucsd.edu', 'A deep convolutional neural network for Kawasaki disease diagnosis', 'Kawasaki disease (KD), the most common cause of acquired heart disease in children, can be easily missed as it shares clinical findings with other pediatric illnesses, leading to risk of myocardial infarction or death. KD remains a clinical diagnosis for which there is no diagnostic test, yet there are classic findings on exam that can be captured in a photograph. This study aimed to develop a deep convolutional neural network, KD-CNN, to differentiate photographs of KD clinical signs from those of other pediatric illnesses. To create the dataset, we used an innovative combination of crowdsourcing images and downloading from public domains on the Internet. KD-CNN was then pretrained using transfer learning from VGG-16 and fine-tuned on the KD dataset, and methods to compensate for limited data were explored to improve model performance and generalizability. KD-CNN achieved a median AUC of 0.90 (IQR 0.10 from tenfold cross validation), with a sensitivity of 0.80 (IQR 0.18) and specificity of 0.85 (IQR 0.19) to distinguish between children with and without clinical manifestations of KD. KD-CNN is a novel application of CNN in medicine, with the potential to assist clinicians in differentiating KD from other pediatric illnesses and thus reduce KD morbidity and mortality.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5092007889', 'Babak Salimi', 'UCSD', 'Machine Learning', 'bsalimi@ucsd.edu', 'OTClean: Data Cleaning for Conditional Independence Violations using Optimal Transport', 'Ensuring Conditional Independence (CI) constraints is pivotal for the development of fair and trustworthy machine learning models. In this paper, we introduce OTClean, a framework that harnesses optimal transport theory for data repair under CI constraints. Optimal transport theory provides a rigorous framework for measuring the discrepancy between probability distributions, thereby ensuring control over data utility. We formulate the data repair problem concerning CIs as a Quadratically Constrained Linear Program (QCLP) and propose an alternating method for its solution. However, this approach faces scalability issues due to the computational cost associated with computing optimal transport distances, such as the Wasserstein distance. To overcome these scalability challenges, we reframe our problem as a regularized optimization problem, enabling us to develop an iterative algorithm inspired by Sinkhorn''s matrix scaling algorithm, which efficiently addresses high-dimensional and large-scale data. Through extensive experiments, we demonstrate the efficacy and efficiency of our proposed methods, showcasing their practical utility in real-world data cleaning and preprocessing tasks. Furthermore, we provide comparisons with traditional approaches, highlighting the superiority of our techniques in terms of preserving data utility while ensuring adherence to the desired CI constraints.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5019931011', 'Farinaz Koushanfar', 'UCSD', 'Machine Learning', 'farinaz@ucsd.edu', 'Tutorial: Toward Robust Deep Learning against Poisoning Attacks', 'Deep Learning (DL) has been increasingly deployed in various real-world applications due to its unprecedented performance and automated capability of learning hidden representations. While DL can achieve high task performance, the training process of a DL model is both time- and resource-consuming. Therefore, current supply chains of the DL models assume the customers obtain pre-trained Deep Neural Networks (DNNs) from the third-party providers that have sufficient computing power. In the centralized setting, the model designer trains the DL model using the local dataset. However, the collected training data may contain erroneous or poisoned data points. The model designer might craft malicious training samples and inject a backdoor in the DL model distributed to the users. As a result, the user’s model will malfunction. In the federated learning setting, the cloud server aggregates local models trained on individual local datasets and updates the global model. In this scenario, the local client could poison the local training set and/or arbitrarily manipulate the local update. If the cloud server incorporates the malicious local gradients in model aggregation, the resulting global model will have degraded performance or backdoor behaviors. In this article, we present a comprehensive overview of contemporary data poisoning and model poisoning attacks against DL models in both centralized and federated learning scenarios. In addition, we review existing detection and defense t', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5077882926', 'Florian Meyer', 'UCSD', 'Machine Learning', 'flmeyer@ucsd.edu', 'Neural Enhanced Belief Propagation for Multiobject Tracking', 'Algorithmic solutions for multi-object tracking (MOT) are a key enabler for applications in autonomous navigation and applied ocean sciences. State-of-the-art MOT methods fully rely on a statistical model and typically use preprocessed sensor data as measurements. In particular, measurements are produced by a detector that extracts potential object locations from the raw sensor data collected at discrete time steps. This preparatory processing step reduces data flow and computational complexity but may result in a loss of information. State-of-the-art Bayesian MOT methods that are based on belief propagation (BP) systematically exploit graph structures of the statistical model to reduce computational complexity and improve scalability. However, as a fully model-based approach, BP can provide highly suboptimal estimates when there is a mismatch between the statistical model and the true data-generating process. Existing BP-based MOT methods can further only make use of preprocessed measurements. In this paper, we introduce a variant of BP that combines model-based with data-driven MOT. The proposed neural enhanced belief propagation (NEBP) method complements the statistical model of BP by information learned from raw sensor data. This approach conjectures that the learned information can reduce model mismatch and thus improve data association and false alarm rejection. Our NEBP method improves tracking performance compared to model-based methods. At the same time, it inherits ', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5005081662', 'Henry D. I. Abarbanel', 'UCSD', 'Machine Learning', 'habarbanel@ucsd.edu', 'Constraining chaos: Enforcing dynamical invariants in the training of reservoir computers', 'Drawing on ergodic theory, we introduce a novel training method for machine learning based forecasting methods for chaotic dynamical systems. The training enforces dynamical invariants-such as the Lyapunov exponent spectrum and the fractal dimension-in the systems of interest, enabling longer and more stable forecasts when operating with limited data. The technique is demonstrated in detail using reservoir computing, a specific kind of recurrent neural network. Results are given for the Lorenz 1996 chaotic dynamical system and a spectral quasi-geostrophic model of the atmosphere, both typical test cases for numerical weather prediction.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5012547577', 'Jessica Sorrell', 'UCSD', 'Machine Learning', 'jess@jhu.edu', 'Reproducibility in learning', 'We introduce the notion of a reproducible algorithm in the context of learning. A reproducible learning algorithm is resilient to variations in its samples — with high probability, it returns the exact same output when run on two samples from the same underlying distribution. We begin by unpacking the definition, clarifying how randomness is instrumental in balancing accuracy and reproducibility. We initiate a theory of reproducible algorithms, showing how reproducibility implies desirable properties such as data reuse and efficient testability. Despite the exceedingly strong demand of reproducibility, there are efficient reproducible algorithms for several fundamental problems in statistics and learning. First, we show that any statistical query algorithm can be made reproducible with a modest increase in sample complexity, and we use this to construct reproducible algorithms for finding approximate heavy-hitters and medians. Using these ideas, we give the first reproducible algorithm for learning halfspaces via a reproducible weak learner and a reproducible boosting algorithm. Interestingly, we utilize a connection to foams as a higher-dimension randomized rounding scheme. Finally, we initiate the study of lower bounds and inherent tradeoffs for reproducible algorithms, giving nearly tight sample complexity upper and lower bounds for reproducible versus nonreproducible SQ algorithms.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5039500313', 'Jingbo Shang', 'UCSD', 'Machine Learning', 'jshang@ucsd.edu', 'PrimeNet: Pre-training for Irregular Multivariate Time Series', 'Real-world applications often involve irregular time series, for which the time intervals between successive observations are non-uniform. Irregularity across multiple features in a multi-variate time series further results in a different subset of features at any given time (i.e., asynchronicity). Existing pre-training schemes for time-series, however, often assume regularity of time series and make no special treatment of irregularity. We argue that such irregularity offers insight about domain property of the data—for example, frequency of hospital visits may signal patient health condition—that can guide representation learning. In this work, we propose PrimeNet to learn a self-supervised representation for irregular multivariate time-series. Specifically, we design a time sensitive contrastive learning and data reconstruction task to pre-train a model. Irregular time-series exhibits considerable variations in sampling density over time. Hence, our triplet generation strategy follows the density of the original data points, preserving its native irregularity. Moreover, the sampling density variation over time makes data reconstruction difficult for different regions. Therefore, we design a data masking technique that always masks a constant time duration to accommodate reconstruction for regions of different sampling density. We learn with these tasks using unlabeled data to build a pre-trained model and fine-tune on a downstream task with limited labeled data, in contras', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5077387335', 'Jishen Zhao', 'UCSD', 'Machine Learning', 'jzhao@ucsd.edu', 'Learning Bounded Context-Free-Grammar via LSTM and the Transformer: Difference and the Explanations', 'Long Short-Term Memory (LSTM) and Transformers are two popular neural architectures used for natural language processing tasks. Theoretical results show that both are Turing-complete and can represent any context-free language (CFL).In practice, it is often observed that Transformer models have better representation power than LSTM. But the reason is barely understood. We study such practical differences between LSTM and Transformer and propose an explanation based on their latent space decomposition patterns. To achieve this goal, we introduce an oracle training paradigm, which forces the decomposition of the latent representation of LSTMand the Transformer and supervises with the transitions of the Pushdown Automaton (PDA) of the corresponding CFL. With the forced decomposition, we show that the performance upper bounds of LSTM and Transformer in learning CFL are close: both of them can simulate a stack and perform stack operation along with state transitions. However, the absence of forced decomposition leads to the failure of LSTM models to capture the stack and stack operations, while having a marginal impact on the Transformer model. Lastly, we connect the experiment on the prototypical PDA to a real-world parsing task to re-verify the conclusions', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040382316', 'Johnatan Aljadeff', 'UCSD', 'Machine Learning', 'aljadeff@ucsd.edu', 'Multiplicative Shot-Noise: A New Route to Stability of Plastic Networks', 'Fluctuations of synaptic weights, among many other physical, biological, and ecological quantities, are driven by coincident events of two "parent" processes. We propose a multiplicative shot-noise model that can capture the behaviors of a broad range of such natural phenomena, and analytically derive an approximation that accurately predicts its statistics. We apply our results to study the effects of a multiplicative synaptic plasticity rule that was recently extracted from measurements in physiological conditions. Using mean-field theory analysis and network simulations, we investigate how this rule shapes the connectivity and dynamics of recurrent spiking neural networks. The multiplicative plasticity rule is shown to support efficient learning of input stimuli, and it gives a stable, unimodal synaptic-weight distribution with a large fraction of strong synapses. The strong synapses remain stable over long times but do not "run away." Our results suggest that the multiplicative shot-noise offers a new route to understand the tradeoff between flexibility and stability in neural circuits and other dynamic networks.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5046609009', 'Manmohan Chandraker', 'UCSD', 'Machine Learning', 'mkchandraker@ucsd.edu', 'Controllable Dynamic Multi-Task Architectures', 'Multi-task learning commonly encounters competition for resources among tasks, specifically when model capac-ity is limited. This challenge motivates models which al-low control over the relative importance of tasks and total compute cost during inference time. In this work, we pro-pose such a controllable multi-task network that dynami-cally adjusts its architecture and weights to match the de-sired task preference as well as the resource constraints. In contrast to the existing dynamic multi-task approaches that adjust only the weights within a fixed architecture, our approach affords the flexibility to dynamically control the total computational cost and match the user-preferred task importance better. We propose a disentangled training of two hype rnetwo rks, by exploiting task affinity and a novel branching regularized loss, to take input prefer-ences and accordingly predict tree-structured models with adapted weights. Experiments on three multi-task bench-marks, namely PASCAL-Context, NYU-v2, and CIFAR-100, show the efficacy of our approach. Project page is available at https://www.nec-labs.com/-mas/DYMU.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5054598974', 'Michael C. Yip', 'UCSD', 'Machine Learning', 'yip@ucsd.edu', 'Markerless Camera-to-Robot Pose Estimation via Self-Supervised Sim-to-Real Transfer', 'Solving the camera-to-robot pose is a fundamental requirement for vision-based robot control, and is a process that takes considerable effort and cares to make accurate. Traditional approaches require modification of the robot via markers, and subsequent deep learning approaches enabled markerless feature extraction. Mainstream deep learning methods only use synthetic data and rely on Domain Randomization to fill the sim-to-real gap, because acquiring the 3D annotation is labor-intensive. In this work, we go beyond the limitation of 3D annotations for real-world data. We propose an end-to-end pose estimation framework that is capable of online camera-to-robot calibration and a self-supervised training method to scale the training to unlabeled real-world data. Our framework combines deep learning and geometric vision for solving the robot pose, and the pipeline is fully differentiable. To train the Camera-to-Robot Pose Estimation Network (CtRNet), we leverage foreground segmentation and differentiable rendering for image-level self-supervision. The pose prediction is visualized through a renderer and the image loss with the input image is back-propagated to train the neural network. Our experimental results on two public real datasets confirm the effectiveness of our approach over existing works. We also integrate our framework into a visual servoing system to demonstrate the promise of real-time precise robot pose estimation for automation tasks.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5052874876', 'Michael D. Todd', 'UCSD', 'Machine Learning', 'mdtodd@ucsd.edu', 'Improved Vision-Based Method for Detection of Unauthorized Intrusion by Construction Sites Workers', 'The construction site environment is quite complex with many dangerous hazards (e.g., foundation pits, holes). To avoid injuries, workers must wear helmets that are color-coded for the specific type of work, which is helpful to identify whether workers are in permitted areas. Therefore, it is possible to identify unauthorized intrusion by classifying the safety helmets. This study proposes a vision-based method called Helmet–Yolov5 to automatically detect unauthorized intrusions by workers on construction sites. Multiple improvement measures are made to enhance the model performance. First, the attention mechanism is used to enhance the weights of object regions in the image, which makes the detection of small objects more effective. Second, atrous spatial pyramid pooling is adopted to preserve the detail information of the image. Third, the universal upsampling operator is introduced to fuse image features at different scales. To verify the effectiveness of the improved model, images collected from a real construction site are used to build a large-scale image dataset of safety helmets for model testing. It shows that the proposed Helmet-Yolov5 model is more accurate than the original Yolov5 model, also with high inference speed. Compared to other state-of-the-art models (e.g., Yolov4), the Helmet-Yolov5 model has considerable advantages in term of high detection accuracy and efficiency.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5102796459', 'Mikhail Belkin', 'UCSD', 'Machine Learning', 'mbelkin@ucsd.edu', 'Mechanism for feature learning in neural networks and backpropagation-free machine learning models', 'Understanding how neural networks learn features, or relevant patterns in data, for prediction is necessary for their reliable use in technological and scientific applications. In this work, we presented a unifying mathematical mechanism, known as average gradient outer product (AGOP), that characterized feature learning in neural networks. We provided empirical evidence that AGOP captured features learned by various neural network architectures, including transformer-based language models, convolutional networks, multilayer perceptrons, and recurrent neural networks. Moreover, we demonstrated that AGOP, which is backpropagation-free, enabled feature learning in machine learning models, such as kernel machines, that a priori could not identify task-specific features. Overall, we established a fundamental mechanism that captured feature learning in neural networks and enabled feature learning in general machine learning models.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5068831718', 'Mohan M. Trivedi', 'UCSD', 'Machine Learning', 'mtrivedi@ucsd.edu', 'Patterns of vehicle lights: Addressing complexities of camera-based vehicle light datasets and metrics', 'This paper explores the representation of vehicle lights in computer vision and its implications for various pattern recognition tasks in autonomous driving. Different representations for vehicle lights, including bounding boxes, center points, corner points, and segmentation masks, are discussed in terms of their strengths and weaknesses toward a variety of domain tasks, as well as associated data collection and annotation challenges. This leads to the introduction of the LISA Vehicle Lights Dataset, providing light annotations related to position, state, color, and signal, specifically designed for downstream applications in vehicle detection, intent and trajectory prediction, and safe path planning. A comparison of existing vehicle light datasets is provided, highlighting the unique features and limitations of each dataset. Because occlusions from vehicle pose and passing objects can limit camera observation, we introduce a group of Light Visibility neural networks, which take as input a detected vehicle image and return as output whether a corresponding vehicle light is present in the image. This is especially important for the evaluation of light localizations, states, and signals, as systems decisions should account for differences of lights being in unknown states due to occlusion versus model uncertainty. We show that our trained Light Visibility Models achieve over 90% accuracy on each of the four light classes. Our dataset and model are made available at https://cvr', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5090671359', 'Nadia Polikarpova', 'UCSD', 'Machine Learning', 'npolikarpova@ucsd.edu', 'babble: Learning Better Abstractions with E-Graphs and Anti-unification', 'Library learning compresses a given corpus of programs by extracting common structure from the corpus into reusable library functions. Prior work on library learning suffers from two limitations that prevent it from scaling to larger, more complex inputs. First, it explores too many candidate library functions that are not useful for compression. Second, it is not robust to syntactic variation in the input. We propose library learning modulo theory (LLMT), a new library learning algorithm that additionally takes as input an equational theory for a given problem domain. LLMT uses e-graphs and equality saturation to compactly represent the space of programs equivalent modulo the theory, and uses a novel e-graph anti-unification technique to find common patterns in the corpus more directly and efficiently. We implemented LLMT in a tool named babble. Our evaluation shows that babble achieves better compression orders of magnitude faster than the state of the art. We also provide a qualitative evaluation showing that babble learns reusable functions on inputs previously out of reach for library learning.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5043325212', 'Nuno Vasconcelos', 'UCSD', 'Machine Learning', 'nuno@ucsd.edu', 'Calibrating Deep Neural Networks by Pairwise Constraints', 'It is well known that deep neural networks (DNNs) pro-duce poorly calibrated estimates of class-posterior prob-abilities. We hypothesize that this is due to the limited calibration supervision provided by the cross-entropy loss, which places all emphasis on the probability of the true class and mostly ignores the remaining. We consider how each example can supervise all classes and show that the calibration of a C-way classification problem is equivalent to the calibration of C(C - 1) /2 pairwise binary classifi-cation problems that can be derived from it. This suggests the hypothesis that DNN calibration can be improved by providing calibration supervision to all such binary prob-lems. An implementation of this calibration by pairwise constraints (CPC) is then proposed, based on two types of binary calibration constraints. This is finally shown to be implementable with a very minimal increase in the complex-ity of cross-entropy training. Empirical evaluations of the proposed CPC method across multiple datasets and DNN architectures demonstrate state-of-the-art calibration per-formance.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5055778695', 'Rayan Saab', 'UCSD', 'Machine Learning', 'rsaab@ucsd.edu', 'Post-training Quantization for Neural Networks with Provable Guarantees', '.While neural networks have been remarkably successful in a wide array of applications, implementing them in resource-constrained hardware remains an area of intense research. By replacing the weights of a neural network with quantized (e.g., 4-bit, or binary) counterparts, massive savings in computation cost, memory, and power consumption are attained. To that end, we generalize a post-training neural network quantization method, GPFQ, that is based on a greedy path-following mechanism. Among other things, we propose modifications to promote sparsity of the weights, and rigorously analyze the associated error. Additionally, our error analysis expands the results of previous work on GPFQ to handle general quantization alphabets, showing that for quantizing a single-layer network, the relative square error essentially decays linearly in the number of weights, i.e., level of overparametrization. Our result holds across a range of input distributions and for both fully connected and convolutional architectures thereby also extending previous results. To empirically evaluate the method, we quantize several common architectures with few bits per weight, and test them on ImageNet, showing only minor loss of accuracy compared to unquantized models. We also demonstrate that standard modifications, such as bias correction and mixed precision quantization, further improve accuracy.Keywordsdeep neural networksquantization of neural networksgreedy algorithmssparsityMSC codes68T0768W2562M', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5000231774', 'Ryan Kastner', 'UCSD', 'Machine Learning', 'kastner@ucsd.edu', 'Greater than the Sum of its LUTs: Scaling Up LUT-based Neural Networks with AmigoLUT', 'Applications like high-energy physics and cybersecurity require extremely high throughput and low latency neural network (NN) inference. Lookup-table-based NNs address these constraints by implementing NNs as lookup tables (LUTs), achieving inference latency on the order of nanoseconds. Since LUTs are a fundamental FPGA building block, LUT-based NNs efficiently map to FPGAs. LogicNets (and its successors) form one class of LUT-based NNs that target FPGAs, mapping neurons directly to LUTs to meet low latency constraints with minimal resources. However, it is difficult to build larger, more performant LUT-based NNs like LogicNets because LUT usage increases exponentially with respect to neuron fan-in (i.e., number of synapses X synapse bitwidth). A large LUT-based NN quickly runs out of LUTs on an FPGA. Our work AmigoLUT addresses this issue by creating ensembles of smaller LUT-based NNs that scale linearly with respect to the number of models. AmigoLUT improves the scalability of LUT-based NNs, reaching higher throughput with up to an order of magnitude fewer LUTs than the largest LUT-based NNs.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5105369696', 'Sujit Dey', 'UCSD', 'Machine Learning', 'dey@ece.ucsd.edu', 'Uncertainty-aware Task Offloading for Multi-vehicle Perception Fusion over Vehicular Edge Computing', 'Multi-vehicle perception fusion is an emerging advanced vehicular application providing Vehicle Users (VUs) with comprehensive driving assistance. This involves each VU''s individual vehicular perception tasks and additional fusion tasks at the end. However, performing these perception fusion applications on some VUs may not be feasible due to the applications'' high computing complexity. Vehicular Edge Computing (VEC) server, which is collocated with a Road-side Unit, together with VUs'' Vehicular Local Computing (VLC) units can be used to support these perception fusion applications through task offloading. Achieving this edge-collaborated perception fusion with task offloading involves multiple challenges: (i) frequently varying uplink channel conditions, (ii) sequential and parallel task dependencies, and (iii) uncertain task composition induced by unknown object detection outputs in the dynamic driving environment. In this paper, a real-time mechanism is proposed to minimize the end-to-end delay of an edge-collaborated multi-vehicle perception fusion application by addressing these challenges. Based on the real-time channel conditions, VEC and VLC server capacities, and number of detected objects, this algorithm jointly determines the bandwidth allocation, task partitioning, offloading, and execution scheduling for all the involved tasks of the multi-vehicle perception fusion application. Numerical results show that the proposed approach can significantly reduce the end-to-', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5101486879', 'Tauhidur Rahman', 'UCSD', 'Machine Learning', 'trahman@ucsd.edu', 'V2CE: Video to Continuous Events Simulator', 'Dynamic Vision Sensor (DVS)-based solutions have recently garnered significant interest across various computer vision tasks, offering notable benefits in terms of dynamic range, temporal resolution, and inference speed. However, as a relatively nascent vision sensor compared to Active Pixel Sensor (APS) devices such as RGB cameras, DVS suffers from a dearth of ample labeled datasets. Prior efforts to convert APS data into events often grapple with issues such as a considerable domain shift from real events, the absence of quantified validation, and layering problems within the time axis. In this paper, we present a novel method for video-to-events stream conversion from multiple perspectives, considering the specific characteristics of DVS. A series of carefully designed losses helps enhance the quality of generated event voxels significantly. We also propose a novel local dynamic-aware timestamp inference strategy to accurately recover event timestamps from event voxels in a continuous fashion and eliminate the temporal layering problem. Results from rigorous validation through quantified metrics at all stages of the pipeline establish our method unquestionably as the current state-of-the-art (SOTA). The code can be found at bit.ly/v2ce.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5044141636', 'Terrence J. Sejnowski', 'UCSD', 'Machine Learning', 'sejnowski@salk.edu', 'Random noise promotes slow heterogeneous synaptic dynamics important for robust working memory computation', 'Recurrent neural networks (RNNs) based on model neurons that communicate via continuous signals have been widely used to study how cortical neural circuits perform cognitive tasks. Training such networks to perform tasks that require information maintenance over a brief period (i.e., working memory tasks) remains a challenge. Inspired by the robust information maintenance observed in higher cortical areas such as the prefrontal cortex, despite substantial inherent noise, we investigated the effects of random noise on RNNs across different cognitive functions, including working memory. Our findings reveal that random noise not only speeds up training but also enhances the stability and performance of RNNs on working memory tasks. Importantly, this robust working memory performance induced by random noise during training is attributed to an increase in synaptic decay time constants of inhibitory units, resulting in slower decay of stimulus-specific activity critical for memory maintenance. Our study reveals the critical role of noise in shaping neural dynamics and cognitive functions, suggesting that inherent variability may be a fundamental feature driving the specialization of inhibitory neurons to support stable information processing in higher cortical regions.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001760915', 'Zhuowen Tu', 'UCSD', 'Machine Learning', 'ztu@ucsd.edu', 'MasQCLIP for Open-Vocabulary Universal Image Segmentation', 'We present a new method for open-vocabulary universal image segmentation, which is capable of performing instance, semantic, and panoptic segmentation under a unified framework. Our approach, called MasQCLIP, seamlessly integrates with a pre-trained CLIP model by utilizing its dense features, thereby circumventing the need for extensive parameter training. MasQCLIP emphasizes two new aspects when building an image segmentation method with a CLIP model: 1) a student-teacher module to deal with masks of the novel (unseen) classes by distilling information from the base (seen) classes; 2) a fine-tuning process to update model parameters for the queries Q within the CLIP model. Thanks to these two simple and intuitive designs, MasQCLIP is able to achieve state-of-the-art performances with a substantial gain over the competing methods by a large margin across all three tasks, including open-vocabulary instance, semantic, and panoptic segmentation. Project page is at https://masqclip.github.io/.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5029857320', 'Andreas M. Rauschecker', 'UCSF', 'Machine Learning', 'andreas.rauschecker@ucsf.edu', 'Segmenting with confidence through uncertainty quantification for brain tumor imaging', 'A major barrier to clinical adoption of artificial intelligence (AI) for brain tumor monitoring is the lack of calibrated uncertainty in automated segmentation, limiting clinician trust. We developed a deep learning framework that generates uncertainty estimates for meningioma segmentation on brain MRI. Evidential deep learning ensembles were trained on 1655 post-contrast T1-weighted MRIs (788 patients) to capture aleatoric-like and epistemic-like uncertainty. Architecturally homogeneous and heterogeneous ensembles were evaluated on an independent test set of 68 MRIs (43 patients) and compared with existing methods. Performance was assessed using Dice similarity coefficient, spatial agreement between uncertainty maps and neuroradiologist-identified ambiguous regions, and calibration of volumetric credible intervals. The model achieved high accuracy (median Dice 0.93), with uncertainty maps aligning with ambiguous regions and well-calibrated volume estimates. External validation in 353 patients confirmed generalizability (median Dice 0.92), supporting safer clinical AI deployment and enabling calibrated uncertainty estimation for lesion segmentation beyond meningiomas.', 2026);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5028325717', 'Ashish Raj', 'UCSF', 'Machine Learning', 'ashish.raj@ucsf.edu', 'Deconvolving Passive Diffusion on the Structural Network from Functional Brain Signals', 'It is commonly understood that brain regions perform re-gionally specific computations that are then transmitted glob-ally through the whole-brain white matter network. However, the success of network diffusion models for predicting the brain''s functional connectivity suggests that a significant portion of recorded brain signal is attributable to passive diffusion through the structural network. We can therefore inter-pret the global signal as a convolution of an innovation sig-nal from novel regional computations with a passive signal merely flowing through the network. Since the innovation signal contains the information of interest, there is a need to deconvolve the innovation signal from the passive signal in functional brain recordings. Here, we estimate the innovation signal in functional MRI by using the Network Diffusion Model (NDM) to measure the amount of global signal dif-fusion in data from 64 Human Connectome Project (HCP) subjects, then invert the NDM to perform a Network Diffusion Deconvolution (NDD). We show that the estimated in-novation signal has different BOLD power gradients, forms a more segregated functional network, reorganizes resting -state networks, and constrains the signal in a motor task to the expected motor regions. Overall, NDD highlights a promising new approach to study fMRI and connectivity.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5074319772', 'Chiung‐Yu Huang', 'UCSF', 'Machine Learning', 'chiung-yu.huang@ucsf.edu', 'Efficient data integration under prior probability shift', 'Conventional supervised learning usually operates under the premise that data are collected from the same underlying population. However, challenges may arise when integrating new data from different populations, resulting in a phenomenon known as dataset shift. This paper focuses on prior probability shift, where the distribution of the outcome varies across datasets but the conditional distribution of features given the outcome remains the same. To tackle the challenges posed by such shift, we propose an estimation algorithm that can efficiently combine information from multiple sources. Unlike existing methods that are restricted to discrete outcomes, the proposed approach accommodates both discrete and continuous outcomes. It also handles high-dimensional covariate vectors through variable selection using an adaptive least absolute shrinkage and selection operator penalty, producing efficient estimates that possess the oracle property. Moreover, a novel semiparametric likelihood ratio test is proposed to check the validity of prior probability shift assumptions by embedding the null conditional density function into Neyman''s smooth alternatives (Neyman, 1937) and testing study-specific parameters. We demonstrate the effectiveness of our proposed method through extensive simulations and a real data example. The proposed methods serve as a useful addition to the repertoire of tools for dealing dataset shifts.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5050276927', 'Daniela Ushizima', 'UCSF', 'Machine Learning', 'dushizima@lbl.gov', 'Lithium Metal Battery Quality Control via Transformer–CNN Segmentation', 'Lithium metal battery (LMB) has the potential to be the next-generation battery system because of its high theoretical energy density. However, defects known as dendrites are formed by heterogeneous lithium (Li) plating, which hinders the development and utilization of LMBs. Non-destructive techniques to observe the dendrite morphology often use X-ray computed tomography (XCT) to provide cross-sectional views. To retrieve three-dimensional structures inside a battery, image segmentation becomes essential to quantitatively analyze XCT images. This work proposes a new semantic segmentation approach using a transformer-based neural network called TransforCNN that is capable of segmenting out dendrites from XCT data. In addition, we compare the performance of the proposed TransforCNN with three other algorithms, U-Net, Y-Net, and E-Net, consisting of an ensemble network model for XCT analysis. Our results show the advantages of using TransforCNN when evaluating over-segmentation metrics, such as mean intersection over union (mIoU) and mean Dice similarity coefficient (mDSC), as well as through several qualitatively comparative visualizations.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5105924929', 'Danilo Bernardo', 'UCSF', 'Machine Learning', 'dan.bernardo@ucsf.edu', 'Comparison of Feature Engineering and End-to-End Machine Learning for Neonatal Preictal State Classification', 'Abstract Recent strategies to predict neonatal seizure risk using machine learning (ML) in combination with quantitative electroencephalography (QEEG) have primarily focused on subject-level predictions over several days during the postnatal period. Time-dependent neonatal preictal state classification with high temporal resolution remains unexplored. In this study, we utilized QEEG feature engineering for ML classification of preictal states and compared it to an end-to-end ML approach. We used two publicly available EEG seizure datasets with a total of 132 neonates containing a total of 281 h of EEG data and segmented data into preictal and interictal epochs of 20 s duration. We employed the Boruta algorithm with Shapley values for QEEG feature selection into ML models. The performance of ML models was assessed with cross-validation with area under the receiver operator characteristic curve (AUROC), area under the precision-recall curve (AUPRC), Matthews Correlation Coefficient (MCC), and F1 score. Feature selection demonstrated statistical moments, spectral power, and recurrence quantification analysis features as robust predictors of preictal states. QEEG feature selection combined with convolutional LSTM outperformed other ML models at preictal versus interictal classification, with AUROC 0.678, AUPRC 0.218, MCC 0.255, and F1 0.334. Our results demonstrate the feasibility of applying ML to facilitate prediction and understanding of neonatal preictal states.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5091099837', 'Edward F. Chang', 'UCSF', 'Machine Learning', 'changed@neurosurg.ucsf.edu', 'Large-scale single-neuron speech sound encoding across the depth of human cortex', 'Abstract Understanding the neural basis of speech perception requires that we study the human brain both at the scale of the fundamental computational unit of neurons and in their organization across the depth of cortex. Here we used high-density Neuropixels arrays 1–3 to record from 685 neurons across cortical layers at nine sites in a high-level auditory region that is critical for speech, the superior temporal gyrus 4,5 , while participants listened to spoken sentences. Single neurons encoded a wide range of speech sound cues, including features of consonants and vowels, relative vocal pitch, onsets, amplitude envelope and sequence statistics. Neurons at each cross-laminar recording exhibited dominant tuning to a primary speech feature while also containing a substantial proportion of neurons that encoded other features contributing to heterogeneous selectivity. Spatially, neurons at similar cortical depths tended to encode similar speech features. Activity across all cortical layers was predictive of high-frequency field potentials (electrocorticography), providing a neuronal origin for macroelectrode recordings from the cortical surface. Together, these results establish single-neuron tuning across the cortical laminae as an important dimension of speech encoding in human superior temporal gyrus.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5014012806', 'Geoffrey H. Tison', 'UCSF', 'Machine Learning', 'geoff.tison@ucsf.edu', 'A deep foundation model for electrocardiogram interpretation: enabling rare disease detection through transfer learning', 'In healthcare, scarcity of high-quality human-adjudicated labelled data may limit the potential of deep neural networks (DNNs). Foundation models provide an efficient starting point for deep learning that can facilitate effective DNN training with fewer labelled training examples. In this study, we leveraged cardiologist-confirmed labels from a large dataset of 1.6 million electrocardiograms (ECGs) acquired as part of routine clinical care at UCSF between 1986 and 2019 to pre-train a convolutional DNN to predict 68 common ECG diagnoses. To our knowledge, this model is one of the most comprehensive ECG DNN models to date, demonstrating high performance with a median area under the receiver operating curve (AUC) of 0.978, median sensitivity of 0.937, and median specificity of 0.923. We then demonstrate the model''s utility as a foundation model by additionally training (fine-tuning) the DNN to detect three novel ECG diagnoses with relatively small datasets: carcinoid syndrome, pericardial constriction, and rheumatic doming of the mitral valve. Fine-tuning training of the foundation model achieved an AUC of 0.772 (95% CI 0.723-0.816) for carcinoid syndrome, 0.883 (0.863-0.906) for pericardial constriction, and 0.826 (95% CI 0.802-0.854) for rheumatic doming, compared to 0.492 (95% CI 0.434-0.558), 0.689 (95% CI 0.656-0.720), and 0.701 (95% CI 0.657-0.745), respectively, for DNNs trained from scratch on the same small datasets. Our results demonstrate that the ECG foundation model', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5078387994', 'Karunesh Ganguly', 'UCSF', 'Machine Learning', 'karunesh.ganguly@ucsf.edu', 'Separable global and local beta burst dynamics in motor cortex of primates', 'Sensorimotor beta band oscillations are known to modulate during normal movement control and abnormal beta modulation is linked to pathological bradykinesia. However, the functional differences between beta localized to one brain area versus beta synchronized across brain areas remains unclear. We monitored beta bursts in non-human primates, both neurotypical and stroke-impaired, during the performance of complex motor tasks. Across both groups of animals, we identified two distinct beta burst types: global bursts that tend to be synchronized across cortical and subcortical areas, and local bursts that tend to be confined to cortex. These two types exhibited distinct neural dynamics, with global bursts linked to reduced firing variability and overall slowed movements. In contrast, local bursts often occurred during the execution of complex behaviors, particularly during prehension. We found evidence for changes in the distribution of global and local bursts during recovery after stroke. In impaired animals early after stroke, global bursts predominated and were associated with reduced speed and impaired grasping. Notably, recovery of grasping was associated with a reduction in global bursts and an increase in local bursts, suggesting that local bursts may play an important role during prehension. Our findings reveal distinct roles of global and local beta bursts and indicate that the normalization of global and local burst timing tracks recovery of dexterity.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001435363', 'Michael J. Keiser', 'UCSF', 'Machine Learning', 'michael.keiser@ucsf.edu', 'Fuzz Testing Molecular Representation Using Deep Variational Anomaly Generation', 'Researchers are developing increasingly robust molecular representations, motivating the need for thorough methods to stress-test and validate them. Here, we use a variational auto-encoder (VAE), an unsupervised deep learning model, to generate anomalous examples of SELF-referencIng Embedded Strings (SELFIES), a popular molecular string format. These anomalies defy the assertion that all SELFIES convert into valid SMILES strings. Interestingly, we find specific regions within the VAE''s internal landscape (latent space), whose decoding frequently generates inconvertible SELFIES anomalies. The model''s internal landscape self-organization helps with exploring factors affecting molecular representation reliability. We show how VAEs and similar anomaly generation methods can empirically stress-test molecular representation robustness. Additionally, we investigate reasons for the invalidity of some discovered SELFIES strings (version 2.1.1) and suggest changes to improve them, aiming to spark ongoing molecular representation improvement.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5076537498', 'Ramy Arnaout', 'UCSF', 'Machine Learning', 'rarnaout@bidmc.harvard.edu', 'Grade Inflation in Generative Models', 'Generative models hold great potential, but only if one can trust the evaluation of the data they generate. We show that many commonly used quality scores for comparing two-dimensional distributions of synthetic vs. ground-truth data give better results than they should, a phenomenon we call the "grade inflation problem." We show that the correlation score, Jaccard score, earth-mover''s score, and Kullback-Leibler (relative-entropy) score all suffer grade inflation. We propose that any score that values all datapoints equally, as these do, will also exhibit grade inflation; we refer to such scores as "equipoint" scores. We introduce the concept of "equidensity" scores, and present the Eden score, to our knowledge the first example of such a score. We find that Eden avoids grade inflation and agrees better with human perception of goodness-of-fit than the equipoint scores above. We propose that any reasonable equidensity score will avoid grade inflation. We identify a connection between equidensity scores and Rényi entropy of negative order. We conclude that equidensity scores are likely to outperform equipoint scores for generative models, and for comparing low-dimensional distributions more generally.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5006096245', 'Renuka Sriram', 'UCSF', 'Machine Learning', 'renuka.sriram@ucsf.edu', 'Deep Learning-Based Tumor Segmentation of Murine Magnetic Resonance Images of Prostate Cancer Patient-Derived Xenografts', 'BACKGROUND/OBJECTIVE: Longitudinal in vivo studies of murine xenograft models are widely utilized in oncology to study cancer biology and develop therapies. Magnetic resonance imaging (MRI) of these tumors is an invaluable tool for monitoring tumor growth and characterizing the tumors as well. METHODS: -weighted (T2-wt) MRI images from mice implanted with six different prostate cancer patient-derived xenografts (PDX) in the kidneys, liver, and tibia were used. The segmentation pipeline included a slice classifier to identify the slices that had tumors and subsequent training and validation using several U-Net-based segmentation architectures. Multiple combinations of the algorithm and training images for different sites were evaluated for inference quality. RESULTS AND CONCLUSIONS: The slice classifier network achieved 90% accuracy in identifying slices containing tumors. Among the various segmentation architectures tested, the dense residual recurrent U-Net achieved the highest performance in kidney tumors. When evaluated across the kidneys, tibia, and liver, this architecture performed the best when trained on all data as compared to training on only data from a single site (and inferring on a multi-site tumor images), achieving a Dice score of 0.924 across the test set.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5038354675', 'Shawn L. Hervey‐Jumper', 'UCSF', 'Machine Learning', 'shawn.hervey-jumper@ucsf.edu', 'Electrocorticographic Detection of Speech Networks in Glioma-infiltrated Cortex', 'Direct cortical stimulation (DCS) is the clinical gold standard for identifying functional cortex in the human brain, which is essential for the safe removal of brain lesions. Defining the electro-physiological properties of DCS-positive cortical regions may facilitate the identification of critical language regions, thereby permitting safe glioma resections in communities without access. Leveraging a multicenter electrophysiologic dataset of DCS-positive language regions spatially matched with subdural arrays, we analyzed regions identified as functionally critical (DCS+) versus functionally non-critical (DCS-) during intraoperative language mapping. In IDH-mutant gliomas, DCS+ regions exhibited significantly greater speech-related neural activity and enhanced encoding and decoding of linguistic and semantic features. We demonstrate that resting-state classifiers distinguish DCS+ from DCS- regions in IDH-mutant tumors. Task-based and resting-state electrophysiologic distinctions were pathology-specific and not present in IDH-wildtype glioblastomas. These findings may accelerate DCS mapping by guiding surgeons to priority regions, improving efficiency, and patient outcomes.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5030459567', 'Tomiko Oskotsky', 'UCSF', 'Machine Learning', 'tomiko.oskotsky@ucsf.edu', 'Anticlustering for Sample Allocation To Minimize Batch Effects', 'Abstract High throughput sequencing is a powerful tool for processing large amounts of DNA and RNA samples in batches. Proper experimental design and statistical methods are required to mitigate systematic technical factors due to differences in batches (“batch effects”), as data variation due to these non-biological factors can mask actual biological differences. We propose using anticlustering as an automated method to assign samples to balanced batches. Anticlustering effectively negates differences in (numeric and/or categorical) covariates among batches, and implements user-defined restrictions on the number of batches, the number of samples per batch, and whether to assign certain samples to the same batch (“must-link constraints”). A simulation study shows that anticlustering is better at achieving balance among batches than previous approaches. An application from the UCSF-Stanford Endometriosis Center for Discovery, Innovation, Training and Community Engagement (“ENACT”, https://enactcenter.org/ ) is presented as a real-life example. In the application, multiple samples provided by an individual had to be processed on the same batch, so that comparisons among different samples of the same patient were not diluted by batch effects. The novel Two Phase Must Link (2PML) anticlustering algorithm realized the must-link restrictions while simultaneously obtaining balance among batches regarding disease stage, menstrual cycle phase, case versus control sample, and clinical ', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5073603294', 'William A. Weiss', 'UCSF', 'Machine Learning', 'william.weiss@ucsf.edu', 'NOVA: a novel R-package enabling multi-parameter analysis and visualization of neural activity in MEA recordings', 'Multielectrode array (MEA) technology enables simultaneous recording of electrical signals from neuronal networks, producing complex datasets. Current analytical approaches typically examine a limited number of metrics such as mean firing rate and synchronicity, leaving much of the data underutilized. To address this gap, we created NOVA ( Neural Output Visualization and Analysis), an accessible R-based computational tool for comprehensive MEA data interpretation and visualization. NOVA integrates dimensionality reduction through principal component analysis, hierarchical clustering with heatmap generation, and temporal trajectory mapping of network activity patterns. Our code offers both a userfriendly pipeline requiring minimal coding background as well as customizable advanced plotting modules for experienced users. Validation experiments using primary cortical neurons during development and pharmacological manipulation demonstrated NOVA''s capacity to detect subtle activity shifts overlooked by conventional methods. Notably, our unbiased approach identified network burst duration as a stronger contributor to activity variance than commonly reported firing rate metrics, exemplifying NOVA''s utility for discovering meaningful patterns and generating data-driven hypotheses.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100397430', 'Yang Yang', 'UCSF', 'Machine Learning', 'yang.yang@ucsf.edu', 'Cross-D Conv: Cross-Dimensional Transferable Knowledge Base via Fourier Shifting Operation', 'In biomedical imaging analysis, the dichotomy between 2D and 3D data presents a significant challenge. While 3D volumes offer superior real-world applicability, they are less available for each modality and not easy to train in large scale, whereas 2D samples are abundant but less comprehensive. This paper introduces Cross-D Conv operation, a novel approach that bridges the dimensional gap by learning the phase shifting in the Fourier domain. Our method enables seamless weight transfer between 2D and 3D convolution operations, effectively facilitating cross-dimensional learning. The proposed architecture leverages the abundance of 2D training data to enhance 3D model performance, offering a practical solution to the multimodal data scarcity challenge in 3D medical model pretraining. Experimental validation on the RadImagenet (2D) and multimodal volumetric sets demonstrates that our approach achieves comparable or superior performance in feature quality assessment. The enhanced convolution operation presents new opportunities for developing efficient classification and segmentation models in medical imaging. This work represents an advancement in cross-dimensional and multimodal medical image analysis, offering a robust framework for utilizing 2D priors in 3D model pretraining while maintaining computational efficiency of 2D training. Codes & Weights', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5047191296', 'A. Salman Avestimehr', 'USC', 'Machine Learning', 'avestime@usc.edu', 'ApproxIFER: A Model-Agnostic Approach to Resilient and Robust Prediction Serving Systems', 'Due to the surge of cloud-assisted AI services, the problem of designing resilient prediction serving systems that can effectively cope with stragglers and minimize response delays has attracted much interest. The common approach for tackling this problem is replication which assigns the same prediction task to multiple workers. This approach, however, is inefficient and incurs significant resource overheads. Hence, a learning-based approach known as parity model (ParM) has been recently proposed which learns models that can generate ``parities’’ for a group of predictions to reconstruct the predictions of the slow/failed workers. While this learning-based approach is more resource-efficient than replication, it is tailored to the specific model hosted by the cloud and is particularly suitable for a small number of queries (typically less than four) and tolerating very few stragglers (mostly one). Moreover, ParM does not handle Byzantine adversarial workers. We propose a different approach, named Approximate Coded Inference (ApproxIFER), that does not require training any parity models, hence it is agnostic to the model hosted by the cloud and can be readily applied to different data domains and model architectures. Compared with earlier works, ApproxIFER can handle a general number of stragglers and scales significantly better with the number of queries. Furthermore, ApproxIFER is robust against Byzantine workers. Our extensive experiments on a large number of datasets and m', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5101715504', 'Aram Galstyan', 'USC', 'Machine Learning', 'galstyan@isi.edu', 'Cognitively Inspired Learning of Incremental Drifting Concepts', 'Humans continually expand their learned knowledge to new domains and learn new concepts without any interference with past learned experiences. In contrast, machine learning models perform poorly in a continual learning setting, where input data distribution changes over time. Inspired by the nervous system learning mechanisms, we develop a computational model that enables a deep neural network to learn new concepts and expand its learned knowledge to new domains incrementally in a continual learning setting. We rely on the Parallel Distributed Processing theory to encode abstract concepts in an embedding space in terms of a multimodal distribution. This embedding space is modeled by internal data representations in a hidden network layer. We also leverage the Complementary Learning Systems theory to equip the model with a memory mechanism to overcome catastrophic forgetting through implementing pseudo-rehearsal. Our model can generate pseudo-data points for experience replay and accumulate new experiences to past learned experiences without causing cross-task interference.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5063784062', 'Bhaskar Krishnamachari', 'USC', 'Machine Learning', 'bkrishna@usc.edu', 'Correlation-Aware Neural Networks for DDoS Attack Detection in IoT Systems', 'We present a comprehensive study on applying machine learning to detect distributed Denial of service (DDoS) attacks using large-scale Internet of Things (IoT) systems. While prior works and existing DDoS attacks have largely focused on individual nodes transmitting packets at a high volume, we investigate more sophisticated futuristic attacks that use large numbers of IoT devices and camouflage their attack by having each node transmit at a volume typical of benign traffic. We introduce new correlation-aware architectures that take into account the correlation of traffic across IoT nodes. We extensively analyze the proposed architectures by evaluating five different neural network models trained on a dataset derived from a 4060-node real-world IoT system. We observe that long short-term memory (LSTM) and a transformer-based model, in conjunction with the architectures that use correlation information of the IoT nodes, provide higher performance (in terms of F1 score and binary accuracy) than the other models and architectures, especially when the attacker camouflages itself by following benign traffic distribution on each transmitting node. For instance, by using the LSTM model, the distributed correlation-aware architecture gives 81% F1 score for the attacker that camouflages their attack with benign traffic as compared to 35% for the architecture that does not use correlation information. We validate the effectiveness of our proposed detection mechanism by implementing it ', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5001082656', 'C.‐C. Jay Kuo', 'USC', 'Machine Learning', 'cckuo@sipi.usc.edu', 'Recurrent Neural Networks and Their Memory Behavior: A Survey', 'After their inception in the late 1980s, recurrent neural networks (RNNs) as a sequence computing model have seen mushrooming interests in communities of natural language processing, speech recognition, computer vision, etc. Recent variations of RNNs have made breakthroughs in fields such as machine translation where machines can achieve human level quality. RNNs assisted speech recognition technology is providing services on subtitles for live streaming videos. In this survey, we will offer a historical perspective by walking through the early years of RNNs all the way to their modern forms, detailing their most popular architectural designs and, perhaps more importantly, demystify the mathematical aspect behind their memory behaviors.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5100407035', 'Chao Wang', 'USC', 'Machine Learning', 'wang626@usc.edu', 'LinSyn: Synthesizing Tight Linear Bounds for Arbitrary Neural Network Activation Functions', 'Abstract The most scalable approaches to certifying neural network robustness depend on computing sound linear lower and upper bounds for the network’s activation functions. Current approaches are limited in that the linear bounds must be handcrafted by an expert, and can be sub-optimal, especially when the network’s architecture composes operations using, for example, multiplication such as in LSTMs and the recently popular Swish activation. The dependence on an expert prevents the application of robustness certification to developments in the state-of-the-art of activation functions, and furthermore the lack of tightness guarantees may give a false sense of insecurity about a particular model. To the best of our knowledge, we are the first to consider the problem of automatically synthesizing tight linear bounds for arbitrary n-dimensional activation functions. We propose the first fully automated method that achieves tight linear bounds while only leveraging the mathematical definition of the activation function itself. Our method leverages an efficient heuristic technique to synthesize bounds that are tight and usually sound , and then verifies the soundness (and adjusts the bounds if necessary) using the highly optimized branch-and-bound SMT solver, dReal . Even though our method depends on an SMT solver, we show that the runtime is reasonable in practice, and, compared with state of the art, our method often achieves 2-5X tighter final output bounds and more than quadru', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5012068017', 'Cyrus Shahabi', 'USC', 'Machine Learning', 'shahabi@usc.edu', 'HAGEN: Homophily-Aware Graph Convolutional Recurrent Network for Crime Forecasting', 'The goal of the crime forecasting problem is to predict different types of crimes for each geographical region (like a neighborhood or censor tract) in the near future. Since nearby regions usually have similar socioeconomic characteristics which indicate similar crime patterns, recent state-of-the-art solutions constructed a distance-based region graph and utilized Graph Neural Network (GNN) techniques for crime forecasting, because the GNN techniques could effectively exploit the latent relationships between neighboring region nodes in the graph if the edges reveal high dependency or correlation. However, this distance-based pre-defined graph can not fully capture crime correlation between regions that are far from each other but share similar crime patterns. Hence, to make a more accurate crime prediction, the main challenge is to learn a better graph that reveals the dependencies between regions in crime occurrences and meanwhile captures the temporal patterns from historical crime records. To address these challenges, we propose an end-to-end graph convolutional recurrent network called HAGEN with several novel designs for crime prediction. Specifically, our framework could jointly capture the crime correlation between regions and the temporal crime dynamics by combining an adaptive region graph learning module with the Diffusion Convolution Gated Recurrent Unit (DCGRU). Based on the homophily assumption of GNN (i.e., graph convolution works better where neighboring node', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5083283029', 'Daniel A. Lidar', 'USC', 'Machine Learning', 'lidar@usc.edu', 'Beyond unital noise in variational quantum algorithms: noise-induced barren plateaus and limit sets', 'Variational quantum algorithms (VQAs) hold much promise but face the challenge of exponentially small gradients. Unmitigated, this barren plateau (BP) phenomenon leads to an exponential training overhead for VQAs. Perhaps the most pernicious are noise-induced barren plateaus (NIBPs), a type of unavoidable BP arising from open system effects, which have so far been shown to exist for unital noise maps. Here, we generalize the study of NIBPs to more general completely positive, trace-preserving maps, investigating the existence of NIBPs in the unital case and a class of non-unital maps we call Hilbert-Schmidt (HS)-contractive. The latter includes amplitude damping. We identify the associated phenomenon of noise-induced limit sets (NILS) of the VQA cost function and prove its existence for both unital and HS-contractive non-unital noise maps. Along the way, we extend the parameter shift rule of VQAs to the noisy setting. We provide rigorous bounds in terms of the relevant variables that give rise to NIBPs and NILSs, along with numerical simulations of the depolarizing and amplitude-damping maps that illustrate our analytical results.', 2025);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5031941569', 'Ewa Deelman', 'USC', 'Machine Learning', 'deelman@isi.edu', 'Large Language Models for Anomaly Detection in Computational Workflows: From Supervised Fine-Tuning to In-Context Learning', 'Anomaly detection in computational workflows is critical for ensuring system reliability and security. However, traditional rule-based methods struggle to detect novel anomalies. This paper leverages large language models (LLMs) for workflow anomaly detection by exploiting their ability to learn complex data patterns. Two approaches are investigated: (1) supervised fine-tuning (SFT), where pretrained LLMs are fine-tuned on labeled data for sentence classification to identify anomalies, and (2) in-context learning (ICL), where prompts containing task descriptions and examples guide LLMs in few-shot anomaly detection without fine-tuning. The paper evaluates the performance, efficiency, and generalization of SFT models and explores zeroshot and few-shot ICL prompts and interpretability enhancement via chain-of-thought prompting. Experiments across multiple workflow datasets demonstrate the promising potential of LLMs for effective anomaly detection in complex executions.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5075298131', 'Gerald E. Loeb', 'USC', 'Machine Learning', 'gloeb@usc.edu', 'A model for self-organization of sensorimotor function: the spinal monosynaptic loop', 'A novel model of self-organization of early spinal circuitry based on a biologically realistic plant, sensors, and neuronal plasticity in conjunction with empirical observations of fetal development. Without explicit need for guiding genetic rules, connection matrices emerge that support functional self-organization of the mature pattern of Ia to motoneuron connectivity in the spinal circuitry.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5023774940', 'John Paul Walters', 'USC', 'Machine Learning', 'jwalters@isi.edu', 'PipeEdge: Pipeline Parallelism for Large-Scale Model Inference on Heterogeneous Edge Devices', 'Deep neural networks with large model sizes achieve state-of-the-art results for tasks in computer vision and natural language processing. However, such models are too compute- or memory-intensive for resource-constrained edge devices. Prior works on parallel and distributed execution primarily focus on training-rather than inference-using homogeneous accelerators in data centers. We propose PipeEdge, a distributed framework for edge systems that uses pipeline parallelism to both speed up inference and enable running larger, more accurate models that otherwise cannot fit on single edge devices. PipeEdge uses an optimal partition strategy that considers heterogeneity in compute, memory, and network bandwidth. Our empirical evaluation demonstrates that PipeEdge achieves 11.88× and 12.78× speedup using 16 edge devices for the ViT-Huge and BERT-Large models, respectively, with no accuracy loss. Similarly, PipeEdge improves throughput for ViT-Huge (which cannot fit in a single device) by 3.93× over a 4-device baseline using 16 edge devices. Finally, we show up to 4.16× throughput improvement over the state-of-the-art PipeDream when using a heterogeneous set of devices.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5081582862', 'Leana Golubchik', 'USC', 'Machine Learning', 'leana@usc.edu', 'Predicting Inference Latency of Neural Architectures on Mobile Devices', 'Due to the proliferation of inference tasks on mobile devices, state-of-the-art neural architectures are typically designed using Neural Architecture Search (NAS) to achieve good tradeoffs between machine learning accuracy and inference latency. While measuring inference latency of a huge set of candidate architectures during NAS is not feasible, latency prediction for mobile devices is challenging, because of hardware heterogeneity, optimizations applied by machine learning frameworks, and diversity of neural architectures. Motivated by these challenges, we first quantitatively assess the characteristics of neural architectures and mobile devices that have significant effects on inference latency. Based on this assessment, we propose an operation-wise framework which addresses these challenges by developing operation-wise latency predictors and achieves high accuracy in end-to-end latency predictions, as shown by our comprehensive evaluations on multiple mobile devices using multicore CPUs and GPUs. To illustrate that our approach does not require expensive data collection, we also show that accurate predictions can be achieved on real-world neural architectures using only small amounts of profiling data.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5062569186', 'Maryam M. Shanechi', 'USC', 'Machine Learning', 'shanechi@usc.edu', 'Dissociative and prioritized modeling of behaviorally relevant neural dynamics using recurrent neural networks', 'Understanding the dynamical transformation of neural activity to behavior requires new capabilities to nonlinearly model, dissociate and prioritize behaviorally relevant neural dynamics and test hypotheses about the origin of nonlinearity. We present dissociative prioritized analysis of dynamics (DPAD), a nonlinear dynamical modeling approach that enables these capabilities with a multisection neural network architecture and training approach. Analyzing cortical spiking and local field potential activity across four movement tasks, we demonstrate five use-cases. DPAD enabled more accurate neural-behavioral prediction. It identified nonlinear dynamical transformations of local field potentials that were more behavior predictive than traditional power features. Further, DPAD achieved behavior-predictive nonlinear neural dimensionality reduction. It enabled hypothesis testing regarding nonlinearities in neural-behavioral transformation, revealing that, in our datasets, nonlinearities could largely be isolated to the mapping from latent cortical dynamics to behavior. Finally, DPAD extended across continuous, intermittently sampled and categorical behaviors. DPAD provides a powerful tool for nonlinear dynamical modeling and investigation of neural-behavioral data.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5044650311', 'Massoud Pedram', 'USC', 'Machine Learning', 'pedram@ceng.usc.edu', 'BMPQ: Bit-Gradient Sensitivity-Driven Mixed-Precision Quantization of DNNs from Scratch', 'Large DNNs with mixed-precision quantization can achieve ultra-high compression while retaining high classification performance. However, because of the challenges in finding an accurate metric that can guide the optimization process, these methods either sacrifice significant performance compared to the 32-bit floating-point (FP-32) baseline or rely on a compute-expensive, iterative training policy that requires the availability of a pre-trained baseline. To address this issue, this paper presents BMPQ, a training method that uses bit gradients to analyze layer sensitivities and yield mixed-precision quantized models. BMPQ requires a single training iteration but does not need a pre-trained baseline. It uses an integer linear program (ILP) to dynamically adjust the precision of layers during training, subject to a fixed hardware budget. To evaluate the efficacy of BMPQ, we conduct extensive experiments with VGG16 and ResNet18 on CIFAR-10, CIFAR-100, and Tiny-ImageNet datasets. Compared to the baseline FP-32 models, BMPQ can yield models that have 15.4x fewer parameter bits with negligible drop in accuracy. Compared to the SOTA “during training”, mixed-precision training scheme, our models are 2.1 x, 2.2x, and 2.9x smaller, on CIFAR-10, CIFAR-100, and Tiny-ImageNet, respectively, with an improved accuracy of up to 14.54%.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5009169058', 'Matteo Sesia', 'USC', 'Machine Learning', 'sesia@marshall.usc.edu', 'Testing for outliers with conformal p-values', 'This paper studies the construction of p-values for nonparametric outlier detection, from a multiple-testing perspective. The goal is to test whether new independent samples belong to the same distribution as a reference data set or are outliers. We propose a solution based on conformal inference, a general framework yielding p-values that are marginally valid but mutually dependent for different test points. We prove these p-values are positively dependent and enable exact false discovery rate control, although in a relatively weak marginal sense. We then introduce a new method to compute p-values that are valid conditionally on the training data and independent of each other for different test points; this paves the way to stronger type-I error guarantees. Our results depart from classical conformal inference as we leverage concentration inequalities rather than combinatorial arguments to establish our finite-sample guarantees. Further, our techniques also yield a uniform confidence bound for the false positive rate of any outlier detection algorithm, as a function of the threshold applied to its raw statistics. Finally, the relevance of our results is demonstrated by experiments on real and simulated data.', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5016868056', 'Mladen Kolar', 'USC', 'Machine Learning', 'mkolar@chicagobooth.edu', 'High-dimensional functional graphical model structure learning via neighborhood selection approach', 'Undirected graphical models are widely used to model the conditional independence structure of vector-valued data. However, in many modern applications, for example those involving EEG and fMRI data, observations are more appropriately modeled as multivariate random functions rather than vectors. Functional graphical models have been proposed to model the conditional independence structure of such functional data. We propose a neighborhood selection approach to estimate the structure of Gaussian functional graphical models, where we first estimate the neighborhood of each node via a function-on-function regression and subsequently recover the entire graph structure by combining the estimated neighborhoods. Our approach only requires assumptions on the conditional distributions of random functions, and we estimate the conditional independence structure directly. We thus circumvent the need for a well-defined precision operator that may not exist when the functions are infinite dimensional. Additionally, the neighborhood selection approach is computationally efficient and can be easily parallelized. The statistical consistency of the proposed method in the high-dimensional setting is supported by both theory and experimental results. In addition, we study the effect of the choice of the function basis used for dimensionality reduction in an intermediate step. We give a heuristic criterion for choosing a function basis and motivate two practically useful choices, which we justif', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5040786186', 'Mohammad Rostami', 'USC', 'Machine Learning', 'rostamim@usc.edu', 'Identification of Novel Classes for Improving Few-Shot Object Detection', 'Conventional training of deep neural networks requires a large number of the annotated image which is a laborious and time-consuming task, particularly for rare objects. Few-shot object detection (FSOD) methods offer a remedy by realizing robust object detection using only a few training samples per class [16], [37], [36], [8], [48], [15]. A challenge for FSOD is that instances from unlabeled novel classes that do not belong to the fixed set of training classes appear in the background. These objects behave similarly to label noise, leading to FSOD performance degradation. We develop a semi-supervised algorithm to detect and then utilize these unlabeled novel objects as positive samples during training to improve FSOD performance. Specifically, we propose a hierarchical ternary classification region proposal network (HTRPN) to localize the potential unlabeled novel objects and assign them new objectness labels. Our improved hierarchical sampling strategy for the region proposal network (RPN) also boosts the perception ability of the object detection model for large objects. Our experimental results indicate that our method is effective and outperforms the existing state-of-the-art (SOTA) FSOD methods https://github.com/zshanggu/HTRPN', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5084205024', 'Peter A. Beerel', 'USC', 'Machine Learning', 'pabeerel@usc.edu', 'Self-Attentive Pooling for Efficient Deep Learning', 'Efficient custom pooling techniques that can aggressively trim the dimensions of a feature map for resource-constrained computer vision applications have recently gained significant traction. However, prior pooling works extract only the local context of the activation maps, limiting their effectiveness. In contrast, we propose a novel non-local self-attentive pooling method that can be used as a drop-in replacement to the standard pooling layers, such as max/average pooling or strided convolution. The proposed self-attention module uses patch embedding, multihead self-attention, and spatial-channel restoration, followed by sigmoid activation and exponential soft-max. This self-attention mechanism efficiently aggregates dependencies between non-local activation patches during downsampling. Extensive experiments on standard object classification and detection tasks with various convolutional neural network (CNN) architectures demonstrate the superiority of our proposed mechanism over the state-of-the-art (SOTA) pooling techniques. In particular, we surpass the test accuracy of existing pooling techniques on different variants of MobileNet-V2 on ImageNet by an average of ~1.2%. With the aggressive down-sampling of the activation maps in the initial layers (providing up to 22x reduction in memory consumption), our approach achieves 1.43% higher test accuracy compared to SOTA techniques with iso-memory footprints. This enables the deployment of our models in memory-constrained de', 2023);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5069365931', 'Phebe Vayanos', 'USC', 'Machine Learning', 'phebe.vayanos@usc.edu', 'Strong Optimal Classification Trees', 'Decision trees are among the most interpretable and popular machine learning models that are used routinely in applications ranging from revenue management to medicine. Traditional heuristic methods, although fast, lack modeling flexibility for incorporating constraints such as fairness and do not guarantee optimality. Recent efforts aim to overcome these limitations using mixed-integer optimization (MIO) for better modeling flexibility and optimality, but speed remains an issue. In “Strong Optimal Classification Trees,” Aghaei, Gómez, and Vayanos use integer optimization and polyhedral theory to create an MIO-based formulation with a strong LO relaxation resulting in a 29% speed-up in training time compared with state-of-the-art MIO-based formulations, as well as up to an 8% improvement in out-of-sample accuracy.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5082235583', 'Ulrich Neumann', 'USC', 'Machine Learning', 'uneumann@usc.edu', 'Behind the Curtain: Learning Occluded Shapes for 3D Object Detection', 'Advances in LiDAR sensors provide rich 3D data that supports 3D scene understanding. However, due to occlusion and signal miss, LiDAR point clouds are in practice 2.5D as they cover only partial underlying shapes, which poses a fundamental challenge to 3D perception. To tackle the challenge, we present a novel LiDAR-based 3D object detection model, dubbed Behind the Curtain Detector (BtcDet), which learns the object shape priors and estimates the complete object shapes that are partially occluded (curtained) in point clouds. BtcDet first identifies the regions that are affected by occlusion and signal miss. In these regions, our model predicts the probability of occupancy that indicates if a region contains object shapes and integrates this probability map with detection features and generates high-quality 3D proposals. Finally, the occupancy estimation is integrated into the proposal refinement module to generate accurate bounding boxes. Extensive experiments on the KITTI Dataset and the Waymo Open Dataset demonstrate the effectiveness of BtcDet. Particularly for the 3D detection of both cars and cyclists on the KITTI benchmark, BtcDet surpasses all of the published state-of-the-art methods by remarkable margins. Code is released.', 2022);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5033166029', 'Viktor K. Prasanna', 'USC', 'Machine Learning', 'prasanna@usc.edu', 'Benchmarking Edge AI Platforms for High-Performance ML Inference', 'Edge computing''s growing prominence, due to its ability to reduce communication latency and enable real-time processing, is promoting the rise of high-performance, heteroge-neous System-on-Chip solutions. While current approaches often involve scaling down modern hardware, the performance characteristics of neural network workloads on these platforms can vary significantly, especially when it comes to parallel processing, which is a critical consideration for edge deployments. To address this, we conduct a comprehensive study comparing the latency and throughput of various linear algebra and neural network inference tasks across CPU-only, CPU/GPU, and CPU/NPU integrated solutions. We find that the Neural Processing Unit (NPU) excels in matrix-vector multiplication (58.6% faster) and some neural network tasks (3.2 ×faster for video classification and large language models). GPU outperforms in matrix multiplication (22.6% faster) and LSTM networks (2.7× faster) while CPU excels at less parallel operations like dot product. NPU-based inference offers a balance of latency and throughput at lower power consumption. GPU-based inference, though more energy-intensive, performs best with large dimensions and batch sizes. We highlight the potential of heterogeneous computing solutions for edge AI, where diverse compute units can be strategically leveraged to boost accurate and real-time inference.', 2024);
INSERT INTO public.professors_cache (openalex_id, name, institution, topic, email, latest_paper_title, latest_paper_abstract, latest_paper_year) VALUES ('A5057711796', 'Yue Zhao', 'USC', 'Machine Learning', 'yue.z@usc.edu', 'PyOD 2: A Python Library for Outlier Detection with LLM-powered Model Selection', 'Outlier detection (OD), or anomaly detection, is essential in data analysis and machine learning. The Python Outlier Detection (PyOD) library is the most popular open-source tool for OD-with over 8,500 GitHub stars and 25 million downloads-but it has three limitations: (1) limited modern deep learning algorithms, (2) fragmented PyTorch and TensorFlow implementations, and (3) no automated model selection, which challenges non-experts. To overcome these issues, we introduce PyOD Version 2 (øurs), which integrates 10 state-of-the-art deep learning models into a unified PyTorch framework and adds an LLM-based pipeline for automated model selection. These enhancements streamline OD workflows, offer access to 45 algorithms, and deliver robust performance across various datasets. In this paper, we demonstrate how øurs simplifies the deployment and automation of OD models, setting a new standard in research and industry. øurs is available at https://github.com/yzhao062/pyod.', 2025);
